SELECT 'moj-all-verified-judgments-review-002-chunk-104' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"4f62670e-3282-5fe6-ade2-473ad1e7ea7a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش -تعاطي حبوب اإلمفيتامن -ثبوت تعاطي احلشيش املخدر -إقامة حد املسكر -منع املدعى عليه من السفر -اإلقرار .","document_number":"34277360","case_number":"3466","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/24","year":"1434","subject":"مخدرات -تعاطي احلشيش -تعاطي حبوب اإلمفيتامن -ثبوت تعاطي احلشيش املخدر -إقامة حد املسكر -منع املدعى عليه من السفر -اإلقرار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪34277360:‬تاريخه‪1434/07/24 :‬هـ‬\n                             ‫رقم الدعوى‪3466:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪   34301297‬تاريخه‪1434/8/21:‬هـ‬\n\n\n    ‫مخــدرات ‪ -‬تعاطــي احلشــيش ‪ -‬تعاطــي حبــوب اإلمفيتامــن ‪ -‬ثبــوت‬\n    ‫تعاطــي احلشــيش املخــدر ‪ -‬إقامــة حــد املســكر ‪ -‬منــع املدعــى عليــه مــن‬\n                                                                  ‫الســفر ‪ -‬اإلقــرار ‪.‬‬\n\n\n\n    ‫‪-1‬القاعــدة الفقهيــة ( املــرء مؤاخــذ بإقــراره ) والقاعــدة ( إقــرار اإلنســان‬\n    ‫على نفســه مقبول ) املنثور من القواعد للزركشــي (‪ )188/1‬واألشــباه‬\n                             ‫والنظائر للسيوطي (‪ )465/1‬ودرر احلكام (‪)79/1‬‬\n                 ‫‪-2‬الفقرة الثانية من املادة (‪ )3‬من نظام مكافحة املخدرات‬\n                ‫‪-3‬الفقرة األولى من املادة (‪ )56‬من نظام مكافحة املخدرات‬\n\n\n\n\n    ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n    ‫واحلبــوب احملظــورة وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم‬\n    ‫عليــه بالعقوبــة الــواردة مــن نظــام مكافحــة املخــدرات‪ ،‬اســتند املدعــي‬\n    ‫العــام يف دعــواه علــى ‪ :‬اعتــراف املدعــى عليــه مبــا أســند إليــه مبحضــر‬\n    ‫القبــض وبتحليــل عينــه مــن ســوائله أثبــت تقريــر الســموم الشــرعي‬\n    ‫إيجابيتهــا ملــادة احلشــيش املخــدر و مــادة اإلمفيتامــن وأقــر املدعــى عليــه‬\n    ‫بتعاطــي احلشــيش و حبــوب اإلمفيتامــن بنــاء علــى مــا تقــدم حكمــت‬\n‫‪5‬‬\n\f‫احملكمــة بثبــوت تعاطــي املدعــى عليــه للحشــيش املخــدر و جلــده حــد‬\n‫املســكر ثمانــن جلــده دفعــة واحــدة ‪ ،‬ثبــت تعاطيــه للحبــوب احملظــورة‬\n‫و االكتفــاء بحــد املســكر وصــرف النظــر عــن طلــب املدعــي العــام‬\n‫تطبيــق العقوبــه الــواردة يف (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n‫املخــدرات وذلــك اكتفــاء بإقامــة حــد املســكر ‪ ،‬منــع املدعــى عليــه مــن‬\n‫الســفر ملــدة ســنتني وال يغــادر وأخــذ التعهــد الشــديد علــى املدعــى عليــه‬\n‫بعــدم تكــرار مابــدر منــه وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                    ‫‪6‬‬\n\f    ‫احلمــدهلل وحــده وبعــد فلــدي أنــا املــازم القضائــي باحملكمــة اجلزائيــة‬\n    ‫باألحســاء يف املكتــب القضائــي الســادس وبنــاء علــى املعاملــة احملالــة‬\n    ‫من رئيس احملكمة اجلزائية باألحســاء برقم (‪ ).........‬يف ‪1434/1/3‬هـ‬\n    ‫واملقيــدة برقــم (‪ )........‬يف ‪1434/1/3‬ه ـ وبنــاء علــى تعميــدي مــن فضيلة‬\n    ‫الشــيخ‪ /‬رئيــس احملكمــة اجلزائيــة باألحســاء املكلــف مبوجــب خطابــه‬\n    ‫رقــم (‪ )................‬يف ‪1434/6/26‬هــ  لنظــر القضايــا مــا عــدا الســجناء‬\n    ‫ويف يــوم الثالثــاء املوافــق ‪1434/7/18‬ه ـ افتتحــت اجللســة األولــى يف‬\n    ‫متــام الســاعة احلاديــة عشــر صباحـ ًا يف هــذه القضيــة رقــم (‪ )........‬وفيهــا‬\n    ‫حضــر املدعــي العــام الســعودي بالســجل املدنــي رقــم (‪ ).............‬وحضــر‬\n    ‫حلضــوره املدعــى عليــه الســعودي بالســجل املدنــي رقــم (‪ )...............‬وبنــاء‬\n    ‫علــى األوراق املثبتــة يف املعاملــة بــأن املدعــى عليــه مطلــق ســراحه لــذا‬\n    ‫فقــد قــررت نظــر الدعــوى هــذا فتــم ســؤال املدعــي العــام عــن دعــواه‬\n    ‫قــال بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء‬\n    ‫أدعــي علــى ‪ /‬البالــغ مــن العمــر (‪ )...‬عام ـ ًا ســعودي اجلنســية مبوجــب‬\n    ‫الســجل املدنــي رقــم (‪ ).............‬متســبب محصــن قبــض عليــه بتاريــخ‬\n    ‫‪1433/11/20‬ه ـ وأوقــف مبوجــب أمــر اإليقــاف الصــادر مــن دائــرة‬\n    ‫التحقيــق واالدعــاء العــام مبحافظــة األحســاء برقــم (ه ـ ق ‪)......././.‬‬\n    ‫وتاريــخ ‪1433/11/21‬ه ـ وفق ـ ًا لبرقيــة وزيــر الداخليــة رقــم (‪/5/1‬‬\n    ‫‪ )..............‬وتاريــخ ‪1432/12/20‬ه ـ وجــرى التمديــد لــه ملــدة (‪ )25‬يومـ ًا‬\n    ‫بأمــر التمديــد الصــادر مــن فــرع الهيئــة باملنطقــة الشــرقية برقــم (ه ـ ق‬\n    ‫‪ )55766/5/1‬يف ‪1433/11/27‬ه ـ وأحيــل إلــى شــعبة ســجن محافظــة‬\n\n‫‪7‬‬\n\f‫األحســاء أنــه بتاريــخ ‪1433/11/20‬ه ـ مت القبــض عليــه مــن قبــل مركز‬\n‫شــرطة التابعــة حملافظــة األحســاء بقضيــة قفــز علــى منــزل (فــرزت لهــا‬\n‫أوراق مســتقلة ومعاجلتهــا مــن قبــل جهــة االختصــاص وبتحليــل عينــة مــن‬\n‫ســوائله أثبــت التقريــر الســموم الشــرعي رقــم (‪........‬م أ) لعــام ‪1433‬ه ـ‬\n‫إيجابيتهــا ملــادة احلشــيش املخــدر واملــدرج يف اجلــدول (‪ )1‬فئــة (أ) ومــادة‬\n‫االمفيتامــن احملظــور واملــدرج يف اجلــدول (‪ )2‬فئــة (ب) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة وبضبــط أقــوال املدعــى عليــه‬\n‫‪ /‬أقــر بتعاطــي احلشــيش املخــدر وحبــوب األمفيتامــن املنبــه احملظــور‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بتعاطــي احلشــيش املخــدر‬\n‫واحلبــوب احملظــورة وذلــك لألدلــة والقرائــن التاليــة ‪ -1‬اعترافــه املنــوه‬\n‫عنــه املــدون علــى الصفحــة رقــم (‪ )2‬مــن دفتــر االســتدالل لفــه رقــم (‪)10‬‬\n‫‪ -2‬مــا جــاء يف محضــر القبــض املــدون علــى الصفحــة رقــم (‪ )11‬مــن‬\n‫دفتــر االســتدالل لفــه رقــم (‪ -3 )3‬مــا جــاء يف خطــاب مديــر مركــز‬\n‫شــرطة العيــون املرفــق لفــة رقــم (‪ -4 )3‬مــا جــاء يف التقريــر الســموم‬\n‫الشــرعي املرفــق علــى اللفــة رقــم (‪ )2‬وبالبحــث عمــا إذا كان لــه‬\n‫ســوابق تبــن وجــود ســابقتني األولــى مضاربــة والثانيــة حيــازة واســتعمال‬\n‫مخــدرات بتاريــخ ‪1431/3/7‬ه ـ وحيــث إن مــا أقــدم عليــه املذكــور‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم‬\n‫(م‪ )39/‬تاريــخ ‪1426/7/8‬ه ـ أطلــب أثبــات مــا أســند إليــه واحلكــم عليه‬\n‫مبــا يلــي ‪ -1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة رقــم (‪ )41‬مــن‬\n                                                   ‫النظــام املشــار إليــه لقــاء مــا‬\n\n\n                                                                                          ‫‪8‬‬\n\f    ‫أســند إليــه مــن اتهــام ‪ -2‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة‬\n    ‫(‪ )56‬مــن النظــام مبنعــه مــن الســفر ‪ .‬هــذه دعــواي وبســؤال املدعــى عليــه‬\n    ‫عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام مــن‬\n    ‫قيامــي بتعاطــي احلشــيش املخــدر واحلبــوب احملظــورة فصحيــح وأنــا‬\n    ‫تائــب إلــى اهلل ونــادم علــى مــا بــدر منــي هــذه إجابتــي هــذا فتــم ســؤاله‬\n    ‫عــن عمــره فقــال أبلــغ مــن العمــر ثالثــن عامــا هكــذا قــال كمــا مت‬\n    ‫ســؤاله عــن عملــه فقــال أعمــل يف شــركة الغــاز هكــذا قــال كمــا مت‬\n    ‫ســؤاله هــل أنــت محصــن ولديــك أطفــال فقــال نعــم هكــذا قــال هــذا‬\n    ‫فتــم اطالعــي علــى شــهادة ســوابق املدعــى عليــه املرفقــة يف املعاملــة علــى‬\n    ‫اللفــة رقــم (‪ )22‬وتتضمــن (وجــود ســابقة واحــدة وهــي ســرقة حيوانــات)‬\n    ‫أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه قــال الســابقة صحيحــة وقــد أخــذت‬\n    ‫جزائــي عليهــا هكــذا قــال كمــا مت اطالعــي تقريــر الســموم الشــرعي‬\n    ‫املرفــق يف املعاملــة علــى اللفــة رقــم (إيجابيــة عينــة البــول ملركبــات‬\n    ‫احلشــيش املخــدر وملركــب اإلمفيتامني)أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن‬\n    ‫الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بدعــوى املدعــي العــام‬\n    ‫ولكــون هــذا اإلقــرار قــد صــدر مــن مكلــف ‪ -‬عاقــل بالــغ‪ -‬وللقاعــدة‬\n    ‫الفقهيــة ((أن املــرء مؤاخــذ بإقــراره)) والقاعــدة ((إقــرار اإلنســان علــى‬\n    ‫نفســه مقبــول)) املنثــور مــن القواعــد للزركشــي [ج‪ ]188/1‬واألشــباه‬\n    ‫والنظائــر للســيوطي [ج‪ ]465/1‬ودرر احلــكام [ج‪ ]79/1‬وبعــد االطــاع‬\n    ‫علــى تقريــر الســموم الشــرعي لذلــك كلــه‪ :‬أوال‪ :‬ثبــت لــدي تعاطــي‬\n    ‫املدعــى عليــه للحشــيش املخــدر وقــررت جلــده حــد املســكر ثمانــن‬\n    ‫جلــدة حــدا دفعــة واحــدة علن ـاً‪ .‬ثانيــا‪ :‬ثبــت لــدي تعاطــي املدعــى عليــه‬\n    ‫للحبــوب احملظــورة واكتفيــت مبــا مت احلكــم عليــه يف الفقــرة أوال‪.‬‬\n\n\n‫‪9‬‬\n\f‫ثالثــا‪ :‬صرفــت النظــر عــن طلــب املدعــي العــام مــن تطبيــق العقوبــة‬\n‫علــى املدعــى عليــه الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات وذلــك اكتفــاء مبــا مت احلكــم عليــه يف الفقــرة‬\n‫أوال‪ .‬رابعــا‪ :‬ونظــرا لثبــوت تعاطــي املدعــى عليــه للحشــيش املخــدر‬\n‫واحلبــوب احملظــورة وهــذه اجلرميتــان نصــت عليهــا الفقــرة الثانيــة مــن‬\n‫املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات وبنــاء علــى الفقــرة األولــى‬\n‫مــن املــادة (‪ )56‬مــن نفــس النظــام لــذا فقــد قــررت منــع املدعــى عليــه‬\n‫مــن الســفر خــارج اململكــة ملــدة ســنتني وال يغــادر اململكــة لضــرورة إال‬\n‫بــأذن مــن وزيــر الداخليــة‪ .‬خامســا‪ :‬أخــذ التعهــد الشــديد علــى املدعــى‬\n‫عليــه بعــدم تكــرار مــا بــدر منــه ومبــا ســبق كلــه حكمــت وبعرضــه‬\n‫علــى املدعــى عليــه قــرر القناعــة بــه كمــا قــرر املدعــي العــام املعارضــة‬\n‫عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة اعتراضيــة‬\n‫وبذلــك تكــون القضيــة منتهيــة وعليــه فقــد قــررت بعــث كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف بالشــرقية لتدقيــق احلكــم حســب املتبــع‬\n‫وبــاهلل التوفيــق واختتمــت اجللســة يف متــام الســاعة التاســعة وللبيــان حــرر‬\n‫يف  ‪1434/7/18‬ه ـ ـ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                         ‫وســلم تســليما كثيــرا‪.‬‬\n‫     احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/1942831‬ج‪ 2‬وتاريــخ ‪1434/08/10‬ه ـ‬\n‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف برقــم ‪ 341669167‬وتاريــخ ‪1434/08/03‬ه ـ املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ‪/‬‬\n\n\n                                                                                      ‫‪10‬‬\n\f     ‫املســجل برقــم وتاريــخ ‪1434/07/24‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام  ‬\n       ‫ضد‪/‬املدعــى عليــه يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه  ‬\n       ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n           ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/21‬هــ‪.‬‬\n\n\n\n\n‫‪11‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":5,"source_page_end":11,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"67520a4d0c60faf66433843c43a32554f57300477f5a4a19c2ccdffaf66e8afd","normalized_text_hash":"86edc488829229717829fe57eb0d809cf49d539b1bac73a26a94a0436ddbc300","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p5-34277360"},{"id":"45eb5959-21ea-5d13-88be-10385855e96e","document_type":"judgment","category":"judicial","subcategory":"general","title":"تعاطي الشمة -ترويج الشمة -ترويج واستعمال مقاطع جنسية - عدم اكتمال نصاب الشهادة ال يثبت به الواقعة اجلنائية إال أنها قرينة مورثة للتهمة ( الشبهة ) املوجبة للتعزير -التعزير بالسجن واجللد -صرف النظر عن املصادرة والغرامة لعدم ثبوت اإلدانة.","document_number":"34440072","case_number":"349674","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"تعاطي الشمة -ترويج الشمة -ترويج واستعمال مقاطع جنسية - عدم اكتمال نصاب الشهادة ال يثبت به الواقعة اجلنائية إال أنها قرينة مورثة للتهمة ( الشبهة ) املوجبة للتعزير -التعزير بالسجن واجللد -صرف النظر عن املصادرة والغرامة لعدم ثبوت اإلدانة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 34440072:‬تاريخه‪1434/2/23 :‬هـ‬\n                        ‫رقم الدعوى‪349674 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n     ‫تاريخه‪1434/7/5 :‬هـ‬         ‫‪34260338‬‬\n\n\n\n‫تعاطــي الشــمة ‪ -‬ترويــج الشــمة ‪ -‬ترويــج واســتعمال مقاطــع جنســية ‪-‬‬\n‫عــدم اكتمــال نصــاب الشــهادة ال يثبــت بــه الواقعــة اجلنائيــة إال أنهــا‬\n‫قرينــة مورثــة للتهمــة ( الشــبهة ) املوجبــة للتعزيــر ‪ -‬التعزيــر بالســجن‬\n    ‫واجللــد ‪ -‬صــرف النظــر عــن املصــادرة والغرامــة لعــدم ثبــوت اإلدانــة‪.‬‬\n\n\n\n\n                                     ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بحيــازة كميــة‬\n‫كبيــرة مــن الشــمة بقصــد الترويــج والتعاطــي وحيــازة صــور ومقاطــع‬\n‫جنســية وتخزينهــا يف جهــازي احلاســب اآللــي وجهــاز اجلــوال بقصــد‬\n‫الترويــج وطلــب إثبــات ذلــك ‪ ،‬ورد بــاغ لهيئــة األمــر باملعــروف والنهــي‬\n‫عــن املنكــر عــن قيامــه بذلــك خــال عملــه مبحــل بيــع اجلــوالت فجــرى‬\n‫االنتقــال للمحــل فعثــر بحوزتــه مــادة الشــمة معــدة للبيــع ويف جهــازه‬\n‫احلاســوب مقاطــع إباحيــة ‪ ،‬أنكــر املدعــى عليــه التهــم املوجهــة إليــه‬\n‫ودفــع بأنــه يعمــل يف محــل بيــع وصيانــة أجهــزة اجلــوال وقــد حضــر لديــه‬\n‫مجموعــة مــن املعتمريــن ووضعــوا أكياســا لهــم يف احملــل وكانــت هــذه‬\n‫الشــمة داخــل األكيــاس وال عالقــة لــه بهــا كمــا أنكــر بــأن جهــاز‬\n\n                                                                                   ‫‪12‬‬\n\f     ‫احلاســب اآللــي احملمــول واجلــوال يعــودان لــه وقــرر بــأن اجلهــاز احملمــول‬\n     ‫تركــه عميــل عنــده إلصالحــه‪ ،‬أحضــر املدعــي العــام شــاهدا يعمــل‬\n     ‫عضــوا يف هيئــة األمــر باملعــروف والنهــي عــن املنكــر وشــهد بأنــه ورد‬\n     ‫بــاغ أن املدعــى عليــه يقــوم ببيــع مادة الشــمة فانتقل مــع الفرقة القابضة‬\n     ‫للمحــل فعثــر حتــت الطاولــة املعــروض فيهــا األجهــزة كيســا يحتــوي‬\n     ‫علــى (‪ )248‬كيــس صغيــر بــه مــادة الشــمة كمــا عثــر بحوزتــه جهــاز‬\n     ‫حاســب آلــي محمــول يحتــوي علــى مقاطــع مرئيــة جنســية وعثــر معــه‬\n     ‫علــى جهــاز جــوال يحتــوي علــى صــور جنســية ‪ ،‬جــرى عــرض الشــاهد‬\n     ‫وشــهادته علــى املدعــى عليــه فقــرر بأنــه ال يعلــم عــن الشــاهد شــيئا أمــا‬\n     ‫شــهادته فالصحيــح مــا ورد يف جوابــه ‪ ،‬طلــب مــن املدعــي العــام إحضــار‬\n     ‫زيــادة بينــة فطلــب مهلــة ‪ ،‬ثــم قــرر املدعــي العــام بأنــه طلــب البينــة أكثــر‬\n     ‫مــن مــرة فلــم حتضــر وطلــب احلكــم بالقضيــة اكتفــاء بشــهادة الشــاهد‬\n     ‫ومــا ورد يف أوراق املعاملــة ‪ ،‬جــرى الرجــوع ألوراق املعاملــة فعثــر علــى‬\n     ‫اعتــراف للمدعــى عليــه حتقيقــا بتعاطــي الشــمة ‪ ،‬وإلنــكار املدعــى‬\n     ‫عليــه وملــا دفــع بــه ‪ ،‬وبنــاء علــى شــهادة الشــاهد ‪ ،‬ونظــرا لتوجــه الشــبهة‬\n     ‫جتــاه املدعــى عليــه ولعــدم وجــود ســوابق مســجلة عليــه فقــد قــررت‬\n     ‫احملكمــة عــدم ثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه بالدعــوى‬\n     ‫وقــررت للشــبهة جتاهــه ســجنه شــهرين يحســب منهــا املــدة التــي أوقــف‬\n     ‫فيهــا ألجــل القضيــة وجلــده ســتون جلــدة دفعــة واحــدة ولــم حتكــم‬\n     ‫باملصــادرة وال الغرامــة لعــدم ثبــوت التهمــة‪ ،‬بعــرض احلكــم عليهمــا‬\n     ‫قــررا االعتــراض عليــه وأفهمــا بتعليمــات االســتئناف ‪ ،‬قــدم املدعــى‬\n     ‫عليــه الئحــة اعتراضيــة بينمــا لــم يقــدم املدعــي العــام بعــد مضــي املــدة‬\n     ‫املقــررة لــذا جــرى رفــع احلكــم حملكمــة االســتئناف ‪ ،‬صــدق احلكــم‬\n\n\n‫‪13‬‬\n\f                                                    ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد يف يــوم‬\n‫الثالثــاء املوافــق ‪1433/1/28‬هــ  لــدي أنــا ‪...........‬القاضــي يف احملكمة‬\n‫ـاء على املعاملــة احملالة من رئيس احملكمة‬       ‫اجلزائيــة مبكــة املكرمــة بنـ ً‬\n‫برقــم ‪ 332077757‬وتاريــخ ‪1433/11/21‬ه ـ فتحــت اجللســة الســاعة‬\n‫الثانيــة عشــرة وثالثــون دقيقــة وفيهــا حضــر املدعــي العــام ‪...........‬وادعــى‬\n‫قائــا يف دعــواه أدعــي علــى هــذا احلاضــر معــي باملجلــس الشــرعي‪/‬‬\n‫‪......................‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...........‬أن‬\n‫التحقيــق يدينــه بحيــازة كميــة كبيــرة مــن مــادة الشــمة بقصــد الترويــج‬\n‫والتعاطــي وحيــازة صــور ومقاطــع جنســية وتخزينهــا يف جهــازي احلاســب‬\n‫اآللــي وجهــاز جوالــه لغــرض الترويــج ‪ ،‬أطلــب إثبــات ذلــك واحلكــم عليه‬\n‫بعقوبــة تعزيريــة لقــاء ترويجــه وتعاطيــه مــادة الشــمة وحيازتــه لهــا لغــرض‬\n‫الترويــج والســجن والغرامــة وفقــا للفقــرة (‪ )1‬مــن املــادة (‪ )6‬مــن نظــام‬\n‫مكافحــة اجلرائــم املعلوماتيــة الصــادر باملرســوم امللكــي رقــم (‪)79‬‬\n‫وتاريــخ ‪1428/3/7‬ه ـ ومبصــادرة جهــاز اجلــوال مــن نــوع ‪ .......‬ورقمــه‬\n‫املصنعــي (‪ ).......‬وجهــاز الالبتــوب مــن نــوع ‪ .....‬ورقمــه املصنعــي ‪.......‬‬\n‫وفقــا للمــادة (‪ )13‬مــن نظــام املشــار إليــه ‪ ،‬وبســؤال املدعــى عليــه عــن‬\n‫الدعــوى أجــاب قائـاً‪ :‬مــا ذكــره املدعــي العــام مــن حيازتــي مادة الشــمة‬\n‫بقصــد الترويــج والتعاطــي وحيازتــي صــور ًا ومقاطــع جنســية وتخزينهــا‬\n‫يف جهــاز حاســب آلــي وجهــاز جــوال عائديــن لــي لغــرض الترويــج غيــر‬\n‫صحيــح والصحيــح هــو أنــي أعمــل يف محــل لبيــع وصيانــة أجهــزة اجلــوال‬\n\n                                                                                       ‫‪14‬‬\n\f     ‫وقــد حضــر لــدي مجموعــة مــن املعتمريــن ووضعــوا أكياس ـ ًا لهــم لــدي‬\n     ‫يف احملــل وكانــت هــذه الشــمة داخــل هــذه األكيــاس وال عالقــة لــي‬\n     ‫بهــا وأمــا الصــور واملقاطــع اجلنســية التــي يف احلاســب اآللــي فقــد أحضــر‬\n     ‫هــذا اجلهــاز رجــل يطلــب منــي فحــص اجلهــاز وذهــب بعــد ذلــك وال عالقــة‬\n     ‫لــي بهــذا احلاســب اآللــي ومــا يحتويــه وأمــا جهــاز اجلــوال الــذي يحتــوي‬\n     ‫علــى مــا ذكــر فليــس عائــد ًا لــي هكــذا أجــاب ثــم ســألت املدعــي العــام‬\n     ‫بينتــه فقــال أطلــب إمهالــي إلحضارهــا هكــذا أجــاب لــذا قــررت رفــع‬\n     ‫اجللســة لذلــك  ويف يــوم الثالثــاء املوافــق ‪1434/1/6‬ه ـ فتحــت اجللســة‬\n     ‫الســاعة العاشــرة وفيهــا حضــر املدعــى عليــه كمــا حضــر يف اجللســة‬\n     ‫‪......................‬ســعودي بالســجل املدنــي رقــم ‪...........‬وبســؤاله عمــا لديــه‬\n     ‫مــن شــهادة قــال ‪ :‬أعمــل عضــوا يف هيئــة األمــر باملعــروف والنهــي عــن‬\n     ‫املنكــر وأشــهد هلل تعالــى أنــه وردنــا مــا يفيــد أن املدعــى عليــه يعمــل‬\n     ‫مبحــل لبيــع اجلــواالت وأنــه يقــوم ببيــع مــادة الشــمة عنــد ذلــك انتقلــت‬\n     ‫رفــق الفرقــة القابضــة للمحــل ووجــدت حتــت الطاولــة املعــروض فيهــا‬\n     ‫أجهــزة اجلــوال كيس ـ ًا يحتــوي علــى (‪ )248‬كيس ـ ًا صغيــر ًا بــه مــادة‬\n     ‫الشــمة كمــا وجــدت بحوزتــه جهــاز حاســب آلــي محمــول يحتــوي علــى‬\n     ‫مقاطــع فيديــو جنســية وكذلــك عثــر معــه علــى جهــاز جوالــه يحتــوي‬\n     ‫أيضـ ًا علــى صــور جنســية هــذا مــا لــدي وبــه أشــهد جــرى عــرض الشــاهد‬\n     ‫وشــهادته علــى املدعــى عليــه فقــال أمــا هــو  فــا أعلــم عنــه شــيئ ًا وأمــا‬\n     ‫شــهادته فالصحيــح مــا ذكرتــه يف إجابتــي يف اجللســة املاضيــة هكــذا‬\n     ‫أجــاب ثــم ســألت املدعــي العــام زيــادة بينــة علــى دعــواه فقــال أطلــب‬\n     ‫إمهالــي إلحضارهــا هكــذا أجــاب لــذا قــررت رفــع اجللســة لذلــك ويف‬\n     ‫يــوم الثالثــاء املوافــق ‪1434/2/19‬ه ـ فتحــت اجللســة الســاعة العاشــرة‬\n\n\n‫‪15‬‬\n\f‫وأربعــون دقيقــة وفيهــا حضــر املدعــى عليــه وجــرى ســؤال املدعــي العــام‬\n‫عــن بينتــه التــي اســتمهل ألجلهــا فقــال مت طلــب البينة ثالث مرات حســب‬\n‫صــور طلبــات حضورهــم املرفقــة ولــم يحضــر منهــم إال شــاهد واحــد‬\n‫أطلــب احلكــم يف القضيــة هكــذا أجــاب اطلعــت بعــد ذلــك علــى أوراق‬\n‫املعاملــة فوجــدت ضمنهــا محضــر االطــاع واملعاينــة املرفــق لفــة رقــم‬\n‫(‪)18‬صحيفــة رقــم (‪ )4‬وإقــراره حتقيقـ ًا بتعاطــي الشــمة املرفــق لفــة رقــم‬\n‫(‪ )18‬صحيفــة رقــم (‪ )2‬وهمــا كمــا ذكــر املدعــي العــام فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واجلــواب وإنــكار املدعــى عليــه دعــوى املدعــي العــام‬\n‫ومــا دفــع بــه ســلف ًا وبنــاء علــى مــا تضمنتــه شــهادة الشــاهد املرصــودة‬\n‫ســلف ًا وكونــه عضــو ًا يف هيئــة األمــر باملعــروف والنهــي عــن املنكــر وال‬\n‫بينــة للمدعــي العــام علــى دعــواه إال هــذا الشــاهد ونظــر ًا لتوجــه الشــبهة‬\n‫جتــاه املدعــى عليــه وال ســوابق عليــه ولــكل مــا تقــدم لــم يثبــت لــدي‬\n‫إدانــة املدعــى عليــه مبــا نســب إليــه يف دعــوى املدعــي العــام وحكمــت‬\n‫علــى املدعــى عليــه لقــاء توجــه الشــبهة جتاهــه بســجنه مــدة شــهرين‬\n‫يحتســب منهــا مــدة إيقافــه بســبب هــذه القضيــة وجلــده ســتون جلــدة‬\n‫دفعــة واحــدة وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر‬\n‫املدعــي العــام اعتراضــه عليــه بالئحــة اعتراضيــة وقــرر املدعــى عليــه‬\n‫اعتراضــه عليــه بالئحــة اعتراضيــة جــرى إفهامــه مبراجعــة احملكمــة‬\n‫يــوم الثالثــاء املوافــق ‪1434/2/26‬ه ـ الســتالم صــورة مــن إعــام احلكــم‬\n‫وتقــدمي الئحتــه االعتراضيــة عليهــا خــال ثالثــن يوم ـ ًا فــإن تأخــر عــن‬\n‫ذلــك ســقط حقــه يف تقــدمي االعتــراض وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن جــرى النطــق باحلكــم‬\n                               ‫الســاعة احلاديــة عشــرة بتاريــخ ‪1434/2/19‬ه ـ‬\n\n\n                                                                                      ‫‪16‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة‬\n     ‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 349674‬وتاريــخ‬\n     ‫‪1434/01/06‬هــ   املقيــدة باحملكمــة برقــم ‪ 3444007‬وتاريــخ‬\n     ‫‪1434/1/6‬هــ  ففــي يــوم  االثنــن املوافق‪1434/03/02‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة الثامنــة وفيهــا حضــر املدعــى عليــه ‪...........‬املذكــور‬\n     ‫واســتلم صــورة مــن إعــام احلكــم الصــادر منــا برقــم ‪ 3444072‬وتاريــخ‬\n     ‫‪1434/02/23‬ه ـ وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n     ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/2‬ه ـ ويف يــوم االثنــن املوافــق‬\n     ‫‪1434/5/13‬ه ـ فتحــت اجللســة الســاعة التاســعة وعشــرين دقيقــة‬\n     ‫وقــد قــدم املدعــى عليــه الئحتــه االعتراضيــة جــرى إرفاقهــا باملعاملــة‬\n     ‫وباالطــاع عليهــا لــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه ولــم يقــدم‬\n     ‫املدعــي العــام الئحتــه االعتراضيــة وقــد مضــت املــدة النظاميــة لذلــك لذا‬\n     ‫قــررت رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق‬\n     ‫حــرر الســاعة التاســعة وخمــس وعشــرين دقيقــة بتاريــخ ‪1434/5/13‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل  وبعــد ‪ ...‬نحــن رئيــس‬\n     ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة‬\n     ‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪3444072‬‬\n     ‫وتاريــخ ‪1434/2/23‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ .........../‬القاضــي‬\n     ‫باحملكمــة اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n     ‫ضــد‪........... /‬مينــي اجلنســية‪ ،‬املتهــم بحيــازة مــادة الشــمة بقصــد الترويــج‬\n     ‫والتعاطــي وحيــازة صــور ومقاطــع جنســية ‪ ،‬احملكــوم فيــه مبــا دون‬\n     ‫باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n\n\n‫‪17‬‬\n\f‫باألكثريــة  املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪18‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":12,"source_page_end":18,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9a8fe4f9783a518d0ed056efb021ec1b81101f42d6383272a8def7f8dd952385","normalized_text_hash":"a576eaf3740349fe39559c5038b5eee5b0fb80b92e5ee65d44802a181a7db324","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p12-34440072"},{"id":"ed39293a-668a-5217-bdc8-90d4ff2b3f5e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -الرجوع عن إقامة احلد -اثر املرض النفسي يف إسقاط احلد -درء احلد -التعزير باملنع من","document_number":"341083510","case_number":"3327661","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/26","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -الرجوع عن إقامة احلد -اثر املرض النفسي يف إسقاط احلد -درء احلد -التعزير باملنع من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 341083510 :‬تاريخه‪1434/06/26 :‬هـ‬\n                           ‫رقم الدعوى‪3327661 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪34274653‬تاريخه‪1434/07/22 :‬هـ‬\n\n\n     ‫مخــدرات ‪-‬تعاطــي احلشــيش املخــدر ‪ -‬الرجــوع عــن إقامــة احلــد ‪ -‬اثــر‬\n     ‫املــرض النفســي يف إســقاط احلــد ‪ -‬درء احلــد ‪ -‬التعزيــر باملنــع مــن‬\n                                                                       ‫الســفر ‪.‬‬\n\n\n\n\n     ‫ـاب‬\n      ‫نصـ ُ‬‫ال ْمـ ُـر َو ْالَ ْي ِسـ ُـر َوا َأل َ‬\n                                                ‫نــا ْ َ‬\n                                                       ‫آم ُنــو ْا ِإ َّ َ‬\n                                                                        ‫‪ -1‬قولــه تعالــى ‪َ ( :‬يــا َأ ُّي َهــا ا َّلذِ يـ َـن َ‬\n                  ‫ـوه َل َع َّل ُكـ ْـم ُت ْفل ُِحـ َ‬\n             ‫ـون )‪.‬‬                                            ‫الشـ ْي َطانِ فَ ْ‬\n                                                   ‫اج َتن ُِبـ ُ‬                   ‫َوا َأل ْز َال ُم ِر ٌْجــس ِّمـ ْـن َع َمــلِ َّ‬\n     ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم «كل مســكر خمــر وكل خمــر حــرام»‬\n                                                                                                                     ‫رواه مســلم‬\n     ‫‪ -3‬قــال ابــن حجــر‪ ( :‬اســتدل مبطلــق هــذا احلديــث علــى حتــرمي كل‬\n     ‫مــا يســكر ولــو لــم يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا )‬\n                                                                                                   ‫فتــح البــاري (‪)55/10‬‬\n                                                      ‫‪ -4‬املادة (‪ )3‬من نظام مكافحة املخدرات ‪.‬‬\n     ‫‪ -5‬قولــه صلــى اهلل عليــه وســلم ‪( :‬ادرؤوا احلــدود عــن املســلمني مــا‬\n     ‫اســتطعتم فــإن فوجــدمت للمســلم مخرج ـ ًا فخلــوا ســبيله فــإن اإلمــام‬\n     ‫ألن يخطــئ يف العفــو خيــر مــن أن يخطــئ يف العقوبــة ) اخرجــه‬\n                                                    ‫الترمــذي واحلاكــم والبيهقــي وغيرهــم ‪.‬‬\n\n\n\n\n‫‪19‬‬\n\f‫ادعــى املدعــي العــام ضــد املدعــى عليــه  بتعاطــي احلشــيش املخــدر‬\n‫وشــرب املســكر ‪ ،‬حيــث مت القبــض علــى املدعــى عليــه إثــر مشــاجرة‬\n‫وطلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه ‪ ،‬احلكــم عليــه‬\n‫بالعقوبــة الــواردة بالفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n‫املخــدرات ومنعــه مــن الســفر ‪ ،‬واحلكــم عليــه بحــد املســكر وبتحليــل‬\n‫عينــة البــول ثبتــت إيجابيتهــا ملركــب احلشــيش املخــدر‪ ،‬أقــر املدعــى‬\n‫عليــه بتعاطــي احلشــيش وأنكــر شــرب املســكر ‪ ،‬بنــاء علــى ماتقــدم‬\n‫صــدر احلكــم بإقامــة حــد املســكر واملنــع مــن الســفر ســنتني ‪ ،‬تقــدم‬\n‫والــد املدعــى عليــه باعتراضــه أن ابنــه مصــاب بانفصــام عقلــي و جــرت‬\n‫مكاتبــة املستشــفى للصحــة النفســية للتأكــد مــن ذلــك ‪ ،‬ورد اجلــواب‬\n‫بصحــة ذلــك وأن املدعــى عليــه أثنــاء ارتــكاب اجلرميــة لــم يكــن مدرك ًا‬\n‫لتصرفاتــه وأنــه ال يتحمــل اجللــد ورجــع فضيلتــه عــن حكمــه واكتفــى‬\n‫باملنــع مــن الســفر ســنة وتوبيخــه شــفهي ًا وصــدق احلكــم مــن محكمــة‬\n                                                                  ‫االســتئناف‬\n\n\n\n\n                                                                                 ‫‪20‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة اجلزئيــة مبحافظــة‬\n     ‫القطيــف   وبنــاء علــى املعاملــة احملالــة لنــا برقــم وتاريــخ ‪1433/01/10‬‬\n     ‫هــ  املقيــدة باحملكمــة برقــم  وتاريــخ ‪ 1433/01/10‬هــ  ففــي يــوم  ‬\n       ‫االثنــن املوافــق‪ 1433/01/10‬هــ  وفيهــا حضــر  املدعــي   العــام  وحضــر‬\n       ‫ا‬\n       ‫املدعــى عليــه ‪ .......‬ســعودي رقــم ســجله ملدنــي (‪ )......‬وادعــى األول قائـ ً‬\n       ‫إنــه بتاريــخ ‪1427/3/21‬ه ـ مت القبــض علــى املدعــى عليــه إثــر مضاربــة‬\n       ‫(مت معاجلــة قضيــة املضاربــة مــن قبــل جهــة االختصــاص) وبتحليــل عينــة‬\n       ‫بولــه تبــن إيجابيتهــا ملركــب احلشــيش املخــدر وفق ـ ًا لتقريــر الســموم‬\n       ‫الشــرعي رقــم (‪348‬م أ) وباســتجواب املتهــم املذكــور أقــر بصحــة‬\n       ‫واقعــة القبــض مضيفــا انــه يتعاطــى احلشــيش املخــدر ويتعاطــى الشــراب‬\n       ‫املســكر وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق‬\n       ‫مســجلة أطلــب مــن فضيلتكــم إثبــات مــا أســند إليــه وفق ـ ًا للفقــرة‬\n       ‫الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واحلكــم عليــه‬\n       ‫مبــا يلــي‪-1 :‬احلكــم عليــه بالعقوبــة الــواردة بالفقــرة (‪ )1‬مــن املــادة (‪)41‬‬\n       ‫مــن نظــام مكافحــة املخــدرات لتعاطــي احلشــيش املخدر‪-2‬منعــه مــن‬\n       ‫الســفر وفــق الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام ‪-3‬احلكــم عليــه‬\n       ‫بحــد املســكر لقــاء اعترافــه بشــرب املســكر وتعاطيــه احلشــيش‬\n       ‫املخــدر هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب قائــا مــا‬\n       ‫ذكــره املدعــي العــام مــن القبــض علــي بالتاريــخ املذكــور وأننــي كنــت‬\n       ‫متعاطي ـ ًا احلشــيش املخــدر صحيــح لكننــي ال أتعاطــى اخلمــر املســكر‬\n       ‫وقــد خضعــت لبرنامــج عــاج مــن اإلدمــان لــدى مجمــع األمــل للصحــة‬\n\n‫‪21‬‬\n\f‫النفســية  هكــذا أجــاب وبتصفــح املعاملــة جــرى االطــاع علــى التقريــر‬\n‫الكيمــاوي فوجدتــه كمــا ذكــره املدعــي العــام فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واجلــواب وإلقــرار املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n‫وألن مــا أقــدم عليــه فعــل محــرم شــرعا لقولــه تعالــى (( يــا أيهــا الذيــن‬\n‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n‫فاجتنبــوه )) املائــدة‪ 90 :‬ولقولــه صلــى اهلل عليــه وســلم (( كل مس ــكر‬\n‫خمــر وكل خمــر حــرام )) رواه مســلم قــال ابــن حجــر اســتدل مبطلــق‬\n‫هــذا احلديــث علــى حتــرمي كل مــا يســكر ولــو لــم يكــن شــراب ًا فيدخــل‬\n‫يف ذلــك احلشيشــة وغيرهــا فتــح البــاري ‪ 55/10‬كمــا أنــه فعــل مجــرم‬\n‫نظام ـ ًا وفق ـ ًا للمــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات فقــد ثبــت‬\n‫لــدي إدانــة املدعــى عليــه احلاضــر بتعاطــي احلشــيش املخــدر وحكمــت‬\n‫بجلــده حــد شــرب املســكر ثمانــن جلــده دفعــة واحــدة علنـ ًا ومنعــه مــن‬\n‫الســفر خــارج اململكــة ملــدة ســنتني بعــد اكتســاب احلكــم القطعيــة‬\n‫ورددت طلــب املدعــي العــام تطبيــق املــادة  (‪ )41‬مــن النظــام بحقــه لعــدم‬\n‫انطباقهــا عليــه وبإعــان احلكــم عليهمــا قــرر الطرفــان عــدم القناعــة‬\n‫وطلــب املدعــي العــام رفــع املعاملــة دون الئحــة وجــرى إفهــام املدعــى عليــه‬\n‫مراجعــة احملكمــة بتاريــخ ‪1433/2/1‬ه ـ الســتالم نســخة القــرار وأن له‬\n‫ثالثــون يومـ ًا لالعتــراض عليــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد اهلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق ‪1433/2/16‬هـ‬\n‫وقــد حضرســعودي رقــم ســجله املدنــي (‪ ).....‬بصفتــه الوكيــل الشــرعي‬\n‫عــن مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل محافظــة القطيــف‬\n‫برقــم ……………‪.‬وتاريــخ ‪1433/1/12‬ه ـ املخولــة لــه حــق االعتراض‬\n\n\n                                                                                      ‫‪22‬‬\n\f     ‫وقــدم مذكــرة اعتراضيــة مــن صفحــة واحــدة وخمــس مرفقــات‬\n     ‫ملخصهــا أن املدعــى عليــه كان شــبه غيــر مــدرك ملــا أقــر بــه وأنــه أدخــل‬\n     ‫مستشــفى ‪ ......‬للصحــة النفســية بتاريــخ ‪1426/5/2‬ه ـ واحلادثــة املشــار‬\n     ‫لهــا يف القــرار بعــد دخولــه املستشــفى ‪ ،‬واملدعــى عليــه مصــاب بانفصــام‬\n     ‫عقلــي مزمــن ومبــرض الســكري وجلــده يضاعــف حالتــه وطلــب عرضــه‬\n     ‫علــى املستشــفى للتأكــد مــن حالتــه ومــدى قدرتــه علــى اجللــد عليــه فقــد‬\n     ‫قــررت الكتابــة ملجمــع ‪ .....‬للصحــة النفســية لطلــب تقريــر عــن املدعــى‬\n     ‫عليــه وقــد ارتــكاب اجلــرم وإمكانيــة حتملــه اجللــد وصلــى اهلل علــى‬\n                                               ‫نبينــا محمــد وعلــى آلــه وصحبــه ســلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n     ‫القطيــف ففــي يــوم الســبت املوافــق‪ 1433/11/27‬ه ـ وفيهــا حضــر‬\n     ‫املدعــي العــام وكمــا حضــر ســعودي رقــم ســجله املدنــي () بصفتــه‬\n     ‫الولــي الشــرعي علــى املدعــى عليــه علــي مبوجــب صــك الواليــة الصــادر‬\n     ‫مــن احملكمــة العامــة مبحافظــة القطيــف برقــم  يف ‪1433/10/28‬ه ـ‬\n     ‫املتضمــن إقامــة احلاضــر ولي ـ ًا علــى ابنــه واملشــار فيــه لكتــاب مجمــع‬\n     ‫‪ .....‬للصحــة النفســية بــأن املذكــور علــي مصــاب بتخلــف عقلــي كمــا‬\n     ‫ســبق لنــا الكتابــة لســعادة مديــر مجمــع ‪ .....‬للصحــة النفســية بالدمــام‬\n     ‫لإلفــادة عــن حالــة املدعــى عليــه العقليــة والنفســية وقــت ارتــكاب‬\n     ‫اجلــرم يف ‪1427/3/13‬ه ـ ووردنــا منهــم التقريــر رقــم ……………‪.‬‬\n     ‫يف ‪1433/3/29‬ه ـ املتضمــن أنــه باالطــاع علــى ملفــه الطبــي تبــن أنــه‬\n     ‫مصــاب بحالــة التخلــف العقلــي مــن تاريــخ ســابق لتعاطــي املــواد املخــدرة‬\n     ‫وتــرى اللجنــة أنــه يف تاريــخ ارتكابــه للجــرم بتاريــخ ‪1427/3/13‬ه ـ‬\n     ‫ـاء‬\n      ‫لــم يكــن غالب ـ ًا مــدرك ًا لتصرفاتــه وبأنــه ال يتحمــل اجللــد‪ ،‬فبنـ ً‬\n\n‫‪23‬‬\n\f‫علــى مــا ســبق والحتمــال أن ال يكــون املدعــى عليــه بكامــل أهليتــه‬\n‫وقــت ارتــكاب اجلــرم ممــا يعــد شــبهة ُيــدرأ بهــا احلــد لقولــه صلــى اهلل‬\n‫عليــه وســلم « ادرؤوا احلــدود عــن املســلمني مــا اســتطعتم ‪ ،‬فــإن وجــدمت‬\n‫للمســلم مخرجــا ‪ ،‬فخلــوا ســبيله ‪ ،‬فــإن اإلمــام ألن يخطــئ يف العفــو‬\n‫خيــر مــن أن يخطــئ يف العقوبــة « أخرجــه الترمــذي واحلاكــم والبيهقــي‬\n‫وغيرهــم فقــد رجعــت عمــا حكمــت بــه مــن احلــد ونظــر ًا حلالــة املدعــى‬\n‫عليــه العقليــة والصحيــة فقــد اكتفيــت بتعزيــره باملنــع مــن الســفر خــارج‬\n‫اململكــة مــدة ســنة وتوبيخــه شــفهي ًا مــن قبــل احملكمــة بعــد اكتســاب‬\n‫احلكــم القطعيــة  وبإعــان احلكــم قــرر املدعــي العــام وولــي املدعــى‬\n‫عليــه اعتراضهمــا وطلبــا رفــع املعاملــة حملكمــة االســتئناف دون تقــدمي‬\n                         ‫الئحــة وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪0‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬رئيس احملكمــة اجلزائية مبحافظة‬\n‫القطيــف ففــي يــوم األربعــاء املوافق‪1434/02/13‬ه ـ فقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫رقــم بتاريخ‪1434/1/25‬ه ـ املتضمــن‪ :‬لوحــظ أن مــا حكــم بــه فضيلتــه‬\n‫مــن االكتفــاء مبنــع املدعــى عليــه مــن الســفر محــل نظــر لكــون املدعــى‬\n‫عليــه موظــف أهلــي ويتعاطــى املخــدرات ويســعى للحصــول عليهــا وعــدم‬\n‫تعزيــره بعــد درء احلــد ســبب لتماديــه وللعــودة ملثــل ذلــك ملالحظة ما ذكر‬\n‫وإكمــال الــازم أ‪ .‬هــ‪ .‬فأجيــب أصحــاب الفضيلــة بــأن املدعــى عليــه‬\n‫ليــس موظف ـ ًا أهلي ـ ًا وهــو متخلــف عقلــي وواقعــة التعاطــي مضــى عليهــا‬\n‫أكثــر مــن ســت ســنوات ولــم ترفــع عليــه دعــوى بهــذا اخلصــوص بعدهــا‬\n‫يف هــذه احملكمــة وهــو يخضــع للعــاج النفســي كمــا هــو موضــح يف‬\n‫التقاريــر واإلفــادات املرفقــة واملنــع مــن الســفر نــوع مــن التعزيــر عليــه فلــم‬\n\n\n                                                                                           ‫‪24‬‬\n\f     ‫يظهــر لــي مــا يوجــب العــدول عمــا حكمــت بــه ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية وبرفقهــا القــرار رقــم يف ‪1434/3/29‬هــ  املتضمــن‬\n     ‫لوحــظ أوالً‪ :‬أن مــا أجــاب بــه فضيلتــه علــى قــرار الدائــرة غيــر وجيــه‬\n     ‫حيــث إن املدعــى عليــه مقــر بتعاطــي احلشــيش املخــدر ومضــي املــدة‬\n     ‫ال يســقط األحــكام املترتبــة علــى اجلرميــة املنســوبة للمدعــى عليــه ال‬\n     ‫ســيما وأن املدعــى عليــه لــم يقــدم بينــة علــى مــا ذكــر مــن تخلــف عقلــي‬\n     ‫وفضيلتــه قبــل منــه اجلــواب علــى الدعــوى‪ .‬ثاني ـاً‪ :‬أن فضيلتــه أصــدر‬\n     ‫حكمــه الثانــي مــع بقــاء احلكــم األول ‪ ،‬فأجيــب أصحــاب الفضيلــة‬\n     ‫وفقنــي اهلل وإياهــم للصــواب باآلتــي‪ :‬أوالً‪ :‬أنــه تبــن أن إقــرار املدعــى‬\n     ‫عليــه أمــام احملكمــة لــم يكــن وهــو بكامــل أهليتــه وبالتالــي ال يثبــت‬\n     ‫بــه احلــد‪ .‬ثاني ـاً‪ :‬مضــي املــدة ال يســقط األحــكام املترتبــة علــى اجلرميــة‬\n     ‫لكنــه قــد يكــون ســبب ًا للتخفيــف أو اختيــار العقوبــة املالئمــة وهــذا‬\n     ‫مــا حصــل‪ .‬ثالث ـاً‪ :‬ولــي املدعــى عليــه قــدم بينــة علــى مــا ذكــر مــن‬\n     ‫تخلــف عقلــي هــي صــك الواليــة املرفــق نســخته يف املعاملــة لفــة (‪)44‬‬\n     ‫واملتضمــن شــهادة الشــاهدين بــأن املدعــى عليــه أصيــب بتخلــف عقلــي‬\n     ‫بعــد بلوغــه ســتة عشــر عام ـ ًا كمــا أن تقريــر مجمــع األمــل للصحــة‬\n     ‫النفســية املبنــى علــى كتابنــا تضمــن أن املدعــى عليــه لــم يكــن غالب ـ ًا‬\n     ‫مــدرك ًا لتصرفاتــه يف تاريــخ ارتكابــه للجــرم‪ .‬رابع ـاً‪ :‬بينــت أن قبــول‬\n     ‫احملكمــة اجلــواب كان قبــل تبــن إصابتــه بتخلــف عقلــي وال يخفــى‬\n     ‫علــى أصحــاب الفضيلــة أن بعــض أنــواع التخلــف العقلــي خاصــة النــاجت‬\n     ‫علــى تعاطــي املخــدرات واحلبــوب احملظــورة قــد ال يظهــر جلي ـ ًا للوهلــة‬\n\n\n‫‪25‬‬\n\f‫األولــى‪ .‬خامسـاً‪ :‬مــا جــاء يف املالحظــة الثانيــة مــن إصــداري احلكــم مــع‬\n‫بقــاء احلكــم األولــي فســبق أن صرحــت بالرجــوع عمــا حكمــت بــه مــن‬\n‫احلــد وفــات ســهو ًا التصريــح بالرجــوع عــن احلكــم الســابق باملنــع مــن‬\n‫الســفر ســنتني وأنــا أصــرح بالرجــوع عنــه اآلن وســيتم إعــادة املعاملــة‬\n                                       ‫حملكمــة االســتئناف حســب النظــام‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافق‪1434/06/25‬ه ـ فقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا‬\n‫القــرار رقمفي‪1434/6/7‬ه ـ املتضمــن ‪:‬لوحــظ أن مــا أجــاب بــه فضيلتــه‬\n‫علــى قــرار الدائــرة غيــر مقنــع حيــث إن املدعــى عليــه حــال القبــض عليــه‬\n‫يعمــل موظفـ ًا أهليـاً‪ .‬ويــدرك مــا أقدم عليه والواليــة التي صدرت عليه لم‬\n‫تصــدر إال بعــد انتهــاء محاكمتــه يف احملكمــة اجلزائيــة وعلــى فضيلتــه‬\n‫إعــادة التأمــل يف ذلــك أ‪.‬هــ‪ .‬فأجيــب أصحــاب الفضيلــة بــأن التحقــق مــن‬\n‫كــون املدعــى عليــه مــدرك ًا وقــت ارتــكاب اجلــرم يرجــع فيــه ألهــل‬\n‫اخلبــرة مــن األطبــاء وقــد أفــاد التقريــر الطبــي املشــار إليــه أن املدعــى‬\n‫عليــه مصــاب بتخلــف عقلــي مــع تاريــخ ســابق لتعاطــي املــواد املخــدرة‬\n‫وتــرى اللجنــة أنــه يف تاريــخ ارتكابــه للجــرم بتاريخ‪1427/3/13‬ه ـ لــم‬\n‫يكــن غالب ـ ًا مــدرك ًا لتصرفاتــه وتأخــر صــدور الواليــة غيــر مؤثــر إذ‬\n‫العبــرة بوقــت تدهــور قدراتــه العقليــة وليــس بتاريــخ اســتخراج الواليــة‬\n‫التــي قــد يتأخــر البعــض يف اســتخراجها لعــدة مبــررات ‪ ،‬وكــون‬\n‫التحقيــق تضمــن أن املدعــى عليــه موظــف أهلــي غيــر مؤثــر إذ كثيــر‬\n‫مــن العاطلــن حقيقــة يــدون اســمه يف ســجالت مؤسســات أهليــة ‪ ،‬لهــذا‬\n‫كلــه وملــا ســبق وبينتــه فلــم يظهــر مــا يوجــب العــدول عمــا حكمــت بــه ‪،‬‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                     ‫‪26‬‬\n\f       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزائيــة مبحافظة‬\n       ‫القطيــف والقائــم بعمــل فضيلــة رئيــس احملكمــة أثنــاء إجــازة فضيلتــه‬\n       ‫االعتياديــة وذلــك مبوجــب قــرار التكليــف رقــم  يف ‪1434/7/26‬ه ـ ويف‬\n     ‫هــذا اليــوم الســبت ‪1434/ 8 / 6‬ه ـ فتحــت اجللســة الســاعة ‪  11 : 30‬‬\n       ‫وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة محكمــة‬\n       ‫االســتئناف باملنطقــة الشــرقية رقــم   يف ‪1434/7/22‬ه ـ املتضمــن‬\n       ‫املصادقــة علــى احلكــم  وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره يف‬\n                                                                ‫متــام الســاعة ‪. 11 : 45‬‬\n\n\n\n\n‫‪27‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":19,"source_page_end":27,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5f24b1835af85059915ea837dac0d7acda9be743ec91ba05179f593ffdc52cb4","normalized_text_hash":"629691afc71d7521e5cda3b5da588dd51579a965b609126976720d33438ac6cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p19-341083510"},{"id":"45a58380-5878-565c-a25e-76b68635cf6d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب املنبهة احملظورة -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باملنع من السفر .","document_number":"34264339","case_number":"3405001","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/10","year":"1434","subject":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب املنبهة احملظورة -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 34264339 :‬تاريخه ‪1434/7/10:‬هـ‬\n                       ‫رقم الدعوى‪3405001 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‬\n      ‫تاريخه‪1434/8/3 :‬هـ‬       ‫‪34287857:‬‬\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬تعاطــي‬\n‫احلبــوب املنبهــة احملظــورة ‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي‬\n                              ‫احلشــيش ‪ -‬التعزيــر باملنــع مــن الســفر ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعلى(يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n  ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون) ‪.‬‬\n     ‫‪ -2‬املادة (‪ )1/56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى العــام علــى املدعــى عليــه بتعاطــي احلشــيش املخــدر‪  ،‬‬\n  ‫وتعاطــي احلبــوب احملظــورة وطلــب املدعــي العــام بتعزيــره بالســجن‬\n  ‫واجللــد واملنــع مــن الســفر طبقـ ًا ألحــكام املــواد أرقــام (‪ )41‬و (‪ )56‬مــن‬\n  ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث أنــه أثنــاء قيــام‬\n  ‫الدوريــات األمنيــة مبهــام عملهــا لوحظــت ســيارة املدعــى عليــه وطلــب‬\n  ‫إيقافهــا رفــض الوقــوف وبعــد أن مت إيقافــه اعتــرف بتعاطــي احلشــيش‬\n  ‫املخــدر‪ ،‬كمــا أقــر املدعــى عليــه مبــا نســب إليــه ‪ ،‬بنــاء علــى ماتقــدم‬\n  ‫حكمــت احملكمــة علــى املدعــى عليــه بحــد املســكر والتعزيــر باملنــع‬\n  ‫مــن الســفر ‪ ،‬قــرر املدعــى العــام اعتراضــه علــى احلكــم بــدون الئحــة ‪،‬‬\n\n                                                                                      ‫‪28‬‬\n\f     ‫فيمــا قنــع املدعــى عليــه مبــا صــدر بحقــه مــن حكــم و ُصــدق احلكــم‬\n                                                 ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n     ‫برقــم وتاريــخ ‪ 1434 / 7 / 2‬ه ـ املقيــدة باحملكمــة برقــم  وتاريــخ ‪/ 2‬‬\n     ‫‪ 1434 / 7‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ .... /‬ضــد ‪ ، ..../‬ســعودي‬\n     ‫اجلنســية حســب بطاقــة الهويــة الوطنيــة رقــم (‪ ).......‬ففــي يــوم  االثنــن ‪10‬‬\n     ‫‪1434/ 7 /‬ه ـ فتحــت اجللســة الســاعة ‪  11 : 15‬وفيهــا حضــر  املدعــي‬\n     ‫العــام واملدعــى عليــه املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة‬\n     ‫الدعــوى املتضمنــة مــا يلــي ‪ ( :‬بصفتــي مدعي ـ ًا عامــا يف دائــرة التحقيــق‬\n     ‫واإلدعــاء العــام مبحافظــة القطيــف أدعــي علــى ‪ .......‬البالــغ مــن العمــر‬\n     ‫(‪ ، )26‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ،).......‬غيــر‬\n     ‫محصــن ‪ ،‬عاطــل ‪ ،‬املقبــوض عليــه بتاريــخ ‪1434/4/24‬ه ـ موقــوف‬\n     ‫علــى ذمــة قضيــة اخــرى باالطــاع علــى محضــر القبــض املعــد مــن  قبــل‬\n     ‫الدوريــات األمنيــة بالقطيــف بتاريــخ ‪1434/4/24‬ه ـ املتضمــن أنــه أثنــاء‬\n     ‫قيــام الدوريــة مبهــام عملهــا لوحظــت ســيارة مــن نــوع ‪ .....‬ومبتابعتهــا‬\n     ‫وطلــب اســتيقافها رفــض قائدهــا الوقــوف واجتهــت لداخــل احلــي‬\n     ‫وقامــت بصــدم مركبــة ولــم يتوقــف ودخــل باجتــاه وقــام بصــدم ســيارة‬\n     ‫أخــرى بعدهــا مت اســتيقاف املركبــة وبعــد الرفــع للعمليــات اتضــح‬\n     ‫أن قائــد الســيارة مطلــوب لشــرطة تــاروت بالتعميــم رقــم ‪ ....‬وتاريــخ‬\n     ‫‪1434/1/17‬ه ـ بقضيــة ســطو مســلح وباالطــاع علــى محضــر الفــرز‬\n\n‫‪29‬‬\n\f‫املعــد مــن قبــل دائــرة التحقيــق واإلدعــاء العــام بالقطيــف املتضمــن أنــه‬\n‫جــرى فــرز هــذه األوراق للمدعــى عليــه وذلــك إلقراره بتعاطــي املخدرات‪.‬‬\n‫وبســماع أقوالــه األوليــة لــدى الشــرطة أقــر بتعاطيــه احلشــيش بشــكل‬\n‫متقطــع وبســماع أقوالــه األوليــة لــدى مكافحــة املخــدرات أقــر بتعاطيــه‬\n‫احلشــيش املخــدر وحبــوب الــروش احملظــورة وباســتجوابه أقــر بتعاطيــه‬\n‫احلشــيش واحلبــوب وقــد أســفر التحقيــق عــن اتهامــه بتعاطــي احلشــيش‬\n‫وفقــا للفقــرة‬\n              ‫املخــدر وحبــوب اإلمفيتامــن املنبهــة واحملظــورة املجــرم ً‬\n‫رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪-1 :‬إقــراره حتقيقــا املنــوه عنــه‬\n‫واملــدون علــى الصفحــة رقــم ‪ 6‬واملرفــق لفــة رقــم ‪-2 .70‬إقــراره مبحضــر‬\n‫ســماع األقــوال األوليــة لــدى الشــرطة املنــوه عنــه واملــدون علــى الصفحــة‬\n‫رقــم ‪ 11‬واملرفــق لفــة رقــم‪-3 . 51‬إقــراره مبحضــر ســماع األقــوال األوليــة‬\n‫لــدى مكافحــة املخــدرات املنــوه عنــه واملــدون علــى الصفحــة رقــم‬\n‫‪2‬واملرفــق لفــة رقــم‪-4 . 79‬مــا ورد يف محضــر القبــض مــن وقائــع املنــوه‬\n‫عنهــا واملرفــق لفــة رقــم ‪ .60‬وبالبحــث عمــا إذا كان لــه ســوابق عثــر‬\n‫لــه علــى ســابقتني األولــى ترويــج املخــدرات وإهــداء املخــدرات والثانيــة‬\n‫حيــازة واســتعمال املخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور ‪-‬وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرعا ‪-‬فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا لــذا أطلــب إثبــات مــا أســند إليــه وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة‬\n‫رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم‬\n‫عليــه مبــا يلــي‪-1 :‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n‫رقــم (‪ )41‬مــن النظــام‪-2 .‬منعــه مــن الســفر وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )56‬مــن النظــام‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى‬\n\n\n                                                                                             ‫‪30‬‬\n\f     ‫علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف االتهــام املوجــه لــي كلــه‬\n     ‫صحيــح هــذا جوابــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n     ‫أقــر املدعــى عليــه مبــا نســب إليــه ممــا يســتوجب عقوبتــه ولقولــه تعالــى ‪:‬‬\n     ‫(يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n     ‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) وبنــاء علــى املــواد ‪ 2/3‬و‬\n     ‫‪ 1/56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة فقــد حكمــت‬\n     ‫مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n     ‫وحبــوب اإلمفيتامــن احملظــورة ‪ -2 .‬جلــد املدعــى عليــه ثمانــن جلــدة‬\n     ‫حــد املســكر أمــام مــأ مــن النــاس ‪ ،‬كمــا أفهمتــه بانطبــاق املــادة‬\n     ‫‪ 1/56‬مــن نظــام مكافحــة املخــدرات عليــه وهــي منعــه مــن الســفر مــدة‬\n     ‫ســنتني وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم قناعتــه‬\n     ‫ورغبتــه رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n     ‫وقــرر املدعــى عليــه قناعتــه وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره‬\n                                                             ‫يف متــام الســاعة ‪11 : 35‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد ‪1434/8/21‬ه ـ فتحــت اجللســة‬\n     ‫يف متــام الســاعة ‪ 11 : 30‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n     ‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم   يف‬\n     ‫‪1434/8/3‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1434/8/21‬ه ـ ‪.‬‬\n     ‫احلمد هلل وحده وبعد فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة األولى‬\n     ‫مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم  وتاريــخ‬\n\n\n‫‪31‬‬\n\f  ‫‪1434/7/15‬ه ـ املقيــدة لــدى احملكمــة برقــم  وتاريــخ ‪1434/7/18‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ املســجل برقــم  ‬\n  ‫وتاريــخ ‪1434/7/10‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام ‪ .....‬ضــد‪ ...../‬يف‬\n  ‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n  ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n  ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم حــرر يف ‪1434/8/2‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪32‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":28,"source_page_end":32,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ba921e45c9d09855daf78850f05690bd3676c6da487b2c00e7249b9541746a52","normalized_text_hash":"2acec27df41fc81130d298a1e57226f4a7e2a8b02879aedd314a0de3d3dc5bb8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p28-34264339"},{"id":"59e3fa07-9f48-5b77-8b66-41239d3067cc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلبوب احملظورة -وجود سوابق -إقرار - التعزير بالسجن واملنع من السفر -1الفقرة الثانية من املادة ( )3من نظام مكافحة املخدرات واملؤثرات","document_number":"3442047","case_number":"3425142","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/19","year":"1434","subject":"مخدرات -تعاطي احلبوب احملظورة -وجود سوابق -إقرار - التعزير بالسجن واملنع من السفر -1الفقرة الثانية من املادة ( )3من نظام مكافحة املخدرات واملؤثرات","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪   3442047 :‬تاريخه ‪1434/02/19 :‬هـ  ‬\n                             ‫رقم الدعوى‪3425142 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف  ‬\n                ‫‪    34191283‬تاريخه‪1434/04/17 :‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬تعاطــي احلبــوب احملظــورة ‪ -‬وجــود ســوابق ‪ -‬إقــرار ‪-‬‬\n                                          ‫التعزيــر بالســجن واملنــع مــن الســفر‬\n\n\n\n\n     ‫‪-1‬الفقــرة الثانيــة مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثرات‬\n                                                                             ‫العقلية‬\n     ‫‪-2‬الفقــرة األولــى مــن املــادة (‪ )41‬من نظام مكافحــة املخدرات واملؤثرات‬\n                                                                             ‫العقلية‬\n     ‫‪-3‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                            ‫العقليــة‬\n     ‫‪-4‬املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n                                                              ‫واملؤثــرات العقليــة‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتعاطــي احلبــوب احملظــورة‬\n     ‫وطلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه‬\n     ‫بعقوبــة الســجن واملنــع مــن الســفر وفق ـ ًا لنظــام مكافحــة املخــدرات‬\n     ‫املــواد أرقــام (‪ )41‬و (‪ )56‬ـ وجــود ســوابق علــى املدعــى عليــه حيــث مت‬\n     ‫القبــض علــى املدعــى عليــه أثنــاء مرافقتــه ألحــد املروجــن الــذي متكــن‬\n‫‪33‬‬\n\f‫مــن الهــرب ‪ -‬أقــر املدعــى عليــه بتعاطــي احلبــوب احملظــورة يف الســابق و‬\n‫أنــه أخــذ جــزاءه عليهــا مبوجــب حكــم ســابق واســتند املدعــي العــام يف‬\n‫دعــواه علــى إقــرار املدعــى عليــه حتقيقـ ًا بتعاطــي احلبــوب وصــدر احلكم‬\n‫بتعزيــر املدعــى عليــه لقــاء مانســب إليــه ولقــاء ســوابقه بالســجن واملنــع‬\n                  ‫مــن الســفروصدق احلكــم مــن محكمــة االســتئناف‪..‬‬\n\n\n\n\n                                                                                    ‫‪34‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n     ‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 34121887‬وتاريــخ ‪1434/1/14‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 3425142‬وتاريــخ ‪1434/1/14‬ه ـ‬\n     ‫افتتحــت اجللســة يف يــوم األربعــاء ‪1434/2/13‬ه ـ الســاعة الثامنــة‬\n     ‫والنصــف وفيهــا قــدم املدعــي العــام دعــواه ونصهــا اآلتي‪ :‬بصفتــي مدعي ًا‬\n     ‫عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪......../‬‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم  حيــث إنــه باالطــاع علــى‬\n     ‫محضــر االنتقــال والقبــض والتفتيــش املعــد مــن قبــل شــعبة مكافحــة‬\n     ‫املخــدرات بالدمــام تبــن أنــه بتاريــخ ‪1433/11/14‬ه ـ مت القبــض علــى‬\n     ‫املدعــى عليــه اثــر ورود بــاغ بشــان قيــام شــخص يدعــى ‪ ......‬هــارب‬\n     ‫(ســوف يتخــذ الــازم بحقــه فــور القبــض عليــه) بترويــج احلبــوب املنبهــه‬\n     ‫ـاء عليــه مت متكــن‬‫واحملظــورة وأنــه يســتخدم لذلــك اجلــوال رقــم   ‪ ......‬وبنـ ً‬\n     ‫املصــدر مــن االتصــال علــى املدعــو واتفــق معــه علــى شــراء حبــوب‬\n     ‫مخــدرة مببلــغ ‪ 100‬ريــال و اتفــق معــه  علــى أن يتقابــا خلــف ‪ ......‬يف‬\n     ‫مواقــف ‪ ......‬مــول وعليــه مت تزويــد املصــدر باملبلــغ احلكومــي املتفــق‬\n     ‫عليــه كمــا مت تكليــف أحــد أعضــاء الفرقــه مبرافقتــه و عنــد الوصــول‬\n     ‫الــى املوقــع املتفــق عليــه حضــرت ســيارة مــن نــوع  ‪ .......‬حتمــل اللوحــة‬\n     ‫رقــم (‪ ).......‬يســتقلها شــخص واحــد وتوقــف خلــف ســيارة املصــدر ثــم‬\n     ‫نــزل املصــدر وركــب معــه يف ســيارته وشــاهد عضــو الفرقــة القابضــة‬\n\n‫‪35‬‬\n\f  ‫عمليــه االســتالم والتســليم يف داخــل الســيارة وبعــد ذلــك نــزل املصــدر‬\n  ‫وســلم الكميــة املروجــة لعضــو الفرقــة وتبــن أنهــا عبــارة عــن (‪ )2‬حبتــن‬\n  ‫أثبــت التقريــر الكيمــاوي الشــرعي رقــم ( ‪ 4093‬ك ش ) و تاريــخ ‪21‬‬\n  ‫‪1433/11/‬ه ـ ايجابيتهــا ملــادة االمفيتامــن املنبهــه واحملظــوره ومت‬\n  ‫متابعــة قائــد املركبــة ولكــن يتــم التمكــن مــن القبــض عليــه يف حينــه‬\n  ‫ألنــه كان يســير بســرعة جنونيــة وبجمــع املعلومــات عــن املركبــة املنــوه‬\n  ‫عنهــا تبــن أنهــا مســتأجرة باســم مــن قبــل شــركة ‪  .......‬ومت التنســيق‬\n  ‫مــع موظــف الشــركة والــذي  قــام باالتصــال علــى املدعــو وطلــب منــه‬\n  ‫احضــار الســيارة املســتأجرة  وتســديد باقــي املســتحقات ويف الســاعه‬\n  ‫ـاء أفــاد املدعــو انــه قــادم لتســليمها وبعــد ذلــك حضــرت‬  ‫العاشــره مسـ ً‬\n  ‫السيارةاملســتأجرة وبرفقتهــا ســيارة اخــرى مــن نــوع ‪ .......‬حتمــل اللوحــه‬\n  ‫رقــم (‪ ).......‬وعنــد مشــاهدة ألفــراد الفرقــه قــام بالهــرب بالســيارة‬\n‫األخــرى ولــم يتــم التمكــن مــن القبــض عليــه ومت القبــض علــى مرافقــه  ‬\n  ‫اثنــاء تســليمه للسيارةاملســتأجرة وتبــن أنــه املدعــى عليــه ومبناقشــته‬\n  ‫عــن املدعــو اقــر بأنــه هــو الــذي هــرب بســيارته ومت االتصــال عــن طريقــه‬\n  ‫ولكنــه لــم يــرد علــى االتصــال وبســماع أقوالــه املدعــى عليــه أفــاد أن‬\n  ‫املدعــو اتصــل عليــه وطلــب منــه ان يقــوم بتوصليــه لتســليم الســيارة‬\n  ‫ملكتــب االيجــار ومت القبــض عليــه هنــاك و اقــر بتعاطيــه للحبــوب املنبهه‬\n  ‫واحملظــوره يف بعــض األحيــان وباســتجوابه أفــاد أن قــام باالتصــال عليــه‬\n  ‫وطلــب منــه مرافقتــه لتســليم السيارةاملســتأجرة ملكتــب التأجيــر وعنــد‬\n  ‫الوصــول إلــى املكتــب قــام بالنــزول وقابــل املوظــف وركــب يف ســيارته‬\n  ‫و لــم ينــزل معــه لكونــه كان يتصــل باجلــوال ومت القبــض عليــه بعــد‬\n  ‫ذلــك ومتكــن مــن الهــرب و نفــى مــا ســوى ذلــك وقــد انتهــى التحقيــق إلــى‬\n\n\n                                                                                      ‫‪36‬‬\n\f     ‫اتهــام املدعــى عليــه بتعاطــي احلبــوب املنبهــه واحملظــورة (االمفيتامــن)‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬اقــراره املنــوه عنــه املــدون علــى ص (‬\n     ‫‪ ) 22‬مــن امللــف املرفــق علــى اللفــه رقــم (‪ )1‬وبالبحــث عــن ســوابقه عثــر‬\n     ‫لــه علــى ثــاث ســوابق األولــى ســرقة كيابــل والثانيــة تســتر والثالثــة‬\n     ‫اســتعمال مخــدرات وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n     ‫أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب‬\n     ‫إثبــات إدانتــه مبــا أســند إليــه وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪)3‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا‬\n     ‫يلــي ‪ -1:‬بعقوبــة الســجن الــواردة يف الفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n     ‫(‪ )41‬مــن النظــام ‪ -2‬منعــه مــن الســفر وفقـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة‬\n                                                ‫رقــم (‪ )56‬مــن النظــام هكــذا ادعــى‬\n     ‫ا مــا ذكــره‬  ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n     ‫املدعــي العــام مــن قيامــي بتعاطــي احلبــوب احملظــورة فذلــك غيــر صحيــح‬\n     ‫والصحيــح أننــي كنــت أتعاطاهــا يف الســابق ثــم قبــض علــي ومت احلكــم‬\n     ‫علــي يف محكمــة اإلحســاء اجلزائيــة وبعــد ذلــك لــم أقــم بتعاطيهــا أبــد ًا‬\n     ‫وأمــا الســوابق فهــي صحيحــة لكنني تبت مــن تعاطي املخدرات هكذا‬\n     ‫أجــاب وبعــرض ذلــك علــى املدعــي العــام قال ما ذكــره املدعى عليه غير‬\n     ‫صحيــح والصحيــح مــا ذكــرت يف دعــواي مــن قيامــه بتعاطيهــا هكــذا‬\n     ‫أجــاب ثــم جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال بينتــي مــا‬\n     ‫جــاء يف أوراق املعاملــة ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى لفــة‬\n     ‫رقــم (‪ )1‬دفتــر ضبــط إجــراءات ص (‪ )22‬محضــر اســتجواب املدعــى‬\n     ‫عليــه املتضمــن تعاطيــه للحبــوب احملظــورة وبعــرض مــا ورد يف احملضــر‬\n     ‫علــى املدعــى عليــه قــال صحيــح أننــي قمــت بالتوقيع علــى احملضر لكن‬\n\n\n‫‪37‬‬\n\f‫ـاء علــى مــا تقــدم‬\n                    ‫لــم أكــن أعلــم مــا هــو مكتــوب فيــه هكــذا أجــاب فبنـ ً‬\n‫ـاء‬\n‫مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وإنــكاره للدعــوى وبنـ ً‬\n‫علــى إقــراره الــذي وقــع عليــه عنــد التحقيــق معــه وهــو بكامــل أهليتــه‬\n‫ـاء‬\n ‫املعتبــرة شــرع ًا ونظــر ًا لوجــود ســابقة مخــدرات علــى املدعــى عليــه وبنـ ً‬\n‫علــى الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبنــاء‬\n‫علــى املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ونظــر ًا لكــون حبــوب الكبتاجــون ليســت مســكرة‬\n‫والتقــاس علــى املســكر بــل خطرهــا عظيــم علــى اجلســم وهــي تتلــف‬\n‫العقــل كمــا قــرر ذلــك األطبــاء لــذا كلــه فقــد ثبــت لــدي تعاطــي املدعى‬\n‫عليــه للحبــوب احملظــورة وقــررت اآلتــي‪ :‬أوالً‪ :‬رد مطالبــة املدعــي العــام‬\n‫بتطبيــق الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n‫ـداء مــن‬\n        ‫لعــدم انطباقهــا‪ .‬ثانيـاً‪ :‬ســجن املدعــى عليــه ملــدة ثالثــة أشــهر ابتـ ً‬\n‫تاريــخ إيقافــه لقــاء تعاطيــه املــواد املخــدرة‪ .‬ثالثـاً‪ :‬منعــه مــن الســفر ملــدة‬\n‫ســنتني تبــدأ بعــد انتهــاء فتــرة الســجن املقــررة يف حقــه يف البنــد ثاني ـاً‪.‬‬\n‫وبــكل مــا تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n‫عليــه القناعــة باحلكــم وأمــا املدعــي العــام فقــرر االعتــراض واالكتفــاء‬\n‫بالئحــة الدعــوى العامــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                ‫محمــد‪ .‬حــرر يف ‪1434/2/119‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1434/3/25‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم‬\n‫‪ 3457784‬يف ‪1434/3/8‬ه ـ املتضمــن (لوحــظ‪ :‬أوالً‪ :‬أن املدعــى عليــه‬\n\n\n                                                                                           ‫‪38‬‬\n\f     ‫دفــع يف جوابــه بأنــه ســبق أن حكــم عليــه لــدى احملكمــة اجلزائيــة‬\n     ‫باإلحســاء ولــم جنــد أن فضيلتــه حتقــق مــن ذلــك وهــل مــا حكــم بــه‬\n     ‫عليــه قبــل هــذه الواقعــة أم ال ثاني ـاً‪ :‬مــا مســتند فضيلتــه يف احلكــم‬\n     ‫علــى املدعــى عليــه بالســجن مــا دام أنــه مــدان بالتعاطــي فعلــى فضيلتــه‬\n     ‫مالحظــة مــا ذكــر وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة إلكمــال‬\n     ‫الزمهــا واهلل املوفــق) عليــه أجيــب أصحــاب الفضيلــة بالنســبة للمالحظــة‬\n     ‫األولــى علــى فــرض صحــة مــا ذكــر املدعــى عليــه فــإن تلــك قضيــة وهــذه‬\n     ‫قضيــة أخــرى واملدعــى عليــه هنــا مطالــب بالتعزيــر فــا أرى فائــدة مــن‬\n     ‫التحقــق مــن ذلــك وأمــا بالنســبة للمالحظــة الثانيــة فــإن املســتند قــد‬\n     ‫ذكرتــه يف تســبيب احلكــم وهــو املــادة (‪ )30‬مــن الالئحــة التنفيذيــة‬\n     ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وكذلــك وجــود ســوابق‬\n     ‫لديــه منهــا ســابقة مخــدرات ونظــر ًا لكــون حبــوب الكبتاجــون ليســت‬\n     ‫مســكرة والتقــاس علــى املســكر وأضرارهــا علــى اجلســم كثيــرة‬\n     ‫حيــث ذكــر األطبــاء أن مــن أضرارهــا تلــف خاليــا املــخ واألعصــاب‬\n     ‫كمــا أنهــا تغيــر يف الضغــط الشــرياني وتغيــر يف نظــم القلــب وتغيــر يف‬\n     ‫الفعاليــة النفســية احلركيــة للمتعاطــي وقــد تتســبب يف احتشــاء الدمــاغ‬\n     ‫أو القلــب وضعــف احملاكمــة العقليــة وغيــر ذلــك مــن األضــرار ليس هذا‬\n     ‫محــل ذكرهــا وأمــرت برفــع املعاملــة إلــى محكمــة االســتئناف وبــاهلل‬\n     ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/3/25‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1434/05/01‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة الثامنــة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية برقــم ‪ 341034402‬يف ‪1434/04/23‬ه ـ وبرفقهــا‬\n     ‫القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم  يف ‪1434/04/17‬ه ـ‬\n\n\n‫‪39‬‬\n\f‫املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/05/01‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪40‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":33,"source_page_end":40,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"12ce59c66321de117dc6986b232c0e146bfd5cae8be7f2d8520fd5da58960565","normalized_text_hash":"cec7a78f8bb4abcb5194c101a7449e67e97adc9e60ee90336df23c2efab0989a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p33-3442047"},{"id":"d3da7d45-2c79-5012-bad2-165ff15cb56f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلبوب احملظورة «الترامادول» -الشروع يف إهداء احلبوب احملظورة -إقرار بسبق تعاطي احلشيش -تخفيف العقوبة لعدم وجود سوابق ولكون الترامادول يعرف بوصفة طبية خارج اململكة -إقامة حد املسكر -التعزير بالسجن واجللد واإلبعاد","document_number":"3436221","case_number":"3438818","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/12","year":"1434","subject":"مخدرات -تعاطي احلبوب احملظورة «الترامادول» -الشروع يف إهداء احلبوب احملظورة -إقرار بسبق تعاطي احلشيش -تخفيف العقوبة لعدم وجود سوابق ولكون الترامادول يعرف بوصفة طبية خارج اململكة -إقامة حد املسكر -التعزير بالسجن واجللد واإلبعاد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪    3436221 :‬تاريخه ‪1434/02/12 :‬هـ  ‬\n                             ‫رقم الدعوى ‪3438818 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪      3450134‬تاريخه‪1434/02/30 :‬هـ‬\n\n\n\n     ‫مخــدرات ‪ -‬تعاطــي احلبــوب احملظــورة «الترامــادول» ‪ -‬الشــروع يف‬\n     ‫إهــداء احلبــوب احملظــورة ‪ -‬إقــرار بســبق تعاطــي احلشــيش ‪ -‬تخفيــف‬\n     ‫العقوبــة لعــدم وجــود ســوابق ولكــون الترامــادول يعــرف بوصفــة طبيــة‬\n     ‫خــارج اململكــة ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن واجللــد واإلبعــاد‬\n                                                                         ‫عــن البــاد‪.‬‬\n\n\n\n\n     ‫ـاب‬      ‫ال ْمـ ُـر َو ْالَ ْي ِسـ ُـر َو ْ َ‬\n     ‫ال ْن َصـ ُ‬                                ‫نــا ْ َ‬                 ‫‪-1‬قولــه تعالــى ( َيــا َأ ُّي َهــا ا َّلذِ يـ َـن َ‬\n                                                          ‫آم ُنــوا ِإ َّ َ‬\n         ‫ـون ) ‪.‬‬‫ـوه َل َع َّل ُكـ ْـم ُت ْفل ُِحـ َ‬\n                                                  ‫اج َتن ُِبـ ُ‬‫الش ـ ْي َطانِ فَ ْ‬                                          ‫َو ْ َ‬\n                                                                                 ‫ال ْز َل ُم ِر ْ ٌجــس مِ ـ ْـن َع َمــلِ َّ‬\n                            ‫الح َها) ‪.‬‬  ‫‪-2‬قوله تعالى ( َوال ُت ْف ِس ُدوا ِف األرض َب ْع َد ِإ ْص ِ‬\n              ‫‪-3‬املواد (‪ )3/2‬و (‪ )41/1‬و (‪ )56/2‬من نظام مكافحة املخدرات ‪.‬‬\n           ‫‪-4‬برقية سمو وزير الداخلية رقم ‪ 36901‬وتاريخ ‪1432/06/13‬هـ ‪.‬‬\n                                                         ‫‪-5‬املادة (‪ )60‬من نظام مكافحة املخدرات ‪.‬‬\n\n\n\n\n     ‫توجيــه االتهــام للمدعــى عليــه املُقيــم بالشــروع يف إهــداء حبتــن مــن‬\n     ‫حبــوب الترامــادول احملظــورة‪ ،‬تعاطيــه لهــذه احلبــوب‪ ،‬تعاطــي احلشــيش‬\n     ‫املخــدر ‪ ،‬قبــض علــى املدعــى عليــه مــن قبــل مكافحــة املخــدرات إثــر‬\n     ‫بــاغ مــن أحــد املصــادر الســرية عــن قيــام املدعــى عليــه بإهــداء احلبــوب‬\n\n‫‪41‬‬\n\f‫احملظــورة‪ ،‬مت متكــن املصــدر مــن االتصــال باملــروج (املدعــى عليــه)‬\n‫وســماع رجــال الضبــط فحــوى املكاملــة التــي تضمنــت التفــاوض علــى‬\n‫إهــداء املصــدر حبــوب الترامــادول احملظــورة‪ ،‬مت االنتقــال للموقــع املتفق‬\n‫عليــه وخشــية مــن هــروب املدعــى عليــه مت القبــض عليــه قبــل إمتــام عمليــة‬\n‫اإلهــداء‪ ،‬عثــر مــع املدعــى عليــه حلبتــن مــن احلبــوب املنبهــة احملظــورة‬\n‫كمــا عثــر علــى اجلــوال املســتخدم يف عمليــة التنســيق‪ ،‬طلــب املدعــي‬\n‫العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبــة الســجن‬\n‫واجللــد والغرامــة واإلبعــاد ومصــادرة الهاتــف اجلــوال وإلغــاء شــريحته‬\n‫وذلــك وفــق نظــام مكافحــة املخــدرات وتعميــم وزارة الداخليــة‪ ،‬أنكــر‬\n‫املدعــى عليــه الشــروع يف اإلهــداء‪ ،‬أقــر بتعاطــي احلشــيش كمــا‬\n‫أقــر بتعاطــي حبــوب الترامــادول ودفــع بأنــه يســتخدمها وصفــة طبيــة‬\n‫كعــاج آلالم األســنان عنــد احلاجــة‪ ،‬صــدر احلكــم بصــرف النظــر عــن‬\n‫طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه بالشــروع يف إهــداء حبتــن‬\n‫مــن حبــوب الترامــادول مــع توجيــه التهمــة لــه يف ذلــك وإثبــات إدانتــه‬\n‫يف بقيــة مــا أســند إليــه‪ ،‬تخفيــف العقوبــه لعــدم وجــود ســوابق ولكــون‬\n‫الترامــادول يصــرف بوصفــه طبيــه يف جمهوريــة مصــر العربية‪،‬صــدر‬\n‫احلكــم بإقامــة حــد املســكر علــى املدعــى عليــه والتعزيــر بالســجن‬\n‫واجللــد واإلبعــاد عــن البــاد‪ ،‬صــدق احلكــم مــن محكــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪42‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n       ‫برقــم ‪ 3438818‬وتاريــخ ‪1434 /1/21‬ه ـ املقيــدة باحملكمــة برقــم‬\n       ‫‪ 34189566‬وتاريــخ ‪ 1434/1/21‬ه ـ واملتعلقــة بدعــوى املدعــي العــام‬\n       ‫‪ ............/‬ضــد ‪ .........../‬مصــري اجلنســية حســب إقامتــه الصــادرة مــن‬\n       ‫الدوادمــي برقــم (‪ )....‬ففــي يــوم  الثالثــاء ‪1434/ 1 / 27‬ه ـ فتحــت‬\n       ‫اجللســة الســاعة ‪  10 : 15‬وفيهــا حضــر  املدعــي العــام واملدعــى عليــه‬\n       ‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا‬\n       ‫يلــي ‪( :‬بصفتــي مدعيـ ًا عامــا يف دائــرة التحقيــق واإلدعاء العام مبحافظة‬\n       ‫القطيــف أدعــي علــى (‪ )....‬البالــغ مــن العمــر (‪ )31‬ســنة ‪ ،‬مصــري‬\n       ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ، )....‬غيــر محصــن ‪ ،‬موظــف‬\n       ‫أهلــي‪ ،‬قبــض عليــه بتاريــخ ‪1433/11/20‬ه ـ وأحيــل لســجن محافظــة‬\n       ‫القطيــف اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬هــ‪.‬‬\n       ‫حيــث أنــه بتاريــخ ‪1433/11/20‬ه ـ ورد بــاغ مــن أحــد املصــادر الســرية‬\n     ‫ملكافحــة املخــدرات بالدمــام عــن وجــود املدعــى عليــه يحمل اجلــوال رقم  ‬\n       ‫ويســكن بالـ ـ (‪ )....‬ويقــوم بإهــداء احلبــوب احملظــورة‪ .‬وباالطــاع علــى‬\n       ‫محضــر االتصــال املعــد مــن قبــل مكافحــة املخــدرات بالدمــام بتاريــخ‬\n       ‫‪1433/11/20‬ه ـ املتضمــن أنــه مت متكــن املصــدر الســري مــن االتصــال‬\n       ‫باملــروج وســماع رجــال الضبــط فحــوى املكاملــة التــي تضمنــت التفــاوض‬\n       ‫علــى إهــداء املصــدر حبــوب الترامــادول احملظــورة ‪ .‬وباالطــاع علــى‬\n       ‫محضــر القبــض املعــد مــن قبــل مكافحــة املخــدرات بالدمــام املتضمــن‬\n\n‫‪43‬‬\n\f‫أنــه مت االتصــال باملدعــى عليــه وطلــب منــه املصــدر حبتــان فــرد املدعــى‬\n‫عليــه أن معــه حبتــان وســيقوم بإعطائهــا للمصــدر ومت االتفــاق علــى‬\n‫مــكان عمليــة التســليم واالســتالم مبحافظــة (‪ )....‬وانتهــت املكاملــة ‪،‬‬\n‫وحتــرك أعضــاء الفرقــة القابضــة نحــو املــكان املتفــق عليــه وباالتصــال‬\n‫علــى املدعــى عليــه أفــاد أنــه موجــود عنــد أحــد املخططــات كــي يقــوم‬\n‫بتســليمه احلبــوب احملظــورة فــرد املصــدر بأنــه ســيحضر بعــد عــدة دقائــق‬\n‫وبعــد مشــاهدة املصــدر للمذكــور قــام باإلشــارة إليــه ألفــراد الفرقــة‬\n‫القابضــة ولكــون الســيارة يف وضــع التشــغيل وخشــية مــن هروبــه مت‬\n‫إرســال أحــد رجــال األمــن لــه لتمثيــل دور شــخص يريــد عمــل اشــتراك‬\n‫لســيارته ومت الســيطرة والقبــض عليــه وعثــر معــه علــى عــدد (‪ )2‬حبتــن‬\n‫مــن احلبــوب املنبهــة واحملظــورة كمــا عثــر علــى اجلــوال الــذي مت التنســيق‬\n‫معــه مــن خاللــه نــوع (‪ )....‬ويحمــل رقــم االتصــال (‪ .)....‬وورد التقريــر‬\n‫الكيمــاوي الشــرعي رقم‪4154‬وتاريخ‪1433/11/27‬ه ـ املتضمــن ثبوت‬\n‫إيجابيــة العينــات املضبوطــة لعقــار الترامــادول احملظــورة واملدرجــة يف‬\n‫اجلــدول األول فئــة (هــ) واملرفــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ .‬وبســماع أقــوال املدعــى عليــه األوليــة أقــر بحيازتــه للحبتــن‬\n‫املضبوطتــن معــه وأنــه يتعاطــى احلبــوب احملظــورة منــذ ســنتني ونصــف‬\n‫عنــد اللــزوم وأنــه يتعاطــى احلشــيش املخــدر أيضــا‪ .‬وباســتجواب املدعــى‬\n‫عليــه أقــر بتعاطيــه حبــوب الترامــادول وحيازتــه لهــا وأفــاد أنــاه يتعاطاهــا‬\n‫‪،‬كمــا أقــر بتعاطيــه احلشــيش املخــدر‪ .‬وقــد أســفر التحقيــق عــن اتهامــه‬\n‫بالشــروع يف إهــداء حبتــن مــن حبــوب الترامــادول احملظــورة وتعاطــي‬\n‫نوعهــا وتعاطــي احلشــيش املخــدر‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪-1‬إقــراره حتقيقــا املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪)3-2-1‬‬\n\n\n                                                                                       ‫‪44‬‬\n\f     ‫واملرفــق لفــة رقــم (‪-2 )12-11-10‬إقــراره بحيــازة احلبــوب احملظــورة‬\n     ‫وتعاطيــه لــه وللحشــيش املخــدر مبحضــر ســماع األقــوال األوليــة املنــوه‬\n     ‫عنــه واملــدون علــى الصفحــة رقــم (‪ )21‬واملرفــق لفــة رقــم (‪-3 )1‬مــا‬\n     ‫ورد يف محضــر البــاغ املنــوه عنــه مبحضــر االســتدالل واملــدون علــى‬\n     ‫الصفحــة رقم‪2‬واملرفــق لفــة رقــم (‪-4 )1‬مــا ورد يف محضــر القبــض‬\n     ‫مــن وقائــع املنــوه عنهــا واملدونــة علــى الصفحــة رقــم (‪ )12‬واملرفقــة‬\n     ‫لفــة رقــم (‪ -5 .)1‬مــا ورد يف محضــر االتصــال املنــوه عنــه واملــدون‬\n     ‫علــى الصفحــة رقم‪4‬واملرفقــة لفــة رقــم (‪ -6 )1‬مــا ورد يف التقريــر‬\n     ‫الكيمــاوي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪ .)16‬وبالبحــث‬\n     ‫عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجلة‪ .‬وحيــث إن‬\n     ‫مــا أقــدم عليــه املذكــور ‪-‬وهــو بكامــل أهليتــه املعتبــرة شــرعا‪ -‬فعــل‬\n     ‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب احلكــم عليــه مبــا يلــي‪:‬‬\n     ‫وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن‬\n                                                        ‫أوال‪ :‬إثبــات مــا أســند إليــه ً‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‬\n     ‫‪-1:‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n     ‫رقــم (‪ )38‬مــن النظــام مــع مراعــاة مقتضــى املــادة ‪ 62‬مــن ذات النظــام‬\n     ‫‪-2.‬إبعــاده عــن البــاد إعمــاال ملقتضــى الفقــرة رقــم (‪ )2‬مــن املــادة رقــم‬\n     ‫(‪ )56‬مــن النظــام‪ .‬ثانيــا‪ :‬مصــادرة الهاتــف اجلــوال العائــد للمدعــو نــوع‬\n     ‫(‪ )....‬ويحمــل رقــم االتصــال (‪ .)....‬والرقــم املصنعــي (‪ )....‬الســتخدامه‬\n     ‫يف الترويــج وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام‪،‬‬\n     ‫مــع املطالبــة بإســقاط شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس‬\n     ‫املدعــى عليــه وفقــا لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n     ‫‪1429/2/10-9‬هــ‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى علــى املدعى‬\n\n\n‫‪45‬‬\n\f  ‫عليــه أجــاب بقولــه أقــر بأنــي تعاطيــت احلشــيش الســنة املاضيــة مرتــن‬\n  ‫فقــط والثالثــة قبــل عــدة ســنوات وأقــر بأنــي تعاطيــت حبــوب الترامــادول‬\n  ‫لغــرض تخفيــف ألــم أســناني ولــم أكــن أعلــم أنــه محظــور وقــد حصلــت‬\n  ‫علــى هــذه احلبــوب مــن أحــد زمالئــي قبــل ســفره وعددهــا ســبع حبــات‬\n  ‫وقــد أعطانيهــا عندمــا أخبرتــه بأنــي أعانــي مــن ألــم باألســنان وأقــر‬\n  ‫بحيازتــي حبتــن مــن حبــوب الترامــادول وأمــا الشــروع يف اإلهــداء فإنــي‬\n  ‫أنكــره وال أقــر بــه وحقيقــة مــا حصــل مــع املصــدر أنــي أعمــل مديــرا‬\n  ‫ملعــرض واحــة املســتلزمات الطبيــة بالدمــام وكان بينــي وبــن املصــدر‬\n  ‫املذكــور يف الدعــوى تعامــل حيــث ســبق وأن أحضــرت لــه كرســيا‬\n  ‫متحــركا لوالدتــه املقعــدة وحفاظــات لكبــار الســن ثــم طلــب منــي‬\n  ‫حفاظــات وأحضرتهــا لــه ثــم طلــب منــي املــرة الثالثــة فأحضرتهــا لــه‬\n  ‫ومت القبــض علــي هــذا جوابــي وبعــرض ذلــك علــى املدعــي العــام قــال‬\n  ‫الصحيــح مــا جــاء يف دعــواي وبســؤاله البينــة قــال بينتــي ذكرتهــا يف‬\n  ‫الدعــوى وأطلــب رصدهــا هــذا جوابــي وباالطــاع على أدلــة املدعي العام‬\n  ‫وجــدت علــى اللفــات رقــم ‪ 12-10‬حتقيقــا مــع املدعــى عليــه يتضمــن مــا‬\n  ‫نصــه ‪ ( :‬س‪ .‬أنــت متهــم بإهــداء املؤثــرات العقليــة وتعاطــي املؤثــرات‬\n  ‫العقليــة وتعاطــي املــواد املخــدرة ؟ ج‪ /‬أتعاطــى الترامــادول كمســكن‬\n  ‫مصــروف لــي بوصفــة طبيــة ولــم أكــن أنــوي إهــداءه وتعاطيــت احلشــيش‬\n‫مــرة واحــدة‪ .‬س‪ /‬كــم رقــم جوالــك وهــل يســتخدمه أحــد غيــرك ؟ ج‪  /‬‬\n  ‫وهــو جوالــي اخلــاص وال يســتخدمه أحــد غيــري‪ .‬س‪ /‬مت االتصــال عليــك‬\n  ‫مــن قبــل مصــدر مكافحــة املخــدرات وتضمنــت املكاملــة التفــاوض‬\n  ‫علــى إهدائــك لــه حبــوب الترامــادول احملظــورة فمــا صحــة ذلــك؟ ج‪/‬‬\n  ‫غيــر صحيــح اتصــل علــي شــخص وطلــب منــي حبــوب ترامــادول حيــث‬\n\n\n                                                                                    ‫‪46‬‬\n\f     ‫ســألني حتديــدا هــل تعــرف أحــدا عنــده ترامــادول فأجبتــه بــا وقلــت لــه‬\n     ‫خلينــي أشــوف لــك ولــم أقــل لــه ســأعطيك حبــوب‪ .‬س‪ /‬ولكــن املكاملــة‬\n     ‫مســموعة مــن قبــل رجــال الضبــط ممــا يعنــي صحتهــا فمــا ردك ؟ ج‪/‬‬\n     ‫غيــر صحيــح‪ .‬س‪ /‬مت القبــض عليــك وعثــر علــى احلبــوب احملظــورة التــي‬\n     ‫كنــت تنــوي إهداءهــا فمــا صحــة ذلــك؟ ج‪ /‬مت ضبطــي مــع احلبــوب‬\n     ‫وهــي لــي بقصــد التعاطــي ألنــي أســتخدمها كمســكن وهــو موصــوف‬\n     ‫لــي بوصفــة طبيــة يف الســعودية ومصــر وســأحاول إحضــار الوصفــات‪.‬‬\n     ‫س‪ /‬مــا غرضــك مــن حيــازة هــذه احلبــوب؟ ج‪ /‬لتســكني آالم األســنان‬\n     ‫حيــث أنهــا مصروفــة لــي بوصفــة طبيــة‪ .‬س‪ /‬مــا أنــواع املخــدرات التــي‬\n     ‫تتعاطاهــا ومنــذ متــى؟ ج‪ /‬حبــوب الترامــادول كعــاج موصــوف لــي مــن‬\n     ‫الطبيــب وتعاطيــت احلشــيش املخــدر مــرة واحــدة فقــط‪ .‬س‪ /‬هــل ســبق‬\n     ‫وأن قمــت بإهــداء أو ترويــج أي مــن املخــدرات؟ ج‪ /‬ال‪ .‬س‪ /‬مــا ســبب‬\n     ‫حضــورك للموقــع إذا؟ ج‪ /‬كنــت جالســا أتعشــى يف املوقــع‪ .‬س‪ /‬ولكــن‬\n     ‫ورد يف محضــر القبــض أنــك حضــرت للموقــع الــذي حددتــه أنــت بعــد‬\n     ‫االتصــال بــك مــن قبــل املصــدر لكــي تقــوم بتســليمه احلبــوب فــا داعــي‬\n     ‫إلنــكارك؟ ج‪ /‬غيــر صحيــح‪ .‬س‪ /‬متــى آخــر مــرة زرت فيهــا املستشــفى‬\n     ‫لصــرف هــذه احلبــوب لــك؟ ج‪ /‬قبــل شــهر رمضــان أو يف رمضــان قبــل‬\n     ‫حوالــي شــهرين ونصــف أو ثالثــة تقريبــا وصــرف لــي شــريط ترامــادول‬\n     ‫يحتــوي علــى عشــر حبــات عنــد اللــزوم وال أتذكــر اســم املستشــفى‬\n     ‫وســأحاول إحضــار الوصفــة وعندمــا مت القبــض علــي عثــر معــي علــى‬\n     ‫أدويــة أخــرى مســكنة أيضــا فيفــادول وغيــره‪  .‬س‪ /‬هــل لديــك أقــوال‬\n     ‫أخــرى أو مــا تــود إضافتــه؟ ج‪ /‬ال‪ ).‬ا‪.‬ه ـ كمــا وجــدت علــى الصفحــة‬\n     ‫رقــم ‪ 4‬مــن دفتــر التحقيــق رقــم ‪ 1‬محضــر اتصــال يتضمــن مــا نصــه ‪( :‬‬\n\n\n‫‪47‬‬\n\f‫مت متكــن املصــدر الســري مــن االتصــال باملدعــو وســمع رجــال الضبــط‬\n‫فحــوى املكاملــة التــي تضمنــت التفــاوض علــى مــا يلــي ‪ :‬إهــداء املصــدر‬\n‫حبــوب ترامــادول مخــدرة ) ا‪.‬ه ـ كمــا وجــدت علــى الصفحــة رقم ‪ 12‬من‬\n‫دفتــر التحقيــق رقــم ‪ 1‬محضــر قبــض يتضمــن مــا نصــه ‪ (  :‬مت متكــن‬\n‫املصــدر مــن االتصــال علــى املدعــو وطلــب منــه حبــوب ترامــادول  مخــدرة‬\n                                                                      ‫علــى هاتفــه‬\n‫املوضــح يف البــاغ رقــم  وطلــب منــه فــر ّد املذكــور بــأن معــه حبتــان‬\n‫ســيقوم بإعطائهــا للمصــدر فوافــق املصــدر علــى ذلك واتفــق معه على أن‬\n‫تتــم عمليــة االســتالم والتســليم ب ــ(‪ )....‬وانتهــت املكاملــة وحتــرك أعضــاء‬\n‫الفرقــة نحــو املوقــع املتفــق عليــه يف عمليــة االســتالم والتســليم وعنــد‬\n‫وصولهــم قــام املصــدر باالتصــال علــى املذكــور وســؤاله عــن موقعــه‬\n‫فــرد املذكــور بأنــه ينتظــره يف أحــد املخططــات حتــى يقــوم بإعطائــه‬\n‫احلبــوب احملظــورة فــرد املصــدر بأنــه ســيأتيه بعــد عــدة دقائــق وبعــد‬\n‫مشــاهدة املصــدر للمذكــور قــام باإلشــارة إليــه ألعضــاء الفرقــة حيــث‬\n‫كان املذكــور متوقفــا علــى مركبــة مــن نــوع (‪ )....‬حتمــل لوحــة رقــم‬\n‫(‪ )....‬مبفــرده ولــم يكــن معــه أحــد وكان جالســا حتــت املقــود والســيارة‬\n‫يف وضــع التشــغيل وخوفــا مــن هروبــه قــام أحــد أفــراد الفرقــة بالذهــاب‬\n‫إليــه وطلــب منــه اشــتراك ســيارة والتمويــه عليــه حتــى يقــوم بفتــح النافــذة‬\n‫وفــور اســتجابته لرجــل األمــن وإجــراء حديــث معــه قــام بفتــح النافــذة‬\n‫عندهــا قــام رجــل األمــن بالســيطرة عليــه وقــام باقــي أعضــاء الفرقــة‬\n‫بالقبــض عليــه وتفتيشــه حيــث عثــر بيــده علــى مــا كان ســيقوم بإهدائــه‬\n‫للمصــدر وهــي حبــوب بيضــاء اللــون عددهــا حبتــان يشــتبه أن تكــون‬\n‫مــن احلبــوب املخــدرة كمــا عثــر معــه علــى هاتــف جــوال (‪ )....‬يحمــل‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫رقــم (‪ )....‬الــذي مت التنســيق عليــه عــدا ذلــك لــم يعثــر معــه علــى أي مــن‬\n     ‫احملظــورات واتضــح أنــه يدعــى (‪ )....‬مصــري اجلنســية مبوجــب اإلقامــة‬\n     ‫رقــم (‪ )....‬وبتفتيــش الســيارة التــي كانــت معــه لــم يعثــر علــى أي مــن‬\n     ‫احملظــورات ) ا‪.‬ه ـ وبتصفــح املعاملــة وجــدت علــى اللفــة رقــم ‪ 16‬التقريــر‬\n     ‫الكيمــاوي رقــم ‪ 4154‬ك ش املتضمــن ‪ ( :‬إيجابيــة املضبوطــات ملــادة‬\n     ‫الترامــادول واملــدرج يف اجلــدول ‪ 1‬فئــة ه ـ مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة) ا‪.‬ه ـ وبعــرض األدلــة علــى املدعــى عليــه قــال أمــا‬\n     ‫التحقيــق فإجاباتــي الــواردة فيــه كلهــا صحيحــة ووعــدي لــه بأنــي‬\n     ‫ســأبحث لــه عــن حبــوب ترمــادول كان بســبب أنــي ال أريــد خســارته‬\n     ‫كزبــون وإال فأنــا يف احلقيقــة ال أعــرف أحــدا عنــده هــذه احلبــوب  وأمــا‬\n     ‫مــا ورد يف محضــر االتصــال ومحضــر القبــض واتهامــي بالشــروع يف‬\n     ‫إهــداء حبــوب الترامــادول فهــو غيــر صحيــح هــذا جوابــي وبســؤال‬\n     ‫املدعــي العــام زيــادة بينــة وعــد بإحضــار الفرقــة القابضــة ورفعــت اجللســة‬\n     ‫لذلــك ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه ولــم يحضــر‬\n     ‫الشــهود وطلــب املدعــي العــام مهلــة أخــرى إلحضارهــم فأجبتــه لطلبــه‬\n     ‫وأفهمتــه بأنهــا املهلــة األخيــرة ويف جلســة أخــرى حضــر  املدعــي العــام‬\n     ‫واملدعــى عليــه ولــم يحضــر الشــهود وبســؤال املدعــى عليــه عــن مصــدر‬\n     ‫حبــوب الترامــادول أجــاب بقولــه حصلــت عليهــا يف الســعودية مــن أحــد‬\n     ‫زمالئــي وقــد ســافر إلــى مصــر وقــد صــرف لــي أحــد األطبــاء يف مصــر‬\n     ‫قبــل ثــاث ســنوات نوعــا مــن الترامــادول اســمه ( ألتــرا دول ) أللــم‬\n     ‫األســنان وال أعلــم أيــن هــي هــذه الوصفــة اآلن وحينمــا قدمــت للســعودية‬\n     ‫أحضــرت معــي شــريطني منــه وكنــت اســتخدمهما عنــد احلاجــة وقــد‬\n     ‫انتهيــا علمــا بــأن مــا ذكرتــه يف هيئــة التحقيــق مــن أنــه مصــروف لــي‬\n\n\n‫‪49‬‬\n\f‫بوصفــة طبيــة مــن داخــل الســعودية مخالــف للواقــع وقــد أفــدت احملقــق‬\n‫بذلــك بســبب خــويف علــى زميلــي الــذي ســلمني احلبــوب هــذا جوابــي‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬\n‫بتعاطــي الترامــادول واحلشــيش املخــدر وأقــر بحيــازة حبتــن مــن حبــوب‬\n‫الترامــادول بقصــد التعاطــي وأقــر بأنــه حصــل عليهــا مــن أحــد زمالئــه‬\n‫ولــم يقــدم وصفــات طبيــة تثبــت مــا ذكــره مــن كونهــا مصروفــة لــه عــن‬\n‫طريــق أحــد األطبــاء وبنــاء علــى اختــاف إفاداتــه بشــأن الوصفــة الطبيــة‬\n‫حتقيقــا ويف مجلــس القضــاء وحيــث أنكــر املدعــى عليــه الشــروع يف‬\n‫اإلهــداء ولــم يقــدم املدعــي العــام بينــة موصلــة علــى ذلــك وألن وعــد‬\n‫املدعــى عليــه للمصــدر بالبحــث لــه عــن احلبــوب ثــم القبــض عليــه وهــي‬\n‫بحيازتــه قرينــة علــى قصــد الشــروع يف اإلهــداء ولقولــه (يــا أيهــا الذيــن‬\n‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n‫فاجتنبــوه لعلكــم تفلحــون )  وقولــه ( وال تفســدوا يف األرض بعــد‬\n‫إصالحهــا ) وبنــاء علــى املــواد ‪ 2/3‬و ‪ 1/41‬و ‪ 2/56‬مــن نظــام مكافحــة‬\n‫املخــدرات ولكــون املدعــى عليــه ليــس مــن أربــاب الســوابق وألن هــذه‬\n‫احلبــوب تصــرف بوصفــات طبيــة يف جمهوريــة مصــر حســب مــا ورد يف‬\n‫برقيــة وزيــر الداخليــة رقــم ‪ 36901‬يف ‪1432/6/13‬ه ـ املرفــق نســخة‬\n‫منهــا باملعاملــة وكونهــا كذلــك يهــون مــن شــأن تداولهــا بــن مــن يحمــل‬\n‫جنســية ذلــك البلــد  وهــذان األمــران يخــوالن املدعــى عليــه  االســتفادة‬\n                                                     ‫مــن املــادة ‪ 60‬مــن  النظــام‬\n‫فقــد حكمــت مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه بحيــازة حبتــن‬\n‫مــن حبــوب الترامــادول بقصــد التعاطــي ومعاقبتــه لذلــك بســجنه مــدة‬\n‫شــهر واحــد وإبعــاده مــن البــاد بعــد تنفيــذ األحــكام اجلنائيــة الصــادرة‬\n\n\n                                                                                       ‫‪50‬‬\n\f     ‫عليــه ‪-2‬ثبــوت إدانتــه بتعاطــي احلشــيش املخــدر وحبــوب الترامــادول‬\n     ‫ومعاقبتــه بجلــده ثمانــن جلــدة حــد املســكر أمــام مــأ  مــن النــاس‬\n     ‫‪-3‬صــرف النظــر عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه‬\n     ‫بالشــروع يف إهــداء حبتــن مــن حبــوب الترامــادول مــع توجــه التهمــة‬\n     ‫عليــه بذلــك وتعزيــره للشــبهة بســجنه مــدة ســتة أشــهر وجلــده خمســن‬\n     ‫جلــدة دفعــة واحــدة وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n     ‫عــدم قناعتــه ورغبتــه رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة‬\n     ‫اعتراضيــة وقــرر املدعــى عليــه قناعتــه  وبــاهلل التوفيــق وقــد مت االنتهــاء‬\n     ‫مــن حتريــره يف متــام الســاعة ‪ 10 : 00‬مــن يــوم الثالثــاء ‪1434/ 2 / 12‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم  الســبت ‪1434/ 3 / 14‬هــ  فتحــت‬\n     ‫اجللســة الســاعة ‪  10 : 30‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n     ‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقة الشــرقية رقم ‪3450134‬‬\n     ‫يف ‪1434/2/30‬ه ـ املتضمــن املصادقــة علــى احلكــم  وبــاهلل التوفيــق‬\n                       ‫وقــد مت االنتهــاء مــن حتريــره يف متــام الســاعة ‪.  10 : 40‬‬\n\n\n\n\n‫‪51‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":41,"source_page_end":51,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"af8a8844a233e41e3243e117310e939a5150d0c153d4b7c34e3150335a6522fb","normalized_text_hash":"f7ef9f4cc1993158eb569feed6c59910ba9bb9b92ed1322055a4580de821b5e1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p41-3436221"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"4f62670e-3282-5fe6-ade2-473ad1e7ea7a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش -تعاطي حبوب اإلمفيتامن -ثبوت تعاطي احلشيش املخدر -إقامة حد املسكر -منع املدعى عليه من السفر -اإلقرار .","document_number":"34277360","case_number":"3466","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/24","year":"1434","subject":"مخدرات -تعاطي احلشيش -تعاطي حبوب اإلمفيتامن -ثبوت تعاطي احلشيش املخدر -إقامة حد املسكر -منع املدعى عليه من السفر -اإلقرار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪34277360:‬تاريخه‪1434/07/24 :‬هـ‬\n                             ‫رقم الدعوى‪3466:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪   34301297‬تاريخه‪1434/8/21:‬هـ‬\n\n\n    ‫مخــدرات ‪ -‬تعاطــي احلشــيش ‪ -‬تعاطــي حبــوب اإلمفيتامــن ‪ -‬ثبــوت‬\n    ‫تعاطــي احلشــيش املخــدر ‪ -‬إقامــة حــد املســكر ‪ -‬منــع املدعــى عليــه مــن‬\n                                                                  ‫الســفر ‪ -‬اإلقــرار ‪.‬‬\n\n\n\n    ‫‪-1‬القاعــدة الفقهيــة ( املــرء مؤاخــذ بإقــراره ) والقاعــدة ( إقــرار اإلنســان‬\n    ‫على نفســه مقبول ) املنثور من القواعد للزركشــي (‪ )188/1‬واألشــباه‬\n                             ‫والنظائر للسيوطي (‪ )465/1‬ودرر احلكام (‪)79/1‬‬\n                 ‫‪-2‬الفقرة الثانية من املادة (‪ )3‬من نظام مكافحة املخدرات‬\n                ‫‪-3‬الفقرة األولى من املادة (‪ )56‬من نظام مكافحة املخدرات‬\n\n\n\n\n    ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n    ‫واحلبــوب احملظــورة وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم‬\n    ‫عليــه بالعقوبــة الــواردة مــن نظــام مكافحــة املخــدرات‪ ،‬اســتند املدعــي‬\n    ‫العــام يف دعــواه علــى ‪ :‬اعتــراف املدعــى عليــه مبــا أســند إليــه مبحضــر‬\n    ‫القبــض وبتحليــل عينــه مــن ســوائله أثبــت تقريــر الســموم الشــرعي‬\n    ‫إيجابيتهــا ملــادة احلشــيش املخــدر و مــادة اإلمفيتامــن وأقــر املدعــى عليــه‬\n    ‫بتعاطــي احلشــيش و حبــوب اإلمفيتامــن بنــاء علــى مــا تقــدم حكمــت‬\n‫‪5‬‬\n\f‫احملكمــة بثبــوت تعاطــي املدعــى عليــه للحشــيش املخــدر و جلــده حــد‬\n‫املســكر ثمانــن جلــده دفعــة واحــدة ‪ ،‬ثبــت تعاطيــه للحبــوب احملظــورة‬\n‫و االكتفــاء بحــد املســكر وصــرف النظــر عــن طلــب املدعــي العــام‬\n‫تطبيــق العقوبــه الــواردة يف (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n‫املخــدرات وذلــك اكتفــاء بإقامــة حــد املســكر ‪ ،‬منــع املدعــى عليــه مــن‬\n‫الســفر ملــدة ســنتني وال يغــادر وأخــذ التعهــد الشــديد علــى املدعــى عليــه‬\n‫بعــدم تكــرار مابــدر منــه وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                    ‫‪6‬‬\n\f    ‫احلمــدهلل وحــده وبعــد فلــدي أنــا املــازم القضائــي باحملكمــة اجلزائيــة‬\n    ‫باألحســاء يف املكتــب القضائــي الســادس وبنــاء علــى املعاملــة احملالــة‬\n    ‫من رئيس احملكمة اجلزائية باألحســاء برقم (‪ ).........‬يف ‪1434/1/3‬هـ‬\n    ‫واملقيــدة برقــم (‪ )........‬يف ‪1434/1/3‬ه ـ وبنــاء علــى تعميــدي مــن فضيلة‬\n    ‫الشــيخ‪ /‬رئيــس احملكمــة اجلزائيــة باألحســاء املكلــف مبوجــب خطابــه‬\n    ‫رقــم (‪ )................‬يف ‪1434/6/26‬هــ  لنظــر القضايــا مــا عــدا الســجناء‬\n    ‫ويف يــوم الثالثــاء املوافــق ‪1434/7/18‬ه ـ افتتحــت اجللســة األولــى يف‬\n    ‫متــام الســاعة احلاديــة عشــر صباحـ ًا يف هــذه القضيــة رقــم (‪ )........‬وفيهــا‬\n    ‫حضــر املدعــي العــام الســعودي بالســجل املدنــي رقــم (‪ ).............‬وحضــر‬\n    ‫حلضــوره املدعــى عليــه الســعودي بالســجل املدنــي رقــم (‪ )...............‬وبنــاء‬\n    ‫علــى األوراق املثبتــة يف املعاملــة بــأن املدعــى عليــه مطلــق ســراحه لــذا‬\n    ‫فقــد قــررت نظــر الدعــوى هــذا فتــم ســؤال املدعــي العــام عــن دعــواه‬\n    ‫قــال بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء‬\n    ‫أدعــي علــى ‪ /‬البالــغ مــن العمــر (‪ )...‬عام ـ ًا ســعودي اجلنســية مبوجــب‬\n    ‫الســجل املدنــي رقــم (‪ ).............‬متســبب محصــن قبــض عليــه بتاريــخ‬\n    ‫‪1433/11/20‬ه ـ وأوقــف مبوجــب أمــر اإليقــاف الصــادر مــن دائــرة‬\n    ‫التحقيــق واالدعــاء العــام مبحافظــة األحســاء برقــم (ه ـ ق ‪)......././.‬‬\n    ‫وتاريــخ ‪1433/11/21‬ه ـ وفق ـ ًا لبرقيــة وزيــر الداخليــة رقــم (‪/5/1‬‬\n    ‫‪ )..............‬وتاريــخ ‪1432/12/20‬ه ـ وجــرى التمديــد لــه ملــدة (‪ )25‬يومـ ًا‬\n    ‫بأمــر التمديــد الصــادر مــن فــرع الهيئــة باملنطقــة الشــرقية برقــم (ه ـ ق‬\n    ‫‪ )55766/5/1‬يف ‪1433/11/27‬ه ـ وأحيــل إلــى شــعبة ســجن محافظــة‬\n\n‫‪7‬‬\n\f‫األحســاء أنــه بتاريــخ ‪1433/11/20‬ه ـ مت القبــض عليــه مــن قبــل مركز‬\n‫شــرطة التابعــة حملافظــة األحســاء بقضيــة قفــز علــى منــزل (فــرزت لهــا‬\n‫أوراق مســتقلة ومعاجلتهــا مــن قبــل جهــة االختصــاص وبتحليــل عينــة مــن‬\n‫ســوائله أثبــت التقريــر الســموم الشــرعي رقــم (‪........‬م أ) لعــام ‪1433‬ه ـ‬\n‫إيجابيتهــا ملــادة احلشــيش املخــدر واملــدرج يف اجلــدول (‪ )1‬فئــة (أ) ومــادة‬\n‫االمفيتامــن احملظــور واملــدرج يف اجلــدول (‪ )2‬فئــة (ب) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة وبضبــط أقــوال املدعــى عليــه‬\n‫‪ /‬أقــر بتعاطــي احلشــيش املخــدر وحبــوب األمفيتامــن املنبــه احملظــور‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بتعاطــي احلشــيش املخــدر‬\n‫واحلبــوب احملظــورة وذلــك لألدلــة والقرائــن التاليــة ‪ -1‬اعترافــه املنــوه‬\n‫عنــه املــدون علــى الصفحــة رقــم (‪ )2‬مــن دفتــر االســتدالل لفــه رقــم (‪)10‬‬\n‫‪ -2‬مــا جــاء يف محضــر القبــض املــدون علــى الصفحــة رقــم (‪ )11‬مــن‬\n‫دفتــر االســتدالل لفــه رقــم (‪ -3 )3‬مــا جــاء يف خطــاب مديــر مركــز‬\n‫شــرطة العيــون املرفــق لفــة رقــم (‪ -4 )3‬مــا جــاء يف التقريــر الســموم‬\n‫الشــرعي املرفــق علــى اللفــة رقــم (‪ )2‬وبالبحــث عمــا إذا كان لــه‬\n‫ســوابق تبــن وجــود ســابقتني األولــى مضاربــة والثانيــة حيــازة واســتعمال‬\n‫مخــدرات بتاريــخ ‪1431/3/7‬ه ـ وحيــث إن مــا أقــدم عليــه املذكــور‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم‬\n‫(م‪ )39/‬تاريــخ ‪1426/7/8‬ه ـ أطلــب أثبــات مــا أســند إليــه واحلكــم عليه‬\n‫مبــا يلــي ‪ -1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة رقــم (‪ )41‬مــن‬\n                                                   ‫النظــام املشــار إليــه لقــاء مــا‬\n\n\n                                                                                          ‫‪8‬‬\n\f    ‫أســند إليــه مــن اتهــام ‪ -2‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة‬\n    ‫(‪ )56‬مــن النظــام مبنعــه مــن الســفر ‪ .‬هــذه دعــواي وبســؤال املدعــى عليــه‬\n    ‫عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام مــن‬\n    ‫قيامــي بتعاطــي احلشــيش املخــدر واحلبــوب احملظــورة فصحيــح وأنــا‬\n    ‫تائــب إلــى اهلل ونــادم علــى مــا بــدر منــي هــذه إجابتــي هــذا فتــم ســؤاله‬\n    ‫عــن عمــره فقــال أبلــغ مــن العمــر ثالثــن عامــا هكــذا قــال كمــا مت‬\n    ‫ســؤاله عــن عملــه فقــال أعمــل يف شــركة الغــاز هكــذا قــال كمــا مت‬\n    ‫ســؤاله هــل أنــت محصــن ولديــك أطفــال فقــال نعــم هكــذا قــال هــذا‬\n    ‫فتــم اطالعــي علــى شــهادة ســوابق املدعــى عليــه املرفقــة يف املعاملــة علــى‬\n    ‫اللفــة رقــم (‪ )22‬وتتضمــن (وجــود ســابقة واحــدة وهــي ســرقة حيوانــات)‬\n    ‫أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه قــال الســابقة صحيحــة وقــد أخــذت‬\n    ‫جزائــي عليهــا هكــذا قــال كمــا مت اطالعــي تقريــر الســموم الشــرعي‬\n    ‫املرفــق يف املعاملــة علــى اللفــة رقــم (إيجابيــة عينــة البــول ملركبــات‬\n    ‫احلشــيش املخــدر وملركــب اإلمفيتامني)أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن‬\n    ‫الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بدعــوى املدعــي العــام‬\n    ‫ولكــون هــذا اإلقــرار قــد صــدر مــن مكلــف ‪ -‬عاقــل بالــغ‪ -‬وللقاعــدة‬\n    ‫الفقهيــة ((أن املــرء مؤاخــذ بإقــراره)) والقاعــدة ((إقــرار اإلنســان علــى‬\n    ‫نفســه مقبــول)) املنثــور مــن القواعــد للزركشــي [ج‪ ]188/1‬واألشــباه‬\n    ‫والنظائــر للســيوطي [ج‪ ]465/1‬ودرر احلــكام [ج‪ ]79/1‬وبعــد االطــاع‬\n    ‫علــى تقريــر الســموم الشــرعي لذلــك كلــه‪ :‬أوال‪ :‬ثبــت لــدي تعاطــي‬\n    ‫املدعــى عليــه للحشــيش املخــدر وقــررت جلــده حــد املســكر ثمانــن‬\n    ‫جلــدة حــدا دفعــة واحــدة علن ـاً‪ .‬ثانيــا‪ :‬ثبــت لــدي تعاطــي املدعــى عليــه‬\n    ‫للحبــوب احملظــورة واكتفيــت مبــا مت احلكــم عليــه يف الفقــرة أوال‪.‬‬\n\n\n‫‪9‬‬\n\f‫ثالثــا‪ :‬صرفــت النظــر عــن طلــب املدعــي العــام مــن تطبيــق العقوبــة‬\n‫علــى املدعــى عليــه الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات وذلــك اكتفــاء مبــا مت احلكــم عليــه يف الفقــرة‬\n‫أوال‪ .‬رابعــا‪ :‬ونظــرا لثبــوت تعاطــي املدعــى عليــه للحشــيش املخــدر‬\n‫واحلبــوب احملظــورة وهــذه اجلرميتــان نصــت عليهــا الفقــرة الثانيــة مــن‬\n‫املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات وبنــاء علــى الفقــرة األولــى‬\n‫مــن املــادة (‪ )56‬مــن نفــس النظــام لــذا فقــد قــررت منــع املدعــى عليــه‬\n‫مــن الســفر خــارج اململكــة ملــدة ســنتني وال يغــادر اململكــة لضــرورة إال‬\n‫بــأذن مــن وزيــر الداخليــة‪ .‬خامســا‪ :‬أخــذ التعهــد الشــديد علــى املدعــى‬\n‫عليــه بعــدم تكــرار مــا بــدر منــه ومبــا ســبق كلــه حكمــت وبعرضــه‬\n‫علــى املدعــى عليــه قــرر القناعــة بــه كمــا قــرر املدعــي العــام املعارضــة‬\n‫عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة اعتراضيــة‬\n‫وبذلــك تكــون القضيــة منتهيــة وعليــه فقــد قــررت بعــث كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف بالشــرقية لتدقيــق احلكــم حســب املتبــع‬\n‫وبــاهلل التوفيــق واختتمــت اجللســة يف متــام الســاعة التاســعة وللبيــان حــرر‬\n‫يف  ‪1434/7/18‬ه ـ ـ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                         ‫وســلم تســليما كثيــرا‪.‬‬\n‫     احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/1942831‬ج‪ 2‬وتاريــخ ‪1434/08/10‬ه ـ‬\n‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف برقــم ‪ 341669167‬وتاريــخ ‪1434/08/03‬ه ـ املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ‪/‬‬\n\n\n                                                                                      ‫‪10‬‬\n\f     ‫املســجل برقــم وتاريــخ ‪1434/07/24‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام  ‬\n       ‫ضد‪/‬املدعــى عليــه يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه  ‬\n       ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n           ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/21‬هــ‪.‬‬\n\n\n\n\n‫‪11‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":5,"source_page_end":11,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"67520a4d0c60faf66433843c43a32554f57300477f5a4a19c2ccdffaf66e8afd","normalized_text_hash":"86edc488829229717829fe57eb0d809cf49d539b1bac73a26a94a0436ddbc300","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p5-34277360"},{"id":"45eb5959-21ea-5d13-88be-10385855e96e","document_type":"judgment","category":"judicial","subcategory":"general","title":"تعاطي الشمة -ترويج الشمة -ترويج واستعمال مقاطع جنسية - عدم اكتمال نصاب الشهادة ال يثبت به الواقعة اجلنائية إال أنها قرينة مورثة للتهمة ( الشبهة ) املوجبة للتعزير -التعزير بالسجن واجللد -صرف النظر عن املصادرة والغرامة لعدم ثبوت اإلدانة.","document_number":"34440072","case_number":"349674","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"تعاطي الشمة -ترويج الشمة -ترويج واستعمال مقاطع جنسية - عدم اكتمال نصاب الشهادة ال يثبت به الواقعة اجلنائية إال أنها قرينة مورثة للتهمة ( الشبهة ) املوجبة للتعزير -التعزير بالسجن واجللد -صرف النظر عن املصادرة والغرامة لعدم ثبوت اإلدانة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 34440072:‬تاريخه‪1434/2/23 :‬هـ‬\n                        ‫رقم الدعوى‪349674 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n     ‫تاريخه‪1434/7/5 :‬هـ‬         ‫‪34260338‬‬\n\n\n\n‫تعاطــي الشــمة ‪ -‬ترويــج الشــمة ‪ -‬ترويــج واســتعمال مقاطــع جنســية ‪-‬‬\n‫عــدم اكتمــال نصــاب الشــهادة ال يثبــت بــه الواقعــة اجلنائيــة إال أنهــا‬\n‫قرينــة مورثــة للتهمــة ( الشــبهة ) املوجبــة للتعزيــر ‪ -‬التعزيــر بالســجن‬\n    ‫واجللــد ‪ -‬صــرف النظــر عــن املصــادرة والغرامــة لعــدم ثبــوت اإلدانــة‪.‬‬\n\n\n\n\n                                     ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بحيــازة كميــة‬\n‫كبيــرة مــن الشــمة بقصــد الترويــج والتعاطــي وحيــازة صــور ومقاطــع‬\n‫جنســية وتخزينهــا يف جهــازي احلاســب اآللــي وجهــاز اجلــوال بقصــد‬\n‫الترويــج وطلــب إثبــات ذلــك ‪ ،‬ورد بــاغ لهيئــة األمــر باملعــروف والنهــي‬\n‫عــن املنكــر عــن قيامــه بذلــك خــال عملــه مبحــل بيــع اجلــوالت فجــرى‬\n‫االنتقــال للمحــل فعثــر بحوزتــه مــادة الشــمة معــدة للبيــع ويف جهــازه‬\n‫احلاســوب مقاطــع إباحيــة ‪ ،‬أنكــر املدعــى عليــه التهــم املوجهــة إليــه‬\n‫ودفــع بأنــه يعمــل يف محــل بيــع وصيانــة أجهــزة اجلــوال وقــد حضــر لديــه‬\n‫مجموعــة مــن املعتمريــن ووضعــوا أكياســا لهــم يف احملــل وكانــت هــذه‬\n‫الشــمة داخــل األكيــاس وال عالقــة لــه بهــا كمــا أنكــر بــأن جهــاز‬\n\n                                                                                   ‫‪12‬‬\n\f     ‫احلاســب اآللــي احملمــول واجلــوال يعــودان لــه وقــرر بــأن اجلهــاز احملمــول‬\n     ‫تركــه عميــل عنــده إلصالحــه‪ ،‬أحضــر املدعــي العــام شــاهدا يعمــل‬\n     ‫عضــوا يف هيئــة األمــر باملعــروف والنهــي عــن املنكــر وشــهد بأنــه ورد‬\n     ‫بــاغ أن املدعــى عليــه يقــوم ببيــع مادة الشــمة فانتقل مــع الفرقة القابضة‬\n     ‫للمحــل فعثــر حتــت الطاولــة املعــروض فيهــا األجهــزة كيســا يحتــوي‬\n     ‫علــى (‪ )248‬كيــس صغيــر بــه مــادة الشــمة كمــا عثــر بحوزتــه جهــاز‬\n     ‫حاســب آلــي محمــول يحتــوي علــى مقاطــع مرئيــة جنســية وعثــر معــه‬\n     ‫علــى جهــاز جــوال يحتــوي علــى صــور جنســية ‪ ،‬جــرى عــرض الشــاهد‬\n     ‫وشــهادته علــى املدعــى عليــه فقــرر بأنــه ال يعلــم عــن الشــاهد شــيئا أمــا‬\n     ‫شــهادته فالصحيــح مــا ورد يف جوابــه ‪ ،‬طلــب مــن املدعــي العــام إحضــار‬\n     ‫زيــادة بينــة فطلــب مهلــة ‪ ،‬ثــم قــرر املدعــي العــام بأنــه طلــب البينــة أكثــر‬\n     ‫مــن مــرة فلــم حتضــر وطلــب احلكــم بالقضيــة اكتفــاء بشــهادة الشــاهد‬\n     ‫ومــا ورد يف أوراق املعاملــة ‪ ،‬جــرى الرجــوع ألوراق املعاملــة فعثــر علــى‬\n     ‫اعتــراف للمدعــى عليــه حتقيقــا بتعاطــي الشــمة ‪ ،‬وإلنــكار املدعــى‬\n     ‫عليــه وملــا دفــع بــه ‪ ،‬وبنــاء علــى شــهادة الشــاهد ‪ ،‬ونظــرا لتوجــه الشــبهة‬\n     ‫جتــاه املدعــى عليــه ولعــدم وجــود ســوابق مســجلة عليــه فقــد قــررت‬\n     ‫احملكمــة عــدم ثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه بالدعــوى‬\n     ‫وقــررت للشــبهة جتاهــه ســجنه شــهرين يحســب منهــا املــدة التــي أوقــف‬\n     ‫فيهــا ألجــل القضيــة وجلــده ســتون جلــدة دفعــة واحــدة ولــم حتكــم‬\n     ‫باملصــادرة وال الغرامــة لعــدم ثبــوت التهمــة‪ ،‬بعــرض احلكــم عليهمــا‬\n     ‫قــررا االعتــراض عليــه وأفهمــا بتعليمــات االســتئناف ‪ ،‬قــدم املدعــى‬\n     ‫عليــه الئحــة اعتراضيــة بينمــا لــم يقــدم املدعــي العــام بعــد مضــي املــدة‬\n     ‫املقــررة لــذا جــرى رفــع احلكــم حملكمــة االســتئناف ‪ ،‬صــدق احلكــم‬\n\n\n‫‪13‬‬\n\f                                                    ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد يف يــوم‬\n‫الثالثــاء املوافــق ‪1433/1/28‬هــ  لــدي أنــا ‪...........‬القاضــي يف احملكمة‬\n‫ـاء على املعاملــة احملالة من رئيس احملكمة‬       ‫اجلزائيــة مبكــة املكرمــة بنـ ً‬\n‫برقــم ‪ 332077757‬وتاريــخ ‪1433/11/21‬ه ـ فتحــت اجللســة الســاعة‬\n‫الثانيــة عشــرة وثالثــون دقيقــة وفيهــا حضــر املدعــي العــام ‪...........‬وادعــى‬\n‫قائــا يف دعــواه أدعــي علــى هــذا احلاضــر معــي باملجلــس الشــرعي‪/‬‬\n‫‪......................‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...........‬أن‬\n‫التحقيــق يدينــه بحيــازة كميــة كبيــرة مــن مــادة الشــمة بقصــد الترويــج‬\n‫والتعاطــي وحيــازة صــور ومقاطــع جنســية وتخزينهــا يف جهــازي احلاســب‬\n‫اآللــي وجهــاز جوالــه لغــرض الترويــج ‪ ،‬أطلــب إثبــات ذلــك واحلكــم عليه‬\n‫بعقوبــة تعزيريــة لقــاء ترويجــه وتعاطيــه مــادة الشــمة وحيازتــه لهــا لغــرض‬\n‫الترويــج والســجن والغرامــة وفقــا للفقــرة (‪ )1‬مــن املــادة (‪ )6‬مــن نظــام‬\n‫مكافحــة اجلرائــم املعلوماتيــة الصــادر باملرســوم امللكــي رقــم (‪)79‬‬\n‫وتاريــخ ‪1428/3/7‬ه ـ ومبصــادرة جهــاز اجلــوال مــن نــوع ‪ .......‬ورقمــه‬\n‫املصنعــي (‪ ).......‬وجهــاز الالبتــوب مــن نــوع ‪ .....‬ورقمــه املصنعــي ‪.......‬‬\n‫وفقــا للمــادة (‪ )13‬مــن نظــام املشــار إليــه ‪ ،‬وبســؤال املدعــى عليــه عــن‬\n‫الدعــوى أجــاب قائـاً‪ :‬مــا ذكــره املدعــي العــام مــن حيازتــي مادة الشــمة‬\n‫بقصــد الترويــج والتعاطــي وحيازتــي صــور ًا ومقاطــع جنســية وتخزينهــا‬\n‫يف جهــاز حاســب آلــي وجهــاز جــوال عائديــن لــي لغــرض الترويــج غيــر‬\n‫صحيــح والصحيــح هــو أنــي أعمــل يف محــل لبيــع وصيانــة أجهــزة اجلــوال‬\n\n                                                                                       ‫‪14‬‬\n\f     ‫وقــد حضــر لــدي مجموعــة مــن املعتمريــن ووضعــوا أكياس ـ ًا لهــم لــدي‬\n     ‫يف احملــل وكانــت هــذه الشــمة داخــل هــذه األكيــاس وال عالقــة لــي‬\n     ‫بهــا وأمــا الصــور واملقاطــع اجلنســية التــي يف احلاســب اآللــي فقــد أحضــر‬\n     ‫هــذا اجلهــاز رجــل يطلــب منــي فحــص اجلهــاز وذهــب بعــد ذلــك وال عالقــة‬\n     ‫لــي بهــذا احلاســب اآللــي ومــا يحتويــه وأمــا جهــاز اجلــوال الــذي يحتــوي‬\n     ‫علــى مــا ذكــر فليــس عائــد ًا لــي هكــذا أجــاب ثــم ســألت املدعــي العــام‬\n     ‫بينتــه فقــال أطلــب إمهالــي إلحضارهــا هكــذا أجــاب لــذا قــررت رفــع‬\n     ‫اجللســة لذلــك  ويف يــوم الثالثــاء املوافــق ‪1434/1/6‬ه ـ فتحــت اجللســة‬\n     ‫الســاعة العاشــرة وفيهــا حضــر املدعــى عليــه كمــا حضــر يف اجللســة‬\n     ‫‪......................‬ســعودي بالســجل املدنــي رقــم ‪...........‬وبســؤاله عمــا لديــه‬\n     ‫مــن شــهادة قــال ‪ :‬أعمــل عضــوا يف هيئــة األمــر باملعــروف والنهــي عــن‬\n     ‫املنكــر وأشــهد هلل تعالــى أنــه وردنــا مــا يفيــد أن املدعــى عليــه يعمــل‬\n     ‫مبحــل لبيــع اجلــواالت وأنــه يقــوم ببيــع مــادة الشــمة عنــد ذلــك انتقلــت‬\n     ‫رفــق الفرقــة القابضــة للمحــل ووجــدت حتــت الطاولــة املعــروض فيهــا‬\n     ‫أجهــزة اجلــوال كيس ـ ًا يحتــوي علــى (‪ )248‬كيس ـ ًا صغيــر ًا بــه مــادة‬\n     ‫الشــمة كمــا وجــدت بحوزتــه جهــاز حاســب آلــي محمــول يحتــوي علــى‬\n     ‫مقاطــع فيديــو جنســية وكذلــك عثــر معــه علــى جهــاز جوالــه يحتــوي‬\n     ‫أيضـ ًا علــى صــور جنســية هــذا مــا لــدي وبــه أشــهد جــرى عــرض الشــاهد‬\n     ‫وشــهادته علــى املدعــى عليــه فقــال أمــا هــو  فــا أعلــم عنــه شــيئ ًا وأمــا‬\n     ‫شــهادته فالصحيــح مــا ذكرتــه يف إجابتــي يف اجللســة املاضيــة هكــذا‬\n     ‫أجــاب ثــم ســألت املدعــي العــام زيــادة بينــة علــى دعــواه فقــال أطلــب‬\n     ‫إمهالــي إلحضارهــا هكــذا أجــاب لــذا قــررت رفــع اجللســة لذلــك ويف‬\n     ‫يــوم الثالثــاء املوافــق ‪1434/2/19‬ه ـ فتحــت اجللســة الســاعة العاشــرة‬\n\n\n‫‪15‬‬\n\f‫وأربعــون دقيقــة وفيهــا حضــر املدعــى عليــه وجــرى ســؤال املدعــي العــام‬\n‫عــن بينتــه التــي اســتمهل ألجلهــا فقــال مت طلــب البينة ثالث مرات حســب‬\n‫صــور طلبــات حضورهــم املرفقــة ولــم يحضــر منهــم إال شــاهد واحــد‬\n‫أطلــب احلكــم يف القضيــة هكــذا أجــاب اطلعــت بعــد ذلــك علــى أوراق‬\n‫املعاملــة فوجــدت ضمنهــا محضــر االطــاع واملعاينــة املرفــق لفــة رقــم‬\n‫(‪)18‬صحيفــة رقــم (‪ )4‬وإقــراره حتقيقـ ًا بتعاطــي الشــمة املرفــق لفــة رقــم‬\n‫(‪ )18‬صحيفــة رقــم (‪ )2‬وهمــا كمــا ذكــر املدعــي العــام فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واجلــواب وإنــكار املدعــى عليــه دعــوى املدعــي العــام‬\n‫ومــا دفــع بــه ســلف ًا وبنــاء علــى مــا تضمنتــه شــهادة الشــاهد املرصــودة‬\n‫ســلف ًا وكونــه عضــو ًا يف هيئــة األمــر باملعــروف والنهــي عــن املنكــر وال‬\n‫بينــة للمدعــي العــام علــى دعــواه إال هــذا الشــاهد ونظــر ًا لتوجــه الشــبهة‬\n‫جتــاه املدعــى عليــه وال ســوابق عليــه ولــكل مــا تقــدم لــم يثبــت لــدي‬\n‫إدانــة املدعــى عليــه مبــا نســب إليــه يف دعــوى املدعــي العــام وحكمــت‬\n‫علــى املدعــى عليــه لقــاء توجــه الشــبهة جتاهــه بســجنه مــدة شــهرين‬\n‫يحتســب منهــا مــدة إيقافــه بســبب هــذه القضيــة وجلــده ســتون جلــدة‬\n‫دفعــة واحــدة وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر‬\n‫املدعــي العــام اعتراضــه عليــه بالئحــة اعتراضيــة وقــرر املدعــى عليــه‬\n‫اعتراضــه عليــه بالئحــة اعتراضيــة جــرى إفهامــه مبراجعــة احملكمــة‬\n‫يــوم الثالثــاء املوافــق ‪1434/2/26‬ه ـ الســتالم صــورة مــن إعــام احلكــم‬\n‫وتقــدمي الئحتــه االعتراضيــة عليهــا خــال ثالثــن يوم ـ ًا فــإن تأخــر عــن‬\n‫ذلــك ســقط حقــه يف تقــدمي االعتــراض وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن جــرى النطــق باحلكــم‬\n                               ‫الســاعة احلاديــة عشــرة بتاريــخ ‪1434/2/19‬ه ـ‬\n\n\n                                                                                      ‫‪16‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة‬\n     ‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 349674‬وتاريــخ‬\n     ‫‪1434/01/06‬هــ   املقيــدة باحملكمــة برقــم ‪ 3444007‬وتاريــخ‬\n     ‫‪1434/1/6‬هــ  ففــي يــوم  االثنــن املوافق‪1434/03/02‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة الثامنــة وفيهــا حضــر املدعــى عليــه ‪...........‬املذكــور‬\n     ‫واســتلم صــورة مــن إعــام احلكــم الصــادر منــا برقــم ‪ 3444072‬وتاريــخ‬\n     ‫‪1434/02/23‬ه ـ وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n     ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/2‬ه ـ ويف يــوم االثنــن املوافــق‬\n     ‫‪1434/5/13‬ه ـ فتحــت اجللســة الســاعة التاســعة وعشــرين دقيقــة‬\n     ‫وقــد قــدم املدعــى عليــه الئحتــه االعتراضيــة جــرى إرفاقهــا باملعاملــة‬\n     ‫وباالطــاع عليهــا لــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه ولــم يقــدم‬\n     ‫املدعــي العــام الئحتــه االعتراضيــة وقــد مضــت املــدة النظاميــة لذلــك لذا‬\n     ‫قــررت رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق‬\n     ‫حــرر الســاعة التاســعة وخمــس وعشــرين دقيقــة بتاريــخ ‪1434/5/13‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل  وبعــد ‪ ...‬نحــن رئيــس‬\n     ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة‬\n     ‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪3444072‬‬\n     ‫وتاريــخ ‪1434/2/23‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ .........../‬القاضــي‬\n     ‫باحملكمــة اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n     ‫ضــد‪........... /‬مينــي اجلنســية‪ ،‬املتهــم بحيــازة مــادة الشــمة بقصــد الترويــج‬\n     ‫والتعاطــي وحيــازة صــور ومقاطــع جنســية ‪ ،‬احملكــوم فيــه مبــا دون‬\n     ‫باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n\n\n‫‪17‬‬\n\f‫باألكثريــة  املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪18‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":12,"source_page_end":18,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9a8fe4f9783a518d0ed056efb021ec1b81101f42d6383272a8def7f8dd952385","normalized_text_hash":"a576eaf3740349fe39559c5038b5eee5b0fb80b92e5ee65d44802a181a7db324","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p12-34440072"},{"id":"ed39293a-668a-5217-bdc8-90d4ff2b3f5e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -الرجوع عن إقامة احلد -اثر املرض النفسي يف إسقاط احلد -درء احلد -التعزير باملنع من","document_number":"341083510","case_number":"3327661","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/26","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -الرجوع عن إقامة احلد -اثر املرض النفسي يف إسقاط احلد -درء احلد -التعزير باملنع من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 341083510 :‬تاريخه‪1434/06/26 :‬هـ‬\n                           ‫رقم الدعوى‪3327661 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪34274653‬تاريخه‪1434/07/22 :‬هـ‬\n\n\n     ‫مخــدرات ‪-‬تعاطــي احلشــيش املخــدر ‪ -‬الرجــوع عــن إقامــة احلــد ‪ -‬اثــر‬\n     ‫املــرض النفســي يف إســقاط احلــد ‪ -‬درء احلــد ‪ -‬التعزيــر باملنــع مــن‬\n                                                                       ‫الســفر ‪.‬‬\n\n\n\n\n     ‫ـاب‬\n      ‫نصـ ُ‬‫ال ْمـ ُـر َو ْالَ ْي ِسـ ُـر َوا َأل َ‬\n                                                ‫نــا ْ َ‬\n                                                       ‫آم ُنــو ْا ِإ َّ َ‬\n                                                                        ‫‪ -1‬قولــه تعالــى ‪َ ( :‬يــا َأ ُّي َهــا ا َّلذِ يـ َـن َ‬\n                  ‫ـوه َل َع َّل ُكـ ْـم ُت ْفل ُِحـ َ‬\n             ‫ـون )‪.‬‬                                            ‫الشـ ْي َطانِ فَ ْ‬\n                                                   ‫اج َتن ُِبـ ُ‬                   ‫َوا َأل ْز َال ُم ِر ٌْجــس ِّمـ ْـن َع َمــلِ َّ‬\n     ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم «كل مســكر خمــر وكل خمــر حــرام»‬\n                                                                                                                     ‫رواه مســلم‬\n     ‫‪ -3‬قــال ابــن حجــر‪ ( :‬اســتدل مبطلــق هــذا احلديــث علــى حتــرمي كل‬\n     ‫مــا يســكر ولــو لــم يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا )‬\n                                                                                                   ‫فتــح البــاري (‪)55/10‬‬\n                                                      ‫‪ -4‬املادة (‪ )3‬من نظام مكافحة املخدرات ‪.‬‬\n     ‫‪ -5‬قولــه صلــى اهلل عليــه وســلم ‪( :‬ادرؤوا احلــدود عــن املســلمني مــا‬\n     ‫اســتطعتم فــإن فوجــدمت للمســلم مخرج ـ ًا فخلــوا ســبيله فــإن اإلمــام‬\n     ‫ألن يخطــئ يف العفــو خيــر مــن أن يخطــئ يف العقوبــة ) اخرجــه‬\n                                                    ‫الترمــذي واحلاكــم والبيهقــي وغيرهــم ‪.‬‬\n\n\n\n\n‫‪19‬‬\n\f‫ادعــى املدعــي العــام ضــد املدعــى عليــه  بتعاطــي احلشــيش املخــدر‬\n‫وشــرب املســكر ‪ ،‬حيــث مت القبــض علــى املدعــى عليــه إثــر مشــاجرة‬\n‫وطلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه ‪ ،‬احلكــم عليــه‬\n‫بالعقوبــة الــواردة بالفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n‫املخــدرات ومنعــه مــن الســفر ‪ ،‬واحلكــم عليــه بحــد املســكر وبتحليــل‬\n‫عينــة البــول ثبتــت إيجابيتهــا ملركــب احلشــيش املخــدر‪ ،‬أقــر املدعــى‬\n‫عليــه بتعاطــي احلشــيش وأنكــر شــرب املســكر ‪ ،‬بنــاء علــى ماتقــدم‬\n‫صــدر احلكــم بإقامــة حــد املســكر واملنــع مــن الســفر ســنتني ‪ ،‬تقــدم‬\n‫والــد املدعــى عليــه باعتراضــه أن ابنــه مصــاب بانفصــام عقلــي و جــرت‬\n‫مكاتبــة املستشــفى للصحــة النفســية للتأكــد مــن ذلــك ‪ ،‬ورد اجلــواب‬\n‫بصحــة ذلــك وأن املدعــى عليــه أثنــاء ارتــكاب اجلرميــة لــم يكــن مدرك ًا‬\n‫لتصرفاتــه وأنــه ال يتحمــل اجللــد ورجــع فضيلتــه عــن حكمــه واكتفــى‬\n‫باملنــع مــن الســفر ســنة وتوبيخــه شــفهي ًا وصــدق احلكــم مــن محكمــة‬\n                                                                  ‫االســتئناف‬\n\n\n\n\n                                                                                 ‫‪20‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة اجلزئيــة مبحافظــة‬\n     ‫القطيــف   وبنــاء علــى املعاملــة احملالــة لنــا برقــم وتاريــخ ‪1433/01/10‬‬\n     ‫هــ  املقيــدة باحملكمــة برقــم  وتاريــخ ‪ 1433/01/10‬هــ  ففــي يــوم  ‬\n       ‫االثنــن املوافــق‪ 1433/01/10‬هــ  وفيهــا حضــر  املدعــي   العــام  وحضــر‬\n       ‫ا‬\n       ‫املدعــى عليــه ‪ .......‬ســعودي رقــم ســجله ملدنــي (‪ )......‬وادعــى األول قائـ ً‬\n       ‫إنــه بتاريــخ ‪1427/3/21‬ه ـ مت القبــض علــى املدعــى عليــه إثــر مضاربــة‬\n       ‫(مت معاجلــة قضيــة املضاربــة مــن قبــل جهــة االختصــاص) وبتحليــل عينــة‬\n       ‫بولــه تبــن إيجابيتهــا ملركــب احلشــيش املخــدر وفق ـ ًا لتقريــر الســموم‬\n       ‫الشــرعي رقــم (‪348‬م أ) وباســتجواب املتهــم املذكــور أقــر بصحــة‬\n       ‫واقعــة القبــض مضيفــا انــه يتعاطــى احلشــيش املخــدر ويتعاطــى الشــراب‬\n       ‫املســكر وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق‬\n       ‫مســجلة أطلــب مــن فضيلتكــم إثبــات مــا أســند إليــه وفق ـ ًا للفقــرة‬\n       ‫الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واحلكــم عليــه‬\n       ‫مبــا يلــي‪-1 :‬احلكــم عليــه بالعقوبــة الــواردة بالفقــرة (‪ )1‬مــن املــادة (‪)41‬‬\n       ‫مــن نظــام مكافحــة املخــدرات لتعاطــي احلشــيش املخدر‪-2‬منعــه مــن‬\n       ‫الســفر وفــق الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام ‪-3‬احلكــم عليــه‬\n       ‫بحــد املســكر لقــاء اعترافــه بشــرب املســكر وتعاطيــه احلشــيش‬\n       ‫املخــدر هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب قائــا مــا‬\n       ‫ذكــره املدعــي العــام مــن القبــض علــي بالتاريــخ املذكــور وأننــي كنــت‬\n       ‫متعاطي ـ ًا احلشــيش املخــدر صحيــح لكننــي ال أتعاطــى اخلمــر املســكر‬\n       ‫وقــد خضعــت لبرنامــج عــاج مــن اإلدمــان لــدى مجمــع األمــل للصحــة‬\n\n‫‪21‬‬\n\f‫النفســية  هكــذا أجــاب وبتصفــح املعاملــة جــرى االطــاع علــى التقريــر‬\n‫الكيمــاوي فوجدتــه كمــا ذكــره املدعــي العــام فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واجلــواب وإلقــرار املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n‫وألن مــا أقــدم عليــه فعــل محــرم شــرعا لقولــه تعالــى (( يــا أيهــا الذيــن‬\n‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n‫فاجتنبــوه )) املائــدة‪ 90 :‬ولقولــه صلــى اهلل عليــه وســلم (( كل مس ــكر‬\n‫خمــر وكل خمــر حــرام )) رواه مســلم قــال ابــن حجــر اســتدل مبطلــق‬\n‫هــذا احلديــث علــى حتــرمي كل مــا يســكر ولــو لــم يكــن شــراب ًا فيدخــل‬\n‫يف ذلــك احلشيشــة وغيرهــا فتــح البــاري ‪ 55/10‬كمــا أنــه فعــل مجــرم‬\n‫نظام ـ ًا وفق ـ ًا للمــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات فقــد ثبــت‬\n‫لــدي إدانــة املدعــى عليــه احلاضــر بتعاطــي احلشــيش املخــدر وحكمــت‬\n‫بجلــده حــد شــرب املســكر ثمانــن جلــده دفعــة واحــدة علنـ ًا ومنعــه مــن‬\n‫الســفر خــارج اململكــة ملــدة ســنتني بعــد اكتســاب احلكــم القطعيــة‬\n‫ورددت طلــب املدعــي العــام تطبيــق املــادة  (‪ )41‬مــن النظــام بحقــه لعــدم‬\n‫انطباقهــا عليــه وبإعــان احلكــم عليهمــا قــرر الطرفــان عــدم القناعــة‬\n‫وطلــب املدعــي العــام رفــع املعاملــة دون الئحــة وجــرى إفهــام املدعــى عليــه‬\n‫مراجعــة احملكمــة بتاريــخ ‪1433/2/1‬ه ـ الســتالم نســخة القــرار وأن له‬\n‫ثالثــون يومـ ًا لالعتــراض عليــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد اهلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق ‪1433/2/16‬هـ‬\n‫وقــد حضرســعودي رقــم ســجله املدنــي (‪ ).....‬بصفتــه الوكيــل الشــرعي‬\n‫عــن مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل محافظــة القطيــف‬\n‫برقــم ……………‪.‬وتاريــخ ‪1433/1/12‬ه ـ املخولــة لــه حــق االعتراض‬\n\n\n                                                                                      ‫‪22‬‬\n\f     ‫وقــدم مذكــرة اعتراضيــة مــن صفحــة واحــدة وخمــس مرفقــات‬\n     ‫ملخصهــا أن املدعــى عليــه كان شــبه غيــر مــدرك ملــا أقــر بــه وأنــه أدخــل‬\n     ‫مستشــفى ‪ ......‬للصحــة النفســية بتاريــخ ‪1426/5/2‬ه ـ واحلادثــة املشــار‬\n     ‫لهــا يف القــرار بعــد دخولــه املستشــفى ‪ ،‬واملدعــى عليــه مصــاب بانفصــام‬\n     ‫عقلــي مزمــن ومبــرض الســكري وجلــده يضاعــف حالتــه وطلــب عرضــه‬\n     ‫علــى املستشــفى للتأكــد مــن حالتــه ومــدى قدرتــه علــى اجللــد عليــه فقــد‬\n     ‫قــررت الكتابــة ملجمــع ‪ .....‬للصحــة النفســية لطلــب تقريــر عــن املدعــى‬\n     ‫عليــه وقــد ارتــكاب اجلــرم وإمكانيــة حتملــه اجللــد وصلــى اهلل علــى‬\n                                               ‫نبينــا محمــد وعلــى آلــه وصحبــه ســلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n     ‫القطيــف ففــي يــوم الســبت املوافــق‪ 1433/11/27‬ه ـ وفيهــا حضــر‬\n     ‫املدعــي العــام وكمــا حضــر ســعودي رقــم ســجله املدنــي () بصفتــه‬\n     ‫الولــي الشــرعي علــى املدعــى عليــه علــي مبوجــب صــك الواليــة الصــادر‬\n     ‫مــن احملكمــة العامــة مبحافظــة القطيــف برقــم  يف ‪1433/10/28‬ه ـ‬\n     ‫املتضمــن إقامــة احلاضــر ولي ـ ًا علــى ابنــه واملشــار فيــه لكتــاب مجمــع‬\n     ‫‪ .....‬للصحــة النفســية بــأن املذكــور علــي مصــاب بتخلــف عقلــي كمــا‬\n     ‫ســبق لنــا الكتابــة لســعادة مديــر مجمــع ‪ .....‬للصحــة النفســية بالدمــام‬\n     ‫لإلفــادة عــن حالــة املدعــى عليــه العقليــة والنفســية وقــت ارتــكاب‬\n     ‫اجلــرم يف ‪1427/3/13‬ه ـ ووردنــا منهــم التقريــر رقــم ……………‪.‬‬\n     ‫يف ‪1433/3/29‬ه ـ املتضمــن أنــه باالطــاع علــى ملفــه الطبــي تبــن أنــه‬\n     ‫مصــاب بحالــة التخلــف العقلــي مــن تاريــخ ســابق لتعاطــي املــواد املخــدرة‬\n     ‫وتــرى اللجنــة أنــه يف تاريــخ ارتكابــه للجــرم بتاريــخ ‪1427/3/13‬ه ـ‬\n     ‫ـاء‬\n      ‫لــم يكــن غالب ـ ًا مــدرك ًا لتصرفاتــه وبأنــه ال يتحمــل اجللــد‪ ،‬فبنـ ً‬\n\n‫‪23‬‬\n\f‫علــى مــا ســبق والحتمــال أن ال يكــون املدعــى عليــه بكامــل أهليتــه‬\n‫وقــت ارتــكاب اجلــرم ممــا يعــد شــبهة ُيــدرأ بهــا احلــد لقولــه صلــى اهلل‬\n‫عليــه وســلم « ادرؤوا احلــدود عــن املســلمني مــا اســتطعتم ‪ ،‬فــإن وجــدمت‬\n‫للمســلم مخرجــا ‪ ،‬فخلــوا ســبيله ‪ ،‬فــإن اإلمــام ألن يخطــئ يف العفــو‬\n‫خيــر مــن أن يخطــئ يف العقوبــة « أخرجــه الترمــذي واحلاكــم والبيهقــي‬\n‫وغيرهــم فقــد رجعــت عمــا حكمــت بــه مــن احلــد ونظــر ًا حلالــة املدعــى‬\n‫عليــه العقليــة والصحيــة فقــد اكتفيــت بتعزيــره باملنــع مــن الســفر خــارج‬\n‫اململكــة مــدة ســنة وتوبيخــه شــفهي ًا مــن قبــل احملكمــة بعــد اكتســاب‬\n‫احلكــم القطعيــة  وبإعــان احلكــم قــرر املدعــي العــام وولــي املدعــى‬\n‫عليــه اعتراضهمــا وطلبــا رفــع املعاملــة حملكمــة االســتئناف دون تقــدمي‬\n                         ‫الئحــة وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪0‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬رئيس احملكمــة اجلزائية مبحافظة‬\n‫القطيــف ففــي يــوم األربعــاء املوافق‪1434/02/13‬ه ـ فقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫رقــم بتاريخ‪1434/1/25‬ه ـ املتضمــن‪ :‬لوحــظ أن مــا حكــم بــه فضيلتــه‬\n‫مــن االكتفــاء مبنــع املدعــى عليــه مــن الســفر محــل نظــر لكــون املدعــى‬\n‫عليــه موظــف أهلــي ويتعاطــى املخــدرات ويســعى للحصــول عليهــا وعــدم‬\n‫تعزيــره بعــد درء احلــد ســبب لتماديــه وللعــودة ملثــل ذلــك ملالحظة ما ذكر‬\n‫وإكمــال الــازم أ‪ .‬هــ‪ .‬فأجيــب أصحــاب الفضيلــة بــأن املدعــى عليــه‬\n‫ليــس موظف ـ ًا أهلي ـ ًا وهــو متخلــف عقلــي وواقعــة التعاطــي مضــى عليهــا‬\n‫أكثــر مــن ســت ســنوات ولــم ترفــع عليــه دعــوى بهــذا اخلصــوص بعدهــا‬\n‫يف هــذه احملكمــة وهــو يخضــع للعــاج النفســي كمــا هــو موضــح يف‬\n‫التقاريــر واإلفــادات املرفقــة واملنــع مــن الســفر نــوع مــن التعزيــر عليــه فلــم‬\n\n\n                                                                                           ‫‪24‬‬\n\f     ‫يظهــر لــي مــا يوجــب العــدول عمــا حكمــت بــه ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية وبرفقهــا القــرار رقــم يف ‪1434/3/29‬هــ  املتضمــن‬\n     ‫لوحــظ أوالً‪ :‬أن مــا أجــاب بــه فضيلتــه علــى قــرار الدائــرة غيــر وجيــه‬\n     ‫حيــث إن املدعــى عليــه مقــر بتعاطــي احلشــيش املخــدر ومضــي املــدة‬\n     ‫ال يســقط األحــكام املترتبــة علــى اجلرميــة املنســوبة للمدعــى عليــه ال‬\n     ‫ســيما وأن املدعــى عليــه لــم يقــدم بينــة علــى مــا ذكــر مــن تخلــف عقلــي‬\n     ‫وفضيلتــه قبــل منــه اجلــواب علــى الدعــوى‪ .‬ثاني ـاً‪ :‬أن فضيلتــه أصــدر‬\n     ‫حكمــه الثانــي مــع بقــاء احلكــم األول ‪ ،‬فأجيــب أصحــاب الفضيلــة‬\n     ‫وفقنــي اهلل وإياهــم للصــواب باآلتــي‪ :‬أوالً‪ :‬أنــه تبــن أن إقــرار املدعــى‬\n     ‫عليــه أمــام احملكمــة لــم يكــن وهــو بكامــل أهليتــه وبالتالــي ال يثبــت‬\n     ‫بــه احلــد‪ .‬ثاني ـاً‪ :‬مضــي املــدة ال يســقط األحــكام املترتبــة علــى اجلرميــة‬\n     ‫لكنــه قــد يكــون ســبب ًا للتخفيــف أو اختيــار العقوبــة املالئمــة وهــذا‬\n     ‫مــا حصــل‪ .‬ثالث ـاً‪ :‬ولــي املدعــى عليــه قــدم بينــة علــى مــا ذكــر مــن‬\n     ‫تخلــف عقلــي هــي صــك الواليــة املرفــق نســخته يف املعاملــة لفــة (‪)44‬‬\n     ‫واملتضمــن شــهادة الشــاهدين بــأن املدعــى عليــه أصيــب بتخلــف عقلــي‬\n     ‫بعــد بلوغــه ســتة عشــر عام ـ ًا كمــا أن تقريــر مجمــع األمــل للصحــة‬\n     ‫النفســية املبنــى علــى كتابنــا تضمــن أن املدعــى عليــه لــم يكــن غالب ـ ًا‬\n     ‫مــدرك ًا لتصرفاتــه يف تاريــخ ارتكابــه للجــرم‪ .‬رابع ـاً‪ :‬بينــت أن قبــول‬\n     ‫احملكمــة اجلــواب كان قبــل تبــن إصابتــه بتخلــف عقلــي وال يخفــى‬\n     ‫علــى أصحــاب الفضيلــة أن بعــض أنــواع التخلــف العقلــي خاصــة النــاجت‬\n     ‫علــى تعاطــي املخــدرات واحلبــوب احملظــورة قــد ال يظهــر جلي ـ ًا للوهلــة‬\n\n\n‫‪25‬‬\n\f‫األولــى‪ .‬خامسـاً‪ :‬مــا جــاء يف املالحظــة الثانيــة مــن إصــداري احلكــم مــع‬\n‫بقــاء احلكــم األولــي فســبق أن صرحــت بالرجــوع عمــا حكمــت بــه مــن‬\n‫احلــد وفــات ســهو ًا التصريــح بالرجــوع عــن احلكــم الســابق باملنــع مــن‬\n‫الســفر ســنتني وأنــا أصــرح بالرجــوع عنــه اآلن وســيتم إعــادة املعاملــة‬\n                                       ‫حملكمــة االســتئناف حســب النظــام‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافق‪1434/06/25‬ه ـ فقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا‬\n‫القــرار رقمفي‪1434/6/7‬ه ـ املتضمــن ‪:‬لوحــظ أن مــا أجــاب بــه فضيلتــه‬\n‫علــى قــرار الدائــرة غيــر مقنــع حيــث إن املدعــى عليــه حــال القبــض عليــه‬\n‫يعمــل موظفـ ًا أهليـاً‪ .‬ويــدرك مــا أقدم عليه والواليــة التي صدرت عليه لم‬\n‫تصــدر إال بعــد انتهــاء محاكمتــه يف احملكمــة اجلزائيــة وعلــى فضيلتــه‬\n‫إعــادة التأمــل يف ذلــك أ‪.‬هــ‪ .‬فأجيــب أصحــاب الفضيلــة بــأن التحقــق مــن‬\n‫كــون املدعــى عليــه مــدرك ًا وقــت ارتــكاب اجلــرم يرجــع فيــه ألهــل‬\n‫اخلبــرة مــن األطبــاء وقــد أفــاد التقريــر الطبــي املشــار إليــه أن املدعــى‬\n‫عليــه مصــاب بتخلــف عقلــي مــع تاريــخ ســابق لتعاطــي املــواد املخــدرة‬\n‫وتــرى اللجنــة أنــه يف تاريــخ ارتكابــه للجــرم بتاريخ‪1427/3/13‬ه ـ لــم‬\n‫يكــن غالب ـ ًا مــدرك ًا لتصرفاتــه وتأخــر صــدور الواليــة غيــر مؤثــر إذ‬\n‫العبــرة بوقــت تدهــور قدراتــه العقليــة وليــس بتاريــخ اســتخراج الواليــة‬\n‫التــي قــد يتأخــر البعــض يف اســتخراجها لعــدة مبــررات ‪ ،‬وكــون‬\n‫التحقيــق تضمــن أن املدعــى عليــه موظــف أهلــي غيــر مؤثــر إذ كثيــر‬\n‫مــن العاطلــن حقيقــة يــدون اســمه يف ســجالت مؤسســات أهليــة ‪ ،‬لهــذا‬\n‫كلــه وملــا ســبق وبينتــه فلــم يظهــر مــا يوجــب العــدول عمــا حكمــت بــه ‪،‬‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                     ‫‪26‬‬\n\f       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزائيــة مبحافظة‬\n       ‫القطيــف والقائــم بعمــل فضيلــة رئيــس احملكمــة أثنــاء إجــازة فضيلتــه‬\n       ‫االعتياديــة وذلــك مبوجــب قــرار التكليــف رقــم  يف ‪1434/7/26‬ه ـ ويف‬\n     ‫هــذا اليــوم الســبت ‪1434/ 8 / 6‬ه ـ فتحــت اجللســة الســاعة ‪  11 : 30‬‬\n       ‫وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة محكمــة‬\n       ‫االســتئناف باملنطقــة الشــرقية رقــم   يف ‪1434/7/22‬ه ـ املتضمــن‬\n       ‫املصادقــة علــى احلكــم  وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره يف‬\n                                                                ‫متــام الســاعة ‪. 11 : 45‬‬\n\n\n\n\n‫‪27‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":19,"source_page_end":27,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5f24b1835af85059915ea837dac0d7acda9be743ec91ba05179f593ffdc52cb4","normalized_text_hash":"629691afc71d7521e5cda3b5da588dd51579a965b609126976720d33438ac6cf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p19-341083510"},{"id":"45a58380-5878-565c-a25e-76b68635cf6d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب املنبهة احملظورة -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باملنع من السفر .","document_number":"34264339","case_number":"3405001","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/10","year":"1434","subject":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب املنبهة احملظورة -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 34264339 :‬تاريخه ‪1434/7/10:‬هـ‬\n                       ‫رقم الدعوى‪3405001 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‬\n      ‫تاريخه‪1434/8/3 :‬هـ‬       ‫‪34287857:‬‬\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬تعاطــي‬\n‫احلبــوب املنبهــة احملظــورة ‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي‬\n                              ‫احلشــيش ‪ -‬التعزيــر باملنــع مــن الســفر ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعلى(يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n  ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون) ‪.‬‬\n     ‫‪ -2‬املادة (‪ )1/56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى العــام علــى املدعــى عليــه بتعاطــي احلشــيش املخــدر‪  ،‬‬\n  ‫وتعاطــي احلبــوب احملظــورة وطلــب املدعــي العــام بتعزيــره بالســجن‬\n  ‫واجللــد واملنــع مــن الســفر طبقـ ًا ألحــكام املــواد أرقــام (‪ )41‬و (‪ )56‬مــن‬\n  ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث أنــه أثنــاء قيــام‬\n  ‫الدوريــات األمنيــة مبهــام عملهــا لوحظــت ســيارة املدعــى عليــه وطلــب‬\n  ‫إيقافهــا رفــض الوقــوف وبعــد أن مت إيقافــه اعتــرف بتعاطــي احلشــيش‬\n  ‫املخــدر‪ ،‬كمــا أقــر املدعــى عليــه مبــا نســب إليــه ‪ ،‬بنــاء علــى ماتقــدم‬\n  ‫حكمــت احملكمــة علــى املدعــى عليــه بحــد املســكر والتعزيــر باملنــع‬\n  ‫مــن الســفر ‪ ،‬قــرر املدعــى العــام اعتراضــه علــى احلكــم بــدون الئحــة ‪،‬‬\n\n                                                                                      ‫‪28‬‬\n\f     ‫فيمــا قنــع املدعــى عليــه مبــا صــدر بحقــه مــن حكــم و ُصــدق احلكــم‬\n                                                 ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n     ‫برقــم وتاريــخ ‪ 1434 / 7 / 2‬ه ـ املقيــدة باحملكمــة برقــم  وتاريــخ ‪/ 2‬‬\n     ‫‪ 1434 / 7‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ .... /‬ضــد ‪ ، ..../‬ســعودي‬\n     ‫اجلنســية حســب بطاقــة الهويــة الوطنيــة رقــم (‪ ).......‬ففــي يــوم  االثنــن ‪10‬‬\n     ‫‪1434/ 7 /‬ه ـ فتحــت اجللســة الســاعة ‪  11 : 15‬وفيهــا حضــر  املدعــي‬\n     ‫العــام واملدعــى عليــه املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة‬\n     ‫الدعــوى املتضمنــة مــا يلــي ‪ ( :‬بصفتــي مدعي ـ ًا عامــا يف دائــرة التحقيــق‬\n     ‫واإلدعــاء العــام مبحافظــة القطيــف أدعــي علــى ‪ .......‬البالــغ مــن العمــر‬\n     ‫(‪ ، )26‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ،).......‬غيــر‬\n     ‫محصــن ‪ ،‬عاطــل ‪ ،‬املقبــوض عليــه بتاريــخ ‪1434/4/24‬ه ـ موقــوف‬\n     ‫علــى ذمــة قضيــة اخــرى باالطــاع علــى محضــر القبــض املعــد مــن  قبــل‬\n     ‫الدوريــات األمنيــة بالقطيــف بتاريــخ ‪1434/4/24‬ه ـ املتضمــن أنــه أثنــاء‬\n     ‫قيــام الدوريــة مبهــام عملهــا لوحظــت ســيارة مــن نــوع ‪ .....‬ومبتابعتهــا‬\n     ‫وطلــب اســتيقافها رفــض قائدهــا الوقــوف واجتهــت لداخــل احلــي‬\n     ‫وقامــت بصــدم مركبــة ولــم يتوقــف ودخــل باجتــاه وقــام بصــدم ســيارة‬\n     ‫أخــرى بعدهــا مت اســتيقاف املركبــة وبعــد الرفــع للعمليــات اتضــح‬\n     ‫أن قائــد الســيارة مطلــوب لشــرطة تــاروت بالتعميــم رقــم ‪ ....‬وتاريــخ‬\n     ‫‪1434/1/17‬ه ـ بقضيــة ســطو مســلح وباالطــاع علــى محضــر الفــرز‬\n\n‫‪29‬‬\n\f‫املعــد مــن قبــل دائــرة التحقيــق واإلدعــاء العــام بالقطيــف املتضمــن أنــه‬\n‫جــرى فــرز هــذه األوراق للمدعــى عليــه وذلــك إلقراره بتعاطــي املخدرات‪.‬‬\n‫وبســماع أقوالــه األوليــة لــدى الشــرطة أقــر بتعاطيــه احلشــيش بشــكل‬\n‫متقطــع وبســماع أقوالــه األوليــة لــدى مكافحــة املخــدرات أقــر بتعاطيــه‬\n‫احلشــيش املخــدر وحبــوب الــروش احملظــورة وباســتجوابه أقــر بتعاطيــه‬\n‫احلشــيش واحلبــوب وقــد أســفر التحقيــق عــن اتهامــه بتعاطــي احلشــيش‬\n‫وفقــا للفقــرة‬\n              ‫املخــدر وحبــوب اإلمفيتامــن املنبهــة واحملظــورة املجــرم ً‬\n‫رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪-1 :‬إقــراره حتقيقــا املنــوه عنــه‬\n‫واملــدون علــى الصفحــة رقــم ‪ 6‬واملرفــق لفــة رقــم ‪-2 .70‬إقــراره مبحضــر‬\n‫ســماع األقــوال األوليــة لــدى الشــرطة املنــوه عنــه واملــدون علــى الصفحــة‬\n‫رقــم ‪ 11‬واملرفــق لفــة رقــم‪-3 . 51‬إقــراره مبحضــر ســماع األقــوال األوليــة‬\n‫لــدى مكافحــة املخــدرات املنــوه عنــه واملــدون علــى الصفحــة رقــم‬\n‫‪2‬واملرفــق لفــة رقــم‪-4 . 79‬مــا ورد يف محضــر القبــض مــن وقائــع املنــوه‬\n‫عنهــا واملرفــق لفــة رقــم ‪ .60‬وبالبحــث عمــا إذا كان لــه ســوابق عثــر‬\n‫لــه علــى ســابقتني األولــى ترويــج املخــدرات وإهــداء املخــدرات والثانيــة‬\n‫حيــازة واســتعمال املخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور ‪-‬وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرعا ‪-‬فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا لــذا أطلــب إثبــات مــا أســند إليــه وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة‬\n‫رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم‬\n‫عليــه مبــا يلــي‪-1 :‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n‫رقــم (‪ )41‬مــن النظــام‪-2 .‬منعــه مــن الســفر وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )56‬مــن النظــام‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى‬\n\n\n                                                                                             ‫‪30‬‬\n\f     ‫علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف االتهــام املوجــه لــي كلــه‬\n     ‫صحيــح هــذا جوابــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n     ‫أقــر املدعــى عليــه مبــا نســب إليــه ممــا يســتوجب عقوبتــه ولقولــه تعالــى ‪:‬‬\n     ‫(يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n     ‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) وبنــاء علــى املــواد ‪ 2/3‬و‬\n     ‫‪ 1/56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة فقــد حكمــت‬\n     ‫مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n     ‫وحبــوب اإلمفيتامــن احملظــورة ‪ -2 .‬جلــد املدعــى عليــه ثمانــن جلــدة‬\n     ‫حــد املســكر أمــام مــأ مــن النــاس ‪ ،‬كمــا أفهمتــه بانطبــاق املــادة‬\n     ‫‪ 1/56‬مــن نظــام مكافحــة املخــدرات عليــه وهــي منعــه مــن الســفر مــدة‬\n     ‫ســنتني وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم قناعتــه‬\n     ‫ورغبتــه رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n     ‫وقــرر املدعــى عليــه قناعتــه وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره‬\n                                                             ‫يف متــام الســاعة ‪11 : 35‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد ‪1434/8/21‬ه ـ فتحــت اجللســة‬\n     ‫يف متــام الســاعة ‪ 11 : 30‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n     ‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم   يف‬\n     ‫‪1434/8/3‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1434/8/21‬ه ـ ‪.‬‬\n     ‫احلمد هلل وحده وبعد فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة األولى‬\n     ‫مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم  وتاريــخ‬\n\n\n‫‪31‬‬\n\f  ‫‪1434/7/15‬ه ـ املقيــدة لــدى احملكمــة برقــم  وتاريــخ ‪1434/7/18‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ املســجل برقــم  ‬\n  ‫وتاريــخ ‪1434/7/10‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام ‪ .....‬ضــد‪ ...../‬يف‬\n  ‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n  ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n  ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم حــرر يف ‪1434/8/2‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪32‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":28,"source_page_end":32,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ba921e45c9d09855daf78850f05690bd3676c6da487b2c00e7249b9541746a52","normalized_text_hash":"2acec27df41fc81130d298a1e57226f4a7e2a8b02879aedd314a0de3d3dc5bb8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p28-34264339"},{"id":"59e3fa07-9f48-5b77-8b66-41239d3067cc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلبوب احملظورة -وجود سوابق -إقرار - التعزير بالسجن واملنع من السفر -1الفقرة الثانية من املادة ( )3من نظام مكافحة املخدرات واملؤثرات","document_number":"3442047","case_number":"3425142","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/19","year":"1434","subject":"مخدرات -تعاطي احلبوب احملظورة -وجود سوابق -إقرار - التعزير بالسجن واملنع من السفر -1الفقرة الثانية من املادة ( )3من نظام مكافحة املخدرات واملؤثرات","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪   3442047 :‬تاريخه ‪1434/02/19 :‬هـ  ‬\n                             ‫رقم الدعوى‪3425142 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف  ‬\n                ‫‪    34191283‬تاريخه‪1434/04/17 :‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬تعاطــي احلبــوب احملظــورة ‪ -‬وجــود ســوابق ‪ -‬إقــرار ‪-‬‬\n                                          ‫التعزيــر بالســجن واملنــع مــن الســفر‬\n\n\n\n\n     ‫‪-1‬الفقــرة الثانيــة مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثرات‬\n                                                                             ‫العقلية‬\n     ‫‪-2‬الفقــرة األولــى مــن املــادة (‪ )41‬من نظام مكافحــة املخدرات واملؤثرات‬\n                                                                             ‫العقلية‬\n     ‫‪-3‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                            ‫العقليــة‬\n     ‫‪-4‬املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n                                                              ‫واملؤثــرات العقليــة‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتعاطــي احلبــوب احملظــورة‬\n     ‫وطلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه‬\n     ‫بعقوبــة الســجن واملنــع مــن الســفر وفق ـ ًا لنظــام مكافحــة املخــدرات‬\n     ‫املــواد أرقــام (‪ )41‬و (‪ )56‬ـ وجــود ســوابق علــى املدعــى عليــه حيــث مت‬\n     ‫القبــض علــى املدعــى عليــه أثنــاء مرافقتــه ألحــد املروجــن الــذي متكــن‬\n‫‪33‬‬\n\f‫مــن الهــرب ‪ -‬أقــر املدعــى عليــه بتعاطــي احلبــوب احملظــورة يف الســابق و‬\n‫أنــه أخــذ جــزاءه عليهــا مبوجــب حكــم ســابق واســتند املدعــي العــام يف‬\n‫دعــواه علــى إقــرار املدعــى عليــه حتقيقـ ًا بتعاطــي احلبــوب وصــدر احلكم‬\n‫بتعزيــر املدعــى عليــه لقــاء مانســب إليــه ولقــاء ســوابقه بالســجن واملنــع‬\n                  ‫مــن الســفروصدق احلكــم مــن محكمــة االســتئناف‪..‬‬\n\n\n\n\n                                                                                    ‫‪34‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n     ‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 34121887‬وتاريــخ ‪1434/1/14‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 3425142‬وتاريــخ ‪1434/1/14‬ه ـ‬\n     ‫افتتحــت اجللســة يف يــوم األربعــاء ‪1434/2/13‬ه ـ الســاعة الثامنــة‬\n     ‫والنصــف وفيهــا قــدم املدعــي العــام دعــواه ونصهــا اآلتي‪ :‬بصفتــي مدعي ًا‬\n     ‫عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪......../‬‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم  حيــث إنــه باالطــاع علــى‬\n     ‫محضــر االنتقــال والقبــض والتفتيــش املعــد مــن قبــل شــعبة مكافحــة‬\n     ‫املخــدرات بالدمــام تبــن أنــه بتاريــخ ‪1433/11/14‬ه ـ مت القبــض علــى‬\n     ‫املدعــى عليــه اثــر ورود بــاغ بشــان قيــام شــخص يدعــى ‪ ......‬هــارب‬\n     ‫(ســوف يتخــذ الــازم بحقــه فــور القبــض عليــه) بترويــج احلبــوب املنبهــه‬\n     ‫ـاء عليــه مت متكــن‬‫واحملظــورة وأنــه يســتخدم لذلــك اجلــوال رقــم   ‪ ......‬وبنـ ً‬\n     ‫املصــدر مــن االتصــال علــى املدعــو واتفــق معــه علــى شــراء حبــوب‬\n     ‫مخــدرة مببلــغ ‪ 100‬ريــال و اتفــق معــه  علــى أن يتقابــا خلــف ‪ ......‬يف‬\n     ‫مواقــف ‪ ......‬مــول وعليــه مت تزويــد املصــدر باملبلــغ احلكومــي املتفــق‬\n     ‫عليــه كمــا مت تكليــف أحــد أعضــاء الفرقــه مبرافقتــه و عنــد الوصــول‬\n     ‫الــى املوقــع املتفــق عليــه حضــرت ســيارة مــن نــوع  ‪ .......‬حتمــل اللوحــة‬\n     ‫رقــم (‪ ).......‬يســتقلها شــخص واحــد وتوقــف خلــف ســيارة املصــدر ثــم‬\n     ‫نــزل املصــدر وركــب معــه يف ســيارته وشــاهد عضــو الفرقــة القابضــة‬\n\n‫‪35‬‬\n\f  ‫عمليــه االســتالم والتســليم يف داخــل الســيارة وبعــد ذلــك نــزل املصــدر‬\n  ‫وســلم الكميــة املروجــة لعضــو الفرقــة وتبــن أنهــا عبــارة عــن (‪ )2‬حبتــن‬\n  ‫أثبــت التقريــر الكيمــاوي الشــرعي رقــم ( ‪ 4093‬ك ش ) و تاريــخ ‪21‬‬\n  ‫‪1433/11/‬ه ـ ايجابيتهــا ملــادة االمفيتامــن املنبهــه واحملظــوره ومت‬\n  ‫متابعــة قائــد املركبــة ولكــن يتــم التمكــن مــن القبــض عليــه يف حينــه‬\n  ‫ألنــه كان يســير بســرعة جنونيــة وبجمــع املعلومــات عــن املركبــة املنــوه‬\n  ‫عنهــا تبــن أنهــا مســتأجرة باســم مــن قبــل شــركة ‪  .......‬ومت التنســيق‬\n  ‫مــع موظــف الشــركة والــذي  قــام باالتصــال علــى املدعــو وطلــب منــه‬\n  ‫احضــار الســيارة املســتأجرة  وتســديد باقــي املســتحقات ويف الســاعه‬\n  ‫ـاء أفــاد املدعــو انــه قــادم لتســليمها وبعــد ذلــك حضــرت‬  ‫العاشــره مسـ ً‬\n  ‫السيارةاملســتأجرة وبرفقتهــا ســيارة اخــرى مــن نــوع ‪ .......‬حتمــل اللوحــه‬\n  ‫رقــم (‪ ).......‬وعنــد مشــاهدة ألفــراد الفرقــه قــام بالهــرب بالســيارة‬\n‫األخــرى ولــم يتــم التمكــن مــن القبــض عليــه ومت القبــض علــى مرافقــه  ‬\n  ‫اثنــاء تســليمه للسيارةاملســتأجرة وتبــن أنــه املدعــى عليــه ومبناقشــته‬\n  ‫عــن املدعــو اقــر بأنــه هــو الــذي هــرب بســيارته ومت االتصــال عــن طريقــه‬\n  ‫ولكنــه لــم يــرد علــى االتصــال وبســماع أقوالــه املدعــى عليــه أفــاد أن‬\n  ‫املدعــو اتصــل عليــه وطلــب منــه ان يقــوم بتوصليــه لتســليم الســيارة‬\n  ‫ملكتــب االيجــار ومت القبــض عليــه هنــاك و اقــر بتعاطيــه للحبــوب املنبهه‬\n  ‫واحملظــوره يف بعــض األحيــان وباســتجوابه أفــاد أن قــام باالتصــال عليــه‬\n  ‫وطلــب منــه مرافقتــه لتســليم السيارةاملســتأجرة ملكتــب التأجيــر وعنــد‬\n  ‫الوصــول إلــى املكتــب قــام بالنــزول وقابــل املوظــف وركــب يف ســيارته‬\n  ‫و لــم ينــزل معــه لكونــه كان يتصــل باجلــوال ومت القبــض عليــه بعــد‬\n  ‫ذلــك ومتكــن مــن الهــرب و نفــى مــا ســوى ذلــك وقــد انتهــى التحقيــق إلــى‬\n\n\n                                                                                      ‫‪36‬‬\n\f     ‫اتهــام املدعــى عليــه بتعاطــي احلبــوب املنبهــه واحملظــورة (االمفيتامــن)‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬اقــراره املنــوه عنــه املــدون علــى ص (‬\n     ‫‪ ) 22‬مــن امللــف املرفــق علــى اللفــه رقــم (‪ )1‬وبالبحــث عــن ســوابقه عثــر‬\n     ‫لــه علــى ثــاث ســوابق األولــى ســرقة كيابــل والثانيــة تســتر والثالثــة‬\n     ‫اســتعمال مخــدرات وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n     ‫أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب‬\n     ‫إثبــات إدانتــه مبــا أســند إليــه وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪)3‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا‬\n     ‫يلــي ‪ -1:‬بعقوبــة الســجن الــواردة يف الفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n     ‫(‪ )41‬مــن النظــام ‪ -2‬منعــه مــن الســفر وفقـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة‬\n                                                ‫رقــم (‪ )56‬مــن النظــام هكــذا ادعــى‬\n     ‫ا مــا ذكــره‬  ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n     ‫املدعــي العــام مــن قيامــي بتعاطــي احلبــوب احملظــورة فذلــك غيــر صحيــح‬\n     ‫والصحيــح أننــي كنــت أتعاطاهــا يف الســابق ثــم قبــض علــي ومت احلكــم‬\n     ‫علــي يف محكمــة اإلحســاء اجلزائيــة وبعــد ذلــك لــم أقــم بتعاطيهــا أبــد ًا‬\n     ‫وأمــا الســوابق فهــي صحيحــة لكنني تبت مــن تعاطي املخدرات هكذا‬\n     ‫أجــاب وبعــرض ذلــك علــى املدعــي العــام قال ما ذكــره املدعى عليه غير‬\n     ‫صحيــح والصحيــح مــا ذكــرت يف دعــواي مــن قيامــه بتعاطيهــا هكــذا‬\n     ‫أجــاب ثــم جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال بينتــي مــا‬\n     ‫جــاء يف أوراق املعاملــة ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى لفــة‬\n     ‫رقــم (‪ )1‬دفتــر ضبــط إجــراءات ص (‪ )22‬محضــر اســتجواب املدعــى‬\n     ‫عليــه املتضمــن تعاطيــه للحبــوب احملظــورة وبعــرض مــا ورد يف احملضــر‬\n     ‫علــى املدعــى عليــه قــال صحيــح أننــي قمــت بالتوقيع علــى احملضر لكن‬\n\n\n‫‪37‬‬\n\f‫ـاء علــى مــا تقــدم‬\n                    ‫لــم أكــن أعلــم مــا هــو مكتــوب فيــه هكــذا أجــاب فبنـ ً‬\n‫ـاء‬\n‫مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وإنــكاره للدعــوى وبنـ ً‬\n‫علــى إقــراره الــذي وقــع عليــه عنــد التحقيــق معــه وهــو بكامــل أهليتــه‬\n‫ـاء‬\n ‫املعتبــرة شــرع ًا ونظــر ًا لوجــود ســابقة مخــدرات علــى املدعــى عليــه وبنـ ً‬\n‫علــى الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبنــاء‬\n‫علــى املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ونظــر ًا لكــون حبــوب الكبتاجــون ليســت مســكرة‬\n‫والتقــاس علــى املســكر بــل خطرهــا عظيــم علــى اجلســم وهــي تتلــف‬\n‫العقــل كمــا قــرر ذلــك األطبــاء لــذا كلــه فقــد ثبــت لــدي تعاطــي املدعى‬\n‫عليــه للحبــوب احملظــورة وقــررت اآلتــي‪ :‬أوالً‪ :‬رد مطالبــة املدعــي العــام‬\n‫بتطبيــق الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n‫ـداء مــن‬\n        ‫لعــدم انطباقهــا‪ .‬ثانيـاً‪ :‬ســجن املدعــى عليــه ملــدة ثالثــة أشــهر ابتـ ً‬\n‫تاريــخ إيقافــه لقــاء تعاطيــه املــواد املخــدرة‪ .‬ثالثـاً‪ :‬منعــه مــن الســفر ملــدة‬\n‫ســنتني تبــدأ بعــد انتهــاء فتــرة الســجن املقــررة يف حقــه يف البنــد ثاني ـاً‪.‬‬\n‫وبــكل مــا تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n‫عليــه القناعــة باحلكــم وأمــا املدعــي العــام فقــرر االعتــراض واالكتفــاء‬\n‫بالئحــة الدعــوى العامــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                ‫محمــد‪ .‬حــرر يف ‪1434/2/119‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1434/3/25‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم‬\n‫‪ 3457784‬يف ‪1434/3/8‬ه ـ املتضمــن (لوحــظ‪ :‬أوالً‪ :‬أن املدعــى عليــه‬\n\n\n                                                                                           ‫‪38‬‬\n\f     ‫دفــع يف جوابــه بأنــه ســبق أن حكــم عليــه لــدى احملكمــة اجلزائيــة‬\n     ‫باإلحســاء ولــم جنــد أن فضيلتــه حتقــق مــن ذلــك وهــل مــا حكــم بــه‬\n     ‫عليــه قبــل هــذه الواقعــة أم ال ثاني ـاً‪ :‬مــا مســتند فضيلتــه يف احلكــم‬\n     ‫علــى املدعــى عليــه بالســجن مــا دام أنــه مــدان بالتعاطــي فعلــى فضيلتــه‬\n     ‫مالحظــة مــا ذكــر وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة إلكمــال‬\n     ‫الزمهــا واهلل املوفــق) عليــه أجيــب أصحــاب الفضيلــة بالنســبة للمالحظــة‬\n     ‫األولــى علــى فــرض صحــة مــا ذكــر املدعــى عليــه فــإن تلــك قضيــة وهــذه‬\n     ‫قضيــة أخــرى واملدعــى عليــه هنــا مطالــب بالتعزيــر فــا أرى فائــدة مــن‬\n     ‫التحقــق مــن ذلــك وأمــا بالنســبة للمالحظــة الثانيــة فــإن املســتند قــد‬\n     ‫ذكرتــه يف تســبيب احلكــم وهــو املــادة (‪ )30‬مــن الالئحــة التنفيذيــة‬\n     ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وكذلــك وجــود ســوابق‬\n     ‫لديــه منهــا ســابقة مخــدرات ونظــر ًا لكــون حبــوب الكبتاجــون ليســت‬\n     ‫مســكرة والتقــاس علــى املســكر وأضرارهــا علــى اجلســم كثيــرة‬\n     ‫حيــث ذكــر األطبــاء أن مــن أضرارهــا تلــف خاليــا املــخ واألعصــاب‬\n     ‫كمــا أنهــا تغيــر يف الضغــط الشــرياني وتغيــر يف نظــم القلــب وتغيــر يف‬\n     ‫الفعاليــة النفســية احلركيــة للمتعاطــي وقــد تتســبب يف احتشــاء الدمــاغ‬\n     ‫أو القلــب وضعــف احملاكمــة العقليــة وغيــر ذلــك مــن األضــرار ليس هذا‬\n     ‫محــل ذكرهــا وأمــرت برفــع املعاملــة إلــى محكمــة االســتئناف وبــاهلل‬\n     ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/3/25‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1434/05/01‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة الثامنــة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية برقــم ‪ 341034402‬يف ‪1434/04/23‬ه ـ وبرفقهــا‬\n     ‫القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم  يف ‪1434/04/17‬ه ـ‬\n\n\n‫‪39‬‬\n\f‫املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/05/01‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪40‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":33,"source_page_end":40,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"12ce59c66321de117dc6986b232c0e146bfd5cae8be7f2d8520fd5da58960565","normalized_text_hash":"cec7a78f8bb4abcb5194c101a7449e67e97adc9e60ee90336df23c2efab0989a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p33-3442047"},{"id":"d3da7d45-2c79-5012-bad2-165ff15cb56f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلبوب احملظورة «الترامادول» -الشروع يف إهداء احلبوب احملظورة -إقرار بسبق تعاطي احلشيش -تخفيف العقوبة لعدم وجود سوابق ولكون الترامادول يعرف بوصفة طبية خارج اململكة -إقامة حد املسكر -التعزير بالسجن واجللد واإلبعاد","document_number":"3436221","case_number":"3438818","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/12","year":"1434","subject":"مخدرات -تعاطي احلبوب احملظورة «الترامادول» -الشروع يف إهداء احلبوب احملظورة -إقرار بسبق تعاطي احلشيش -تخفيف العقوبة لعدم وجود سوابق ولكون الترامادول يعرف بوصفة طبية خارج اململكة -إقامة حد املسكر -التعزير بالسجن واجللد واإلبعاد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪    3436221 :‬تاريخه ‪1434/02/12 :‬هـ  ‬\n                             ‫رقم الدعوى ‪3438818 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪      3450134‬تاريخه‪1434/02/30 :‬هـ‬\n\n\n\n     ‫مخــدرات ‪ -‬تعاطــي احلبــوب احملظــورة «الترامــادول» ‪ -‬الشــروع يف‬\n     ‫إهــداء احلبــوب احملظــورة ‪ -‬إقــرار بســبق تعاطــي احلشــيش ‪ -‬تخفيــف‬\n     ‫العقوبــة لعــدم وجــود ســوابق ولكــون الترامــادول يعــرف بوصفــة طبيــة‬\n     ‫خــارج اململكــة ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن واجللــد واإلبعــاد‬\n                                                                         ‫عــن البــاد‪.‬‬\n\n\n\n\n     ‫ـاب‬      ‫ال ْمـ ُـر َو ْالَ ْي ِسـ ُـر َو ْ َ‬\n     ‫ال ْن َصـ ُ‬                                ‫نــا ْ َ‬                 ‫‪-1‬قولــه تعالــى ( َيــا َأ ُّي َهــا ا َّلذِ يـ َـن َ‬\n                                                          ‫آم ُنــوا ِإ َّ َ‬\n         ‫ـون ) ‪.‬‬‫ـوه َل َع َّل ُكـ ْـم ُت ْفل ُِحـ َ‬\n                                                  ‫اج َتن ُِبـ ُ‬‫الش ـ ْي َطانِ فَ ْ‬                                          ‫َو ْ َ‬\n                                                                                 ‫ال ْز َل ُم ِر ْ ٌجــس مِ ـ ْـن َع َمــلِ َّ‬\n                            ‫الح َها) ‪.‬‬  ‫‪-2‬قوله تعالى ( َوال ُت ْف ِس ُدوا ِف األرض َب ْع َد ِإ ْص ِ‬\n              ‫‪-3‬املواد (‪ )3/2‬و (‪ )41/1‬و (‪ )56/2‬من نظام مكافحة املخدرات ‪.‬‬\n           ‫‪-4‬برقية سمو وزير الداخلية رقم ‪ 36901‬وتاريخ ‪1432/06/13‬هـ ‪.‬‬\n                                                         ‫‪-5‬املادة (‪ )60‬من نظام مكافحة املخدرات ‪.‬‬\n\n\n\n\n     ‫توجيــه االتهــام للمدعــى عليــه املُقيــم بالشــروع يف إهــداء حبتــن مــن‬\n     ‫حبــوب الترامــادول احملظــورة‪ ،‬تعاطيــه لهــذه احلبــوب‪ ،‬تعاطــي احلشــيش‬\n     ‫املخــدر ‪ ،‬قبــض علــى املدعــى عليــه مــن قبــل مكافحــة املخــدرات إثــر‬\n     ‫بــاغ مــن أحــد املصــادر الســرية عــن قيــام املدعــى عليــه بإهــداء احلبــوب‬\n\n‫‪41‬‬\n\f‫احملظــورة‪ ،‬مت متكــن املصــدر مــن االتصــال باملــروج (املدعــى عليــه)‬\n‫وســماع رجــال الضبــط فحــوى املكاملــة التــي تضمنــت التفــاوض علــى‬\n‫إهــداء املصــدر حبــوب الترامــادول احملظــورة‪ ،‬مت االنتقــال للموقــع املتفق‬\n‫عليــه وخشــية مــن هــروب املدعــى عليــه مت القبــض عليــه قبــل إمتــام عمليــة‬\n‫اإلهــداء‪ ،‬عثــر مــع املدعــى عليــه حلبتــن مــن احلبــوب املنبهــة احملظــورة‬\n‫كمــا عثــر علــى اجلــوال املســتخدم يف عمليــة التنســيق‪ ،‬طلــب املدعــي‬\n‫العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبــة الســجن‬\n‫واجللــد والغرامــة واإلبعــاد ومصــادرة الهاتــف اجلــوال وإلغــاء شــريحته‬\n‫وذلــك وفــق نظــام مكافحــة املخــدرات وتعميــم وزارة الداخليــة‪ ،‬أنكــر‬\n‫املدعــى عليــه الشــروع يف اإلهــداء‪ ،‬أقــر بتعاطــي احلشــيش كمــا‬\n‫أقــر بتعاطــي حبــوب الترامــادول ودفــع بأنــه يســتخدمها وصفــة طبيــة‬\n‫كعــاج آلالم األســنان عنــد احلاجــة‪ ،‬صــدر احلكــم بصــرف النظــر عــن‬\n‫طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه بالشــروع يف إهــداء حبتــن‬\n‫مــن حبــوب الترامــادول مــع توجيــه التهمــة لــه يف ذلــك وإثبــات إدانتــه‬\n‫يف بقيــة مــا أســند إليــه‪ ،‬تخفيــف العقوبــه لعــدم وجــود ســوابق ولكــون‬\n‫الترامــادول يصــرف بوصفــه طبيــه يف جمهوريــة مصــر العربية‪،‬صــدر‬\n‫احلكــم بإقامــة حــد املســكر علــى املدعــى عليــه والتعزيــر بالســجن‬\n‫واجللــد واإلبعــاد عــن البــاد‪ ،‬صــدق احلكــم مــن محكــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪42‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n       ‫برقــم ‪ 3438818‬وتاريــخ ‪1434 /1/21‬ه ـ املقيــدة باحملكمــة برقــم‬\n       ‫‪ 34189566‬وتاريــخ ‪ 1434/1/21‬ه ـ واملتعلقــة بدعــوى املدعــي العــام‬\n       ‫‪ ............/‬ضــد ‪ .........../‬مصــري اجلنســية حســب إقامتــه الصــادرة مــن‬\n       ‫الدوادمــي برقــم (‪ )....‬ففــي يــوم  الثالثــاء ‪1434/ 1 / 27‬ه ـ فتحــت‬\n       ‫اجللســة الســاعة ‪  10 : 15‬وفيهــا حضــر  املدعــي العــام واملدعــى عليــه‬\n       ‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا‬\n       ‫يلــي ‪( :‬بصفتــي مدعيـ ًا عامــا يف دائــرة التحقيــق واإلدعاء العام مبحافظة‬\n       ‫القطيــف أدعــي علــى (‪ )....‬البالــغ مــن العمــر (‪ )31‬ســنة ‪ ،‬مصــري‬\n       ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ، )....‬غيــر محصــن ‪ ،‬موظــف‬\n       ‫أهلــي‪ ،‬قبــض عليــه بتاريــخ ‪1433/11/20‬ه ـ وأحيــل لســجن محافظــة‬\n       ‫القطيــف اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬هــ‪.‬‬\n       ‫حيــث أنــه بتاريــخ ‪1433/11/20‬ه ـ ورد بــاغ مــن أحــد املصــادر الســرية‬\n     ‫ملكافحــة املخــدرات بالدمــام عــن وجــود املدعــى عليــه يحمل اجلــوال رقم  ‬\n       ‫ويســكن بالـ ـ (‪ )....‬ويقــوم بإهــداء احلبــوب احملظــورة‪ .‬وباالطــاع علــى‬\n       ‫محضــر االتصــال املعــد مــن قبــل مكافحــة املخــدرات بالدمــام بتاريــخ‬\n       ‫‪1433/11/20‬ه ـ املتضمــن أنــه مت متكــن املصــدر الســري مــن االتصــال‬\n       ‫باملــروج وســماع رجــال الضبــط فحــوى املكاملــة التــي تضمنــت التفــاوض‬\n       ‫علــى إهــداء املصــدر حبــوب الترامــادول احملظــورة ‪ .‬وباالطــاع علــى‬\n       ‫محضــر القبــض املعــد مــن قبــل مكافحــة املخــدرات بالدمــام املتضمــن‬\n\n‫‪43‬‬\n\f‫أنــه مت االتصــال باملدعــى عليــه وطلــب منــه املصــدر حبتــان فــرد املدعــى‬\n‫عليــه أن معــه حبتــان وســيقوم بإعطائهــا للمصــدر ومت االتفــاق علــى‬\n‫مــكان عمليــة التســليم واالســتالم مبحافظــة (‪ )....‬وانتهــت املكاملــة ‪،‬‬\n‫وحتــرك أعضــاء الفرقــة القابضــة نحــو املــكان املتفــق عليــه وباالتصــال‬\n‫علــى املدعــى عليــه أفــاد أنــه موجــود عنــد أحــد املخططــات كــي يقــوم‬\n‫بتســليمه احلبــوب احملظــورة فــرد املصــدر بأنــه ســيحضر بعــد عــدة دقائــق‬\n‫وبعــد مشــاهدة املصــدر للمذكــور قــام باإلشــارة إليــه ألفــراد الفرقــة‬\n‫القابضــة ولكــون الســيارة يف وضــع التشــغيل وخشــية مــن هروبــه مت‬\n‫إرســال أحــد رجــال األمــن لــه لتمثيــل دور شــخص يريــد عمــل اشــتراك‬\n‫لســيارته ومت الســيطرة والقبــض عليــه وعثــر معــه علــى عــدد (‪ )2‬حبتــن‬\n‫مــن احلبــوب املنبهــة واحملظــورة كمــا عثــر علــى اجلــوال الــذي مت التنســيق‬\n‫معــه مــن خاللــه نــوع (‪ )....‬ويحمــل رقــم االتصــال (‪ .)....‬وورد التقريــر‬\n‫الكيمــاوي الشــرعي رقم‪4154‬وتاريخ‪1433/11/27‬ه ـ املتضمــن ثبوت‬\n‫إيجابيــة العينــات املضبوطــة لعقــار الترامــادول احملظــورة واملدرجــة يف‬\n‫اجلــدول األول فئــة (هــ) واملرفــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ .‬وبســماع أقــوال املدعــى عليــه األوليــة أقــر بحيازتــه للحبتــن‬\n‫املضبوطتــن معــه وأنــه يتعاطــى احلبــوب احملظــورة منــذ ســنتني ونصــف‬\n‫عنــد اللــزوم وأنــه يتعاطــى احلشــيش املخــدر أيضــا‪ .‬وباســتجواب املدعــى‬\n‫عليــه أقــر بتعاطيــه حبــوب الترامــادول وحيازتــه لهــا وأفــاد أنــاه يتعاطاهــا‬\n‫‪،‬كمــا أقــر بتعاطيــه احلشــيش املخــدر‪ .‬وقــد أســفر التحقيــق عــن اتهامــه‬\n‫بالشــروع يف إهــداء حبتــن مــن حبــوب الترامــادول احملظــورة وتعاطــي‬\n‫نوعهــا وتعاطــي احلشــيش املخــدر‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪-1‬إقــراره حتقيقــا املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪)3-2-1‬‬\n\n\n                                                                                       ‫‪44‬‬\n\f     ‫واملرفــق لفــة رقــم (‪-2 )12-11-10‬إقــراره بحيــازة احلبــوب احملظــورة‬\n     ‫وتعاطيــه لــه وللحشــيش املخــدر مبحضــر ســماع األقــوال األوليــة املنــوه‬\n     ‫عنــه واملــدون علــى الصفحــة رقــم (‪ )21‬واملرفــق لفــة رقــم (‪-3 )1‬مــا‬\n     ‫ورد يف محضــر البــاغ املنــوه عنــه مبحضــر االســتدالل واملــدون علــى‬\n     ‫الصفحــة رقم‪2‬واملرفــق لفــة رقــم (‪-4 )1‬مــا ورد يف محضــر القبــض‬\n     ‫مــن وقائــع املنــوه عنهــا واملدونــة علــى الصفحــة رقــم (‪ )12‬واملرفقــة‬\n     ‫لفــة رقــم (‪ -5 .)1‬مــا ورد يف محضــر االتصــال املنــوه عنــه واملــدون‬\n     ‫علــى الصفحــة رقم‪4‬واملرفقــة لفــة رقــم (‪ -6 )1‬مــا ورد يف التقريــر‬\n     ‫الكيمــاوي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪ .)16‬وبالبحــث‬\n     ‫عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجلة‪ .‬وحيــث إن‬\n     ‫مــا أقــدم عليــه املذكــور ‪-‬وهــو بكامــل أهليتــه املعتبــرة شــرعا‪ -‬فعــل‬\n     ‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب احلكــم عليــه مبــا يلــي‪:‬‬\n     ‫وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن‬\n                                                        ‫أوال‪ :‬إثبــات مــا أســند إليــه ً‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‬\n     ‫‪-1:‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n     ‫رقــم (‪ )38‬مــن النظــام مــع مراعــاة مقتضــى املــادة ‪ 62‬مــن ذات النظــام‬\n     ‫‪-2.‬إبعــاده عــن البــاد إعمــاال ملقتضــى الفقــرة رقــم (‪ )2‬مــن املــادة رقــم‬\n     ‫(‪ )56‬مــن النظــام‪ .‬ثانيــا‪ :‬مصــادرة الهاتــف اجلــوال العائــد للمدعــو نــوع‬\n     ‫(‪ )....‬ويحمــل رقــم االتصــال (‪ .)....‬والرقــم املصنعــي (‪ )....‬الســتخدامه‬\n     ‫يف الترويــج وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام‪،‬‬\n     ‫مــع املطالبــة بإســقاط شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس‬\n     ‫املدعــى عليــه وفقــا لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n     ‫‪1429/2/10-9‬هــ‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى علــى املدعى‬\n\n\n‫‪45‬‬\n\f  ‫عليــه أجــاب بقولــه أقــر بأنــي تعاطيــت احلشــيش الســنة املاضيــة مرتــن‬\n  ‫فقــط والثالثــة قبــل عــدة ســنوات وأقــر بأنــي تعاطيــت حبــوب الترامــادول‬\n  ‫لغــرض تخفيــف ألــم أســناني ولــم أكــن أعلــم أنــه محظــور وقــد حصلــت‬\n  ‫علــى هــذه احلبــوب مــن أحــد زمالئــي قبــل ســفره وعددهــا ســبع حبــات‬\n  ‫وقــد أعطانيهــا عندمــا أخبرتــه بأنــي أعانــي مــن ألــم باألســنان وأقــر‬\n  ‫بحيازتــي حبتــن مــن حبــوب الترامــادول وأمــا الشــروع يف اإلهــداء فإنــي‬\n  ‫أنكــره وال أقــر بــه وحقيقــة مــا حصــل مــع املصــدر أنــي أعمــل مديــرا‬\n  ‫ملعــرض واحــة املســتلزمات الطبيــة بالدمــام وكان بينــي وبــن املصــدر‬\n  ‫املذكــور يف الدعــوى تعامــل حيــث ســبق وأن أحضــرت لــه كرســيا‬\n  ‫متحــركا لوالدتــه املقعــدة وحفاظــات لكبــار الســن ثــم طلــب منــي‬\n  ‫حفاظــات وأحضرتهــا لــه ثــم طلــب منــي املــرة الثالثــة فأحضرتهــا لــه‬\n  ‫ومت القبــض علــي هــذا جوابــي وبعــرض ذلــك علــى املدعــي العــام قــال‬\n  ‫الصحيــح مــا جــاء يف دعــواي وبســؤاله البينــة قــال بينتــي ذكرتهــا يف‬\n  ‫الدعــوى وأطلــب رصدهــا هــذا جوابــي وباالطــاع على أدلــة املدعي العام‬\n  ‫وجــدت علــى اللفــات رقــم ‪ 12-10‬حتقيقــا مــع املدعــى عليــه يتضمــن مــا‬\n  ‫نصــه ‪ ( :‬س‪ .‬أنــت متهــم بإهــداء املؤثــرات العقليــة وتعاطــي املؤثــرات‬\n  ‫العقليــة وتعاطــي املــواد املخــدرة ؟ ج‪ /‬أتعاطــى الترامــادول كمســكن‬\n  ‫مصــروف لــي بوصفــة طبيــة ولــم أكــن أنــوي إهــداءه وتعاطيــت احلشــيش‬\n‫مــرة واحــدة‪ .‬س‪ /‬كــم رقــم جوالــك وهــل يســتخدمه أحــد غيــرك ؟ ج‪  /‬‬\n  ‫وهــو جوالــي اخلــاص وال يســتخدمه أحــد غيــري‪ .‬س‪ /‬مت االتصــال عليــك‬\n  ‫مــن قبــل مصــدر مكافحــة املخــدرات وتضمنــت املكاملــة التفــاوض‬\n  ‫علــى إهدائــك لــه حبــوب الترامــادول احملظــورة فمــا صحــة ذلــك؟ ج‪/‬‬\n  ‫غيــر صحيــح اتصــل علــي شــخص وطلــب منــي حبــوب ترامــادول حيــث‬\n\n\n                                                                                    ‫‪46‬‬\n\f     ‫ســألني حتديــدا هــل تعــرف أحــدا عنــده ترامــادول فأجبتــه بــا وقلــت لــه‬\n     ‫خلينــي أشــوف لــك ولــم أقــل لــه ســأعطيك حبــوب‪ .‬س‪ /‬ولكــن املكاملــة‬\n     ‫مســموعة مــن قبــل رجــال الضبــط ممــا يعنــي صحتهــا فمــا ردك ؟ ج‪/‬‬\n     ‫غيــر صحيــح‪ .‬س‪ /‬مت القبــض عليــك وعثــر علــى احلبــوب احملظــورة التــي‬\n     ‫كنــت تنــوي إهداءهــا فمــا صحــة ذلــك؟ ج‪ /‬مت ضبطــي مــع احلبــوب‬\n     ‫وهــي لــي بقصــد التعاطــي ألنــي أســتخدمها كمســكن وهــو موصــوف‬\n     ‫لــي بوصفــة طبيــة يف الســعودية ومصــر وســأحاول إحضــار الوصفــات‪.‬‬\n     ‫س‪ /‬مــا غرضــك مــن حيــازة هــذه احلبــوب؟ ج‪ /‬لتســكني آالم األســنان‬\n     ‫حيــث أنهــا مصروفــة لــي بوصفــة طبيــة‪ .‬س‪ /‬مــا أنــواع املخــدرات التــي‬\n     ‫تتعاطاهــا ومنــذ متــى؟ ج‪ /‬حبــوب الترامــادول كعــاج موصــوف لــي مــن‬\n     ‫الطبيــب وتعاطيــت احلشــيش املخــدر مــرة واحــدة فقــط‪ .‬س‪ /‬هــل ســبق‬\n     ‫وأن قمــت بإهــداء أو ترويــج أي مــن املخــدرات؟ ج‪ /‬ال‪ .‬س‪ /‬مــا ســبب‬\n     ‫حضــورك للموقــع إذا؟ ج‪ /‬كنــت جالســا أتعشــى يف املوقــع‪ .‬س‪ /‬ولكــن‬\n     ‫ورد يف محضــر القبــض أنــك حضــرت للموقــع الــذي حددتــه أنــت بعــد‬\n     ‫االتصــال بــك مــن قبــل املصــدر لكــي تقــوم بتســليمه احلبــوب فــا داعــي‬\n     ‫إلنــكارك؟ ج‪ /‬غيــر صحيــح‪ .‬س‪ /‬متــى آخــر مــرة زرت فيهــا املستشــفى‬\n     ‫لصــرف هــذه احلبــوب لــك؟ ج‪ /‬قبــل شــهر رمضــان أو يف رمضــان قبــل‬\n     ‫حوالــي شــهرين ونصــف أو ثالثــة تقريبــا وصــرف لــي شــريط ترامــادول‬\n     ‫يحتــوي علــى عشــر حبــات عنــد اللــزوم وال أتذكــر اســم املستشــفى‬\n     ‫وســأحاول إحضــار الوصفــة وعندمــا مت القبــض علــي عثــر معــي علــى‬\n     ‫أدويــة أخــرى مســكنة أيضــا فيفــادول وغيــره‪  .‬س‪ /‬هــل لديــك أقــوال‬\n     ‫أخــرى أو مــا تــود إضافتــه؟ ج‪ /‬ال‪ ).‬ا‪.‬ه ـ كمــا وجــدت علــى الصفحــة‬\n     ‫رقــم ‪ 4‬مــن دفتــر التحقيــق رقــم ‪ 1‬محضــر اتصــال يتضمــن مــا نصــه ‪( :‬‬\n\n\n‫‪47‬‬\n\f‫مت متكــن املصــدر الســري مــن االتصــال باملدعــو وســمع رجــال الضبــط‬\n‫فحــوى املكاملــة التــي تضمنــت التفــاوض علــى مــا يلــي ‪ :‬إهــداء املصــدر‬\n‫حبــوب ترامــادول مخــدرة ) ا‪.‬ه ـ كمــا وجــدت علــى الصفحــة رقم ‪ 12‬من‬\n‫دفتــر التحقيــق رقــم ‪ 1‬محضــر قبــض يتضمــن مــا نصــه ‪ (  :‬مت متكــن‬\n‫املصــدر مــن االتصــال علــى املدعــو وطلــب منــه حبــوب ترامــادول  مخــدرة‬\n                                                                      ‫علــى هاتفــه‬\n‫املوضــح يف البــاغ رقــم  وطلــب منــه فــر ّد املذكــور بــأن معــه حبتــان‬\n‫ســيقوم بإعطائهــا للمصــدر فوافــق املصــدر علــى ذلك واتفــق معه على أن‬\n‫تتــم عمليــة االســتالم والتســليم ب ــ(‪ )....‬وانتهــت املكاملــة وحتــرك أعضــاء‬\n‫الفرقــة نحــو املوقــع املتفــق عليــه يف عمليــة االســتالم والتســليم وعنــد‬\n‫وصولهــم قــام املصــدر باالتصــال علــى املذكــور وســؤاله عــن موقعــه‬\n‫فــرد املذكــور بأنــه ينتظــره يف أحــد املخططــات حتــى يقــوم بإعطائــه‬\n‫احلبــوب احملظــورة فــرد املصــدر بأنــه ســيأتيه بعــد عــدة دقائــق وبعــد‬\n‫مشــاهدة املصــدر للمذكــور قــام باإلشــارة إليــه ألعضــاء الفرقــة حيــث‬\n‫كان املذكــور متوقفــا علــى مركبــة مــن نــوع (‪ )....‬حتمــل لوحــة رقــم‬\n‫(‪ )....‬مبفــرده ولــم يكــن معــه أحــد وكان جالســا حتــت املقــود والســيارة‬\n‫يف وضــع التشــغيل وخوفــا مــن هروبــه قــام أحــد أفــراد الفرقــة بالذهــاب‬\n‫إليــه وطلــب منــه اشــتراك ســيارة والتمويــه عليــه حتــى يقــوم بفتــح النافــذة‬\n‫وفــور اســتجابته لرجــل األمــن وإجــراء حديــث معــه قــام بفتــح النافــذة‬\n‫عندهــا قــام رجــل األمــن بالســيطرة عليــه وقــام باقــي أعضــاء الفرقــة‬\n‫بالقبــض عليــه وتفتيشــه حيــث عثــر بيــده علــى مــا كان ســيقوم بإهدائــه‬\n‫للمصــدر وهــي حبــوب بيضــاء اللــون عددهــا حبتــان يشــتبه أن تكــون‬\n‫مــن احلبــوب املخــدرة كمــا عثــر معــه علــى هاتــف جــوال (‪ )....‬يحمــل‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫رقــم (‪ )....‬الــذي مت التنســيق عليــه عــدا ذلــك لــم يعثــر معــه علــى أي مــن‬\n     ‫احملظــورات واتضــح أنــه يدعــى (‪ )....‬مصــري اجلنســية مبوجــب اإلقامــة‬\n     ‫رقــم (‪ )....‬وبتفتيــش الســيارة التــي كانــت معــه لــم يعثــر علــى أي مــن‬\n     ‫احملظــورات ) ا‪.‬ه ـ وبتصفــح املعاملــة وجــدت علــى اللفــة رقــم ‪ 16‬التقريــر‬\n     ‫الكيمــاوي رقــم ‪ 4154‬ك ش املتضمــن ‪ ( :‬إيجابيــة املضبوطــات ملــادة‬\n     ‫الترامــادول واملــدرج يف اجلــدول ‪ 1‬فئــة ه ـ مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة) ا‪.‬ه ـ وبعــرض األدلــة علــى املدعــى عليــه قــال أمــا‬\n     ‫التحقيــق فإجاباتــي الــواردة فيــه كلهــا صحيحــة ووعــدي لــه بأنــي‬\n     ‫ســأبحث لــه عــن حبــوب ترمــادول كان بســبب أنــي ال أريــد خســارته‬\n     ‫كزبــون وإال فأنــا يف احلقيقــة ال أعــرف أحــدا عنــده هــذه احلبــوب  وأمــا‬\n     ‫مــا ورد يف محضــر االتصــال ومحضــر القبــض واتهامــي بالشــروع يف‬\n     ‫إهــداء حبــوب الترامــادول فهــو غيــر صحيــح هــذا جوابــي وبســؤال‬\n     ‫املدعــي العــام زيــادة بينــة وعــد بإحضــار الفرقــة القابضــة ورفعــت اجللســة‬\n     ‫لذلــك ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه ولــم يحضــر‬\n     ‫الشــهود وطلــب املدعــي العــام مهلــة أخــرى إلحضارهــم فأجبتــه لطلبــه‬\n     ‫وأفهمتــه بأنهــا املهلــة األخيــرة ويف جلســة أخــرى حضــر  املدعــي العــام‬\n     ‫واملدعــى عليــه ولــم يحضــر الشــهود وبســؤال املدعــى عليــه عــن مصــدر‬\n     ‫حبــوب الترامــادول أجــاب بقولــه حصلــت عليهــا يف الســعودية مــن أحــد‬\n     ‫زمالئــي وقــد ســافر إلــى مصــر وقــد صــرف لــي أحــد األطبــاء يف مصــر‬\n     ‫قبــل ثــاث ســنوات نوعــا مــن الترامــادول اســمه ( ألتــرا دول ) أللــم‬\n     ‫األســنان وال أعلــم أيــن هــي هــذه الوصفــة اآلن وحينمــا قدمــت للســعودية‬\n     ‫أحضــرت معــي شــريطني منــه وكنــت اســتخدمهما عنــد احلاجــة وقــد‬\n     ‫انتهيــا علمــا بــأن مــا ذكرتــه يف هيئــة التحقيــق مــن أنــه مصــروف لــي‬\n\n\n‫‪49‬‬\n\f‫بوصفــة طبيــة مــن داخــل الســعودية مخالــف للواقــع وقــد أفــدت احملقــق‬\n‫بذلــك بســبب خــويف علــى زميلــي الــذي ســلمني احلبــوب هــذا جوابــي‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬\n‫بتعاطــي الترامــادول واحلشــيش املخــدر وأقــر بحيــازة حبتــن مــن حبــوب‬\n‫الترامــادول بقصــد التعاطــي وأقــر بأنــه حصــل عليهــا مــن أحــد زمالئــه‬\n‫ولــم يقــدم وصفــات طبيــة تثبــت مــا ذكــره مــن كونهــا مصروفــة لــه عــن‬\n‫طريــق أحــد األطبــاء وبنــاء علــى اختــاف إفاداتــه بشــأن الوصفــة الطبيــة‬\n‫حتقيقــا ويف مجلــس القضــاء وحيــث أنكــر املدعــى عليــه الشــروع يف‬\n‫اإلهــداء ولــم يقــدم املدعــي العــام بينــة موصلــة علــى ذلــك وألن وعــد‬\n‫املدعــى عليــه للمصــدر بالبحــث لــه عــن احلبــوب ثــم القبــض عليــه وهــي‬\n‫بحيازتــه قرينــة علــى قصــد الشــروع يف اإلهــداء ولقولــه (يــا أيهــا الذيــن‬\n‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n‫فاجتنبــوه لعلكــم تفلحــون )  وقولــه ( وال تفســدوا يف األرض بعــد‬\n‫إصالحهــا ) وبنــاء علــى املــواد ‪ 2/3‬و ‪ 1/41‬و ‪ 2/56‬مــن نظــام مكافحــة‬\n‫املخــدرات ولكــون املدعــى عليــه ليــس مــن أربــاب الســوابق وألن هــذه‬\n‫احلبــوب تصــرف بوصفــات طبيــة يف جمهوريــة مصــر حســب مــا ورد يف‬\n‫برقيــة وزيــر الداخليــة رقــم ‪ 36901‬يف ‪1432/6/13‬ه ـ املرفــق نســخة‬\n‫منهــا باملعاملــة وكونهــا كذلــك يهــون مــن شــأن تداولهــا بــن مــن يحمــل‬\n‫جنســية ذلــك البلــد  وهــذان األمــران يخــوالن املدعــى عليــه  االســتفادة‬\n                                                     ‫مــن املــادة ‪ 60‬مــن  النظــام‬\n‫فقــد حكمــت مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه بحيــازة حبتــن‬\n‫مــن حبــوب الترامــادول بقصــد التعاطــي ومعاقبتــه لذلــك بســجنه مــدة‬\n‫شــهر واحــد وإبعــاده مــن البــاد بعــد تنفيــذ األحــكام اجلنائيــة الصــادرة‬\n\n\n                                                                                       ‫‪50‬‬\n\f     ‫عليــه ‪-2‬ثبــوت إدانتــه بتعاطــي احلشــيش املخــدر وحبــوب الترامــادول‬\n     ‫ومعاقبتــه بجلــده ثمانــن جلــدة حــد املســكر أمــام مــأ  مــن النــاس‬\n     ‫‪-3‬صــرف النظــر عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه‬\n     ‫بالشــروع يف إهــداء حبتــن مــن حبــوب الترامــادول مــع توجــه التهمــة‬\n     ‫عليــه بذلــك وتعزيــره للشــبهة بســجنه مــدة ســتة أشــهر وجلــده خمســن‬\n     ‫جلــدة دفعــة واحــدة وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n     ‫عــدم قناعتــه ورغبتــه رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة‬\n     ‫اعتراضيــة وقــرر املدعــى عليــه قناعتــه  وبــاهلل التوفيــق وقــد مت االنتهــاء‬\n     ‫مــن حتريــره يف متــام الســاعة ‪ 10 : 00‬مــن يــوم الثالثــاء ‪1434/ 2 / 12‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم  الســبت ‪1434/ 3 / 14‬هــ  فتحــت‬\n     ‫اجللســة الســاعة ‪  10 : 30‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n     ‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقة الشــرقية رقم ‪3450134‬‬\n     ‫يف ‪1434/2/30‬ه ـ املتضمــن املصادقــة علــى احلكــم  وبــاهلل التوفيــق‬\n                       ‫وقــد مت االنتهــاء مــن حتريــره يف متــام الســاعة ‪.  10 : 40‬‬\n\n\n\n\n‫‪51‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":41,"source_page_end":51,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"af8a8844a233e41e3243e117310e939a5150d0c153d4b7c34e3150335a6522fb","normalized_text_hash":"f7ef9f4cc1993158eb569feed6c59910ba9bb9b92ed1322055a4580de821b5e1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p41-3436221"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
